            fastwalk_route=route,
            fastwalk_origin_actions=("get all.pie", "eat pie", "drink skin"),
            fastwalk_hunt_stops=tuple(hunt_stops),
            fastwalk_kill_limit=1,
            fastwalk_train_before_departure=True,
