def _checkpoint_state(checkpoint: Any) -> dict[str, Any]:
    if checkpoint is None:
        return {}
    return dict(json.loads(checkpoint["state_json"]))


def _progress_state_is_valid(
    state: Mapping[str, Any],
    *,
    require_level: bool = False,
) -> bool:
    """Reject impossible DD4 progress before it can satisfy a target."""
    level = state.get("level")
    if level is None:
        return not require_level
    if (
        not isinstance(level, (int, float))
        or isinstance(level, bool)
        or int(level) != level
        or not 1 <= int(level) <= 100
    ):
        return False
    for key in ("xp", "max_xp", "xp_to_next_level"):
        value = state.get(key)
        if value is not None and (
            not isinstance(value, (int, float))
            or isinstance(value, bool)
            or value < 0
        ):
            return False
    xp = state.get("xp")
    max_xp = state.get("max_xp")
    return not (
        isinstance(xp, (int, float))
        and isinstance(max_xp, (int, float))
        and max_xp < xp
    )


def _reconcile_invalid_progress_checkpoint(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Any | None,
) -> Any | None:
    if checkpoint is None:
        return None
    current_state = _checkpoint_state(checkpoint)
    if _progress_state_is_valid(current_state):
        return checkpoint
    checkpoint_id = int(checkpoint["id"])
    prior_checkpoint = None
    for candidate in reversed(storage.list_campaign_checkpoints(campaign_id)):
        if int(candidate["id"]) >= checkpoint_id:
            continue
        candidate_state = _checkpoint_state(candidate)
        if _progress_state_is_valid(candidate_state):
            prior_checkpoint = (candidate, candidate_state)
            break
    if prior_checkpoint is None:
        storage.finish_campaign(
            campaign_id,
            status="ready",
            error=(
                "Invalid progress checkpoint quarantined; no earlier valid "
                "checkpoint was available."
            ),
        )
        return None
    prior, prior_state = prior_checkpoint
    prior_state = {
        **prior_state,
        _INVALID_PROGRESS_QUARANTINE_KEY: checkpoint_id,
    }
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=prior["segment_id"],
        run_id=prior["run_id"],
        phase=str(prior["phase"]),
        reason="invalid_progress_checkpoint_repaired",
        state=prior_state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"Invalid progress checkpoint {checkpoint_id} quarantined; "
            f"resumed from valid checkpoint {int(prior['id'])}."
        ),
    )
    return storage.get_latest_campaign_checkpoint(campaign_id)


def _run_matches_character(run: Any, character_name: str) -> bool:
    suffixes = (
        f":{character_name}".casefold(),
        f"-{character_name}".casefold(),
    )
    return str(run["scenario_name"]).casefold().endswith(suffixes)


def _run_for_failed_segment(
    storage: RunStorage,
    segment: Any,
    *,
    character_name: str,
) -> Any | None:
    """Find the failed runner created inside one campaign segment window."""
    try:
        segment_started = datetime.fromisoformat(segment["started_at"])
        segment_finished = (
            datetime.fromisoformat(segment["finished_at"])
            if segment["finished_at"]
            else None
        )
    except (TypeError, ValueError):
        return None
    for run in storage.list_runs(limit=1000):
        if not _run_matches_character(run, character_name):
            continue
        if str(run["status"]) != "failed":
            continue
        try:
            run_started = datetime.fromisoformat(run["started_at"])
        except (TypeError, ValueError):
            continue
        if run_started < segment_started:
            continue
        if segment_finished is not None and run_started > segment_finished:
            continue
        return run
    return None


def _reconcile_failed_segment_progress(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Any,
    *,
    character_name: str,
) -> bool:
    """Repair an old failed segment whose runner recorded an objective kill."""
    segment_id = checkpoint["segment_id"]
    if segment_id is None:
        return False
    segment = next(
        (
            row
            for row in _runtime_campaign_segments(storage, campaign_id)
            if int(row["id"]) == int(segment_id)
        ),
        None,
    )
    if segment is None or segment["status"] != "failed":
        return False
    run = _run_for_failed_segment(
        storage,
        segment,
        character_name=character_name,
    )
    if run is None:
        return False
    objective_kills = _objective_kills_for_execution(
        storage,
        int(run["id"]),
        execution=str(segment["phase"]),
    )
    if not isinstance(objective_kills, list) or not objective_kills:
        return False
    start_state = json.loads(segment["start_state_json"] or "{}")
    current_state = _run_latest_state(storage, int(run["id"])) or start_state
    end_state = {
        **_campaign_segment_end_state(
            start_state,
            current_state,
            execution=str(segment["phase"]),
        ),
        "campaign_completed_kills": objective_kills,
        "campaign_objective_kills": objective_kills,
        "campaign_last_policy": str(segment["phase"]),
        "campaign_policy_revision": _CAMPAIGN_POLICY_REVISION,
    }
    run_id = int(run["id"])
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=run_id,
        end_state=end_state,
        command_count=storage.count_events(run_id, kind="command"),
        duration_seconds=_run_duration(run),
        error=segment["error"],
    )
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=run_id,
        phase=str(segment["phase"]),
        reason="segment_failed_progress_reconciled",
        state=end_state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"{segment['phase']} progress reconciled from failed run "
            f"{run_id} after {len(objective_kills)} objective kill(s)."
        ),
    )
    return True


def _reconcile_failed_source_ranked_watchdog(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Any,
    *,
    character_name: str,
) -> bool:
    """Convert a legacy source-route watchdog failure into a rotation checkpoint."""
    segment_id = checkpoint["segment_id"]
    if segment_id is None:
        return False
    segment = next(
        (
            row
            for row in _runtime_campaign_segments(storage, campaign_id)
            if int(row["id"]) == int(segment_id)
        ),
        None,
    )
    if not (
        segment is not None
        and segment["status"] == "failed"
        and str(segment["phase"]).startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and _is_source_ranked_watchdog_failure(segment["error"])
    ):
        return False
    run = _run_for_failed_segment(
        storage,
        segment,
        character_name=character_name,
    )
    if run is None:
        return False
    objective_kills = _objective_kills_for_execution(
        storage,
        int(run["id"]),
        execution=str(segment["phase"]),
    )
    if isinstance(objective_kills, list) and objective_kills:
        # The ordinary failed-progress reconciliation must retain a confirmed
        # kill before this route-specific repair is considered.
        return False
    start_state = json.loads(segment["start_state_json"] or "{}")
    current_state = _run_latest_state(storage, int(run["id"])) or start_state
    end_state = _campaign_segment_end_state(
        start_state,
        current_state,
        execution=str(segment["phase"]),
    )
    end_state = _source_ranked_watchdog_failure_state(
        end_state,
        policy_id=str(segment["phase"]),
        error=str(segment["error"] or ""),
    )
    run_id = int(run["id"])
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=run_id,
        end_state=end_state,
        command_count=storage.count_events(run_id, kind="command"),
        duration_seconds=_run_duration(run),
        error=segment["error"],
    )
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=run_id,
        phase=str(segment["phase"]),
        reason="segment_route_watchdog",
        state=end_state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"{segment['phase']} route watchdog quarantined from failed "
            f"run {run_id}; campaign rotation resumed."
        ),
    )
    return True


def _reconcile_failed_maintenance_route_watchdog(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Any,
    *,
    character_name: str,
) -> bool:
    """Repair a failed optional route before the next campaign invocation."""
    segment_id = checkpoint["segment_id"]
    if segment_id is None:
        return False
    segment = next(
        (
            row
            for row in _runtime_campaign_segments(storage, campaign_id)
            if int(row["id"]) == int(segment_id)
        ),
        None,
    )
    phase = str(segment["phase"]) if segment is not None else ""
    if not (
        segment is not None
        and segment["status"] == "failed"
        and phase in {
            "forest-bear-claws-upgrade-10-29",
            "thalos-long-dagger-upgrade-10-29",
            "recover-daycare-ring",
        }
        and _is_source_ranked_watchdog_failure(segment["error"])
    ):
        return False
    run = _run_for_failed_segment(
        storage,
        segment,
        character_name=character_name,
    )
    if run is None:
        return False
    execution = (
        "upgrade-piercing-weapon"
        if phase
        in {
            "forest-bear-claws-upgrade-10-29",
            "thalos-long-dagger-upgrade-10-29",
        }
        else phase
    )
    objective_kills = _objective_kills_for_execution(
        storage,
        int(run["id"]),
        execution=execution,
    )
    if isinstance(objective_kills, list) and objective_kills:
        return False
    start_state = json.loads(segment["start_state_json"] or "{}")
    current_state = _run_latest_state(storage, int(run["id"])) or start_state
    end_state = _campaign_segment_end_state(
        start_state,
        current_state,
        execution=execution,
    )
    end_state = _maintenance_route_watchdog_failure_state(
        end_state,
        policy_id=phase,
        execution=execution,
        boot_id=end_state.get("world_boot_id") or run["boot_id"],
        error=str(segment["error"] or ""),
    )
    run_id = int(run["id"])
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=run_id,
        end_state=end_state,
        command_count=storage.count_events(run_id, kind="command"),
        duration_seconds=_run_duration(run),
        error=segment["error"],
    )
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=run_id,
        phase=str(segment["phase"]),
        reason="segment_route_watchdog",
        state=end_state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"{segment['phase']} optional route watchdog quarantined from "
            f"failed run {run_id}; campaign rotation resumed."
        ),
    )
    return True


def _repair_reconciled_campaign_metadata(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Any,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Restore metadata lost by an older failed-segment reconciliation."""
    if checkpoint is None:
        return state
    reconciled_checkpoints = [
        row
        for row in _runtime_campaign_checkpoints(storage, campaign_id)
        if row["reason"] == "segment_failed_progress_reconciled"
        and row["segment_id"] is not None
    ]
    if not reconciled_checkpoints:
        return state
    segments = sorted(
        _runtime_campaign_segments(storage, campaign_id),
        key=lambda row: int(row["sequence"]),
    )
    reconciled_segments = [
        next(
            (
                segment
                for segment in segments
                if int(segment["id"]) == int(checkpoint["segment_id"])
            ),
            None,
        )
        for checkpoint in reconciled_checkpoints
    ]
    reconciled_segments = [segment for segment in reconciled_segments if segment]
    if not reconciled_segments:
        return state
    reconciled_segment_ids = {
        int(segment["id"]) for segment in reconciled_segments
    }
    first_reconciled = min(
        reconciled_segments,
        key=lambda row: int(row["sequence"]),
    )
    historical_results: dict[str, dict[str, Any]] = {}
    historical_cooldowns: dict[str, int] = {}
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    inferred_cleared_research_policies: set[str] = set()
    for segment in segments:
        if int(segment["sequence"]) < int(first_reconciled["sequence"]):
            continue
        start_state = json.loads(segment["start_state_json"] or "{}")
        end_state = json.loads(segment["end_state_json"] or "{}")
        if (
            int(segment["id"]) not in reconciled_segment_ids
            and str(segment["status"]) in {"ready", "success"}
        ):
            start_results = _campaign_research_results(start_state)
            end_results = _campaign_research_results(end_state)
            for policy_id, result in start_results.items():
                if result.get("absent") and policy_id not in end_results:
                    inferred_cleared_research_policies.add(policy_id)
            for policy_id, result in end_results.items():
                if (
                    policy_id == str(segment["phase"])
                    or result != start_results.get(policy_id)
                ):
                    inferred_cleared_research_policies.discard(policy_id)
        for historical_state in (start_state, end_state):
            historical_results.update(
                _campaign_research_results(historical_state)
            )
            cooldowns = historical_state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
            if isinstance(cooldowns, dict):
                historical_cooldowns.update(
                    {
                        str(policy_id): int(remaining)
                        for policy_id, remaining in cooldowns.items()
                    }
                )
        if end_state.get("campaign_fastwalk_crowded") or str(
            end_state.get("campaign_fastwalk_abort_reason") or ""
        ).startswith("field room contained "):
            historical_results.pop(str(segment["phase"]), None)
            historical_cooldowns.pop(str(segment["phase"]), None)
    cleared_research_policies.update(inferred_cleared_research_policies)
    first_start_state = json.loads(
        first_reconciled["start_state_json"] or "{}"
    )
    repaired = _campaign_segment_end_state(
        first_start_state,
        state,
        execution=str(first_reconciled["phase"]),
    )
    repaired = _clear_crowd_absence_marker(repaired)
    current_results = _campaign_research_results(repaired)
    current_state_results = _campaign_research_results(state)
    current_reboot_crowd_policies = {
        policy_id
        for policy_id, result in current_state_results.items()
        if (
            result.get("crowded") is True
            and result.get("boot_id") == state.get("world_boot_id")
        )
    }
    inferred_cleared_research_policies.difference_update(
        current_reboot_crowd_policies
    )
    cleared_research_policies.difference_update(
        current_reboot_crowd_policies
    )
    cleared_research_policies.difference_update(
        set(current_state_results).difference(
            inferred_cleared_research_policies
        )
    )
    for policy_id in cleared_research_policies:
        historical_results.pop(policy_id, None)
        historical_cooldowns.pop(policy_id, None)
        current_results.pop(policy_id, None)
    historical_results.update(current_results)
    if historical_results:
        repaired["campaign_research_results"] = historical_results
    else:
        repaired.pop("campaign_research_results", None)
    current_cooldowns = repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
    if historical_cooldowns or isinstance(current_cooldowns, dict):
        merged_cooldowns = dict(historical_cooldowns)
        if isinstance(current_cooldowns, dict):
            merged_cooldowns.update(
                {
                    str(policy_id): int(remaining)
                    for policy_id, remaining in current_cooldowns.items()
                }
            )
        for policy_id in cleared_research_policies:
            merged_cooldowns.pop(policy_id, None)
        if merged_cooldowns:
            repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = merged_cooldowns
        else:
            repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if cleared_research_policies:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    if repaired == state:
        return state
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=checkpoint["segment_id"],
        run_id=checkpoint["run_id"],
        phase=str(checkpoint["phase"]),
        reason=_CAMPAIGN_METADATA_REPAIRED_REASON,
        state=repaired,
    )
    return repaired


def _repair_confirmed_research_kills(
    storage: RunStorage,
    campaign_id: int,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Promote old hunt results whose run already records the objective kill."""
    results = _campaign_research_results(state)
    repaired_results = dict(results)
    changed = False
    repaired_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    repaired_crowd_cooldowns = dict(
        state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    repaired_source_ranked_crowd_attempts = dict(
        state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    current_boot_id = state.get("world_boot_id")
    explicit_retry_policy_ids: set[str] = set()
    existing_retry_marker = state.get(_EXPLICIT_RESEARCH_RETRY_KEY)
    if (
        current_boot_id is not None
        and isinstance(existing_retry_marker, Mapping)
        and existing_retry_marker.get("boot_id") == current_boot_id
    ):
        explicit_retry_policy_ids.update(
            str(policy_id)
            for policy_id in existing_retry_marker.get("policy_ids", ())
        )
    original_cleared_research_policies = set(cleared_research_policies)
    if current_boot_id is not None:
        # Older reconnect repair could resurrect a positive crowd route after
        # a reset retry had cleared it. Recover that intent from the durable
        # same-reboot checkpoint history so existing campaigns migrate safely.
        for checkpoint in _runtime_campaign_checkpoints(storage, campaign_id):
            if checkpoint["reason"] != "research_policy_retried":
                # Only an explicit retry checkpoint records a new clear
                # decision. Metadata, segment-complete, and dispatch snapshots
                # contain derived sets that can resurrect stale routes.
                continue
            try:
                checkpoint_state = json.loads(
                    checkpoint["state_json"] or "{}"
                )
            except (TypeError, json.JSONDecodeError):
                continue
            if checkpoint_state.get("world_boot_id") != current_boot_id:
                continue
            checkpoint_retry_policy_ids = {
                str(policy_id)
                for policy_id in checkpoint_state.get(
                    _CLEARED_RESEARCH_POLICIES_KEY,
                    (),
                )
            }
            cleared_research_policies.update(checkpoint_retry_policy_ids)
            explicit_retry_policy_ids.update(checkpoint_retry_policy_ids)
    if cleared_research_policies != original_cleared_research_policies:
        changed = True
    retry_marker = None
    if current_boot_id is not None and explicit_retry_policy_ids:
        retry_marker = {
            "boot_id": current_boot_id,
            "policy_ids": sorted(explicit_retry_policy_ids),
        }
    if retry_marker is None:
        if _EXPLICIT_RESEARCH_RETRY_KEY in state:
            changed = True
    elif state.get(_EXPLICIT_RESEARCH_RETRY_KEY) != retry_marker:
        changed = True
    latest_segments: dict[str, Any] = {}
    segments_by_phase: dict[str, list[Any]] = {}
    for segment in _runtime_campaign_segments(storage, campaign_id):
        policy_id = str(segment["phase"])
        latest_segments[policy_id] = segment
        segments_by_phase.setdefault(policy_id, []).append(segment)
    for policy_id, result in results.items():
        segment = latest_segments.get(policy_id)
        if segment is None:
            continue
        if not isinstance(result, dict) or not isinstance(
            result.get("completed_kill"), bool
        ):
            continue
        end_state = json.loads(segment["end_state_json"] or "{}")
        objective_kills = _segment_objective_kills(storage, segment)
        completed_kill = bool(
            isinstance(objective_kills, list) and objective_kills
        )
        if end_state.get("campaign_died_during_segment"):
            total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
                objective_kills
            )
            fatal_result: dict[str, Any] = {
                "observed": True,
                "viable": False,
                "completed_kill": False,
                "fatal_failure": True,
                "boot_id": end_state.get("world_boot_id"),
                "level": _level(end_state),
            }
            if completed_kill:
                fatal_result["objective_kill_observed"] = True
            if completed_kill and explicit_xp:
                fatal_result["objective_xp"] = total_xp
                fatal_result["max_objective_kill_xp"] = max_kill_xp
            if repaired_results.get(policy_id) != fatal_result:
                repaired_results[policy_id] = fatal_result
                changed = True
            continue
        if result.get("required_object_acquired") is True:
            # Resource policies may kill a carrier while proving an object
            # acquisition.  Their durable result is viable, but it is not
            # hunt proof and must not be promoted by the kill ledger.
            if (
                result.get("completed_kill") is not False
                or result.get("viable") is not True
            ):
                repaired_results[policy_id] = {
                    **result,
                    "completed_kill": False,
                    "viable": True,
                }
                changed = True
            continue
        abort_reason = str(end_state.get("campaign_fastwalk_abort_reason") or "")
        crowd_only_segment = bool(
            end_state.get("campaign_fastwalk_crowded")
            or any(
                abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        )
        if (
            not completed_kill
            and result.get("completed_kill") is True
            and result.get("viable") is True
            and crowd_only_segment
        ):
            # A crowd-only retry is not newer negative hunt evidence. Keep
            # the prior positive result so startup repair converges instead
            # of oscillating until the later crowd/resource repairs run.
            continue
        if result.get("completed_kill") == completed_kill:
            continue
        repaired_results[policy_id] = {
            **result,
            "observed": bool(result.get("observed")) or completed_kill,
            "viable": completed_kill,
            "completed_kill": completed_kill,
        }
        changed = True

    # A later crowd checkpoint can remove a positive result even though the
    # successful hunt segment and its objective kill remain durable. Recover
    # that evidence across crowd-only retries, but never carry it across a
    # reboot or over a newer absent, hazardous, or failed hunt.
    for policy_id, phase_segments in segments_by_phase.items():
        positive_evidence: dict[str, Any] | None = None
        latest_crowd_evidence = False
        for segment in sorted(
            phase_segments,
            key=lambda row: int(row["sequence"]),
        ):
            if str(segment["status"]) not in {"ready", "success"}:
                positive_evidence = None
                latest_crowd_evidence = False
                continue
            try:
                end_state = json.loads(segment["end_state_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                end_state = {}
            objective_kills = _segment_objective_kills(storage, segment)
            historical_result = _campaign_research_results(end_state).get(
                policy_id
            )
            if (
                isinstance(historical_result, Mapping)
                and historical_result.get("required_object_acquired") is True
            ):
                # An acquisition segment may include the carrier kill that
                # supplied the object.  It is not hunt evidence and must not
                # be restored as a positive kill on reconnect.
                positive_evidence = None
                latest_crowd_evidence = False
                continue
            if isinstance(objective_kills, list) and objective_kills:
                if end_state.get("campaign_died_during_segment"):
                    positive_evidence = None
                    latest_crowd_evidence = False
                    continue
                boot_id = (
                    historical_result.get("boot_id")
                    if isinstance(historical_result, dict)
                    else None
                ) or end_state.get("world_boot_id")
                if (
                    isinstance(historical_result, dict)
                    and historical_result.get("viable") is True
                    and (
                        state.get("world_boot_id") is None
                        or boot_id == state.get("world_boot_id")
                    )
                ):
                    positive_evidence = {
                        "result": historical_result,
                        "boot_id": boot_id,
                    }
                    abort_reason = str(
                        end_state.get("campaign_fastwalk_abort_reason") or ""
                    )
                    latest_crowd_evidence = bool(
                        end_state.get("campaign_fastwalk_crowded")
                        or any(
                            abort_reason.startswith(prefix)
                            for prefix in _FIELD_CROWD_ABORT_PREFIXES
                        )
                    )
                    continue
                positive_evidence = None
                latest_crowd_evidence = False
                continue
            if positive_evidence is not None:
                abort_reason = str(
                    end_state.get("campaign_fastwalk_abort_reason") or ""
                )
                if end_state.get("campaign_fastwalk_crowded") or any(
                    abort_reason.startswith(prefix)
                    for prefix in _FIELD_CROWD_ABORT_PREFIXES
                ):
                    latest_crowd_evidence = True
                    continue
                positive_evidence = None
                latest_crowd_evidence = False
        if positive_evidence is None:
            continue
        if policy_id in cleared_research_policies:
            # A bounded reset retry intentionally retired this route for the
            # current reboot. Do not resurrect older positive evidence before
            # the next source-ranked rotation has had a chance to run.
            continue
        current_result = results.get(policy_id)
        current_result_is_positive = (
            isinstance(current_result, Mapping)
            and current_result.get("boot_id")
            == positive_evidence.get("boot_id")
            and current_result.get("viable") is True
            and current_result.get("completed_kill") is True
        )
        if current_result_is_positive:
            # The current checkpoint is newer than the segment evidence. Keep
            # its objective XP and other live metadata; historical evidence is
            # only a fallback for a missing or non-positive result.
            recovered_result = dict(current_result)
            if latest_crowd_evidence:
                recovered_result["crowded"] = True
        else:
            recovered_result = {
                **positive_evidence["result"],
                "observed": True,
                "viable": True,
                "completed_kill": True,
            }
        if repaired_results.get(policy_id) != recovered_result:
            repaired_results[policy_id] = recovered_result
            changed = True
        if policy_id in repaired_cooldowns:
            repaired_cooldowns.pop(policy_id, None)
            changed = True
        if policy_id in repaired_crowd_cooldowns and not latest_crowd_evidence:
            repaired_crowd_cooldowns.pop(policy_id, None)
            changed = True
        if policy_id in cleared_research_policies:
            cleared_research_policies.discard(policy_id)
            changed = True
    # Older campaign checkpoints discarded crowd-only research results. Rebuild
    # a temporary crowd marker from the latest durable segment so a reconnect
    # cannot immediately select the same crowded route again.
    for policy_id, segment in latest_segments.items():
        if str(segment["status"]) not in {"ready", "success"}:
            continue
        try:
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            end_state = {}
        abort_reason = str(end_state.get("campaign_fastwalk_abort_reason") or "")
        if not (
            end_state.get("campaign_fastwalk_crowded")
            or any(
                abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        ):
            continue
        boot_id = end_state.get("world_boot_id")
        if (
            state.get("world_boot_id") is None
            or boot_id != state.get("world_boot_id")
        ):
            continue
        if policy_id in cleared_research_policies:
            # A retry checkpoint intentionally removed this route. Historical
            # crowd evidence must not resurrect it on the next reconnect.
            continue
        current_result = repaired_results.get(policy_id)
        if (
            isinstance(current_result, dict)
            and current_result.get("crowded") is True
            and current_result.get("boot_id") == boot_id
        ):
            if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                previous_attempt = repaired_source_ranked_crowd_attempts.get(
                    policy_id
                )
                try:
                    attempt_count = int(
                        previous_attempt.get("count")
                        if isinstance(previous_attempt, dict)
                        and previous_attempt.get("boot_id") == boot_id
                        else 0
                    )
                except (TypeError, ValueError):
                    attempt_count = 0
                attempt_count = max(attempt_count, 1)
                attempt_record = {
                    "boot_id": boot_id,
                    "count": attempt_count,
                }
                if (
                    repaired_source_ranked_crowd_attempts.get(policy_id)
                    != attempt_record
                ):
                    repaired_source_ranked_crowd_attempts[policy_id] = (
                        attempt_record
                    )
                    changed = True
                if (
                    attempt_count >= _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD
                    and current_result.get("crowd_exhausted") is not True
                ):
                    current_result = dict(current_result)
                    current_result["crowd_exhausted"] = True
                    repaired_results[policy_id] = current_result
                    changed = True
            if policy_id not in repaired_crowd_cooldowns:
                repaired_crowd_cooldowns[policy_id] = (
                    _DEFAULT_RESEARCH_CROWD_COOLDOWN
                )
                changed = True
            continue
        if (
            isinstance(current_result, dict)
            and current_result.get("boot_id") == boot_id
            and current_result.get("viable") is True
            and current_result.get("completed_kill") is not False
        ):
            if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                preserved_result = dict(current_result)
                preserved_result["crowded"] = True
                repaired_results[policy_id] = preserved_result
                previous_attempt = repaired_source_ranked_crowd_attempts.get(
                    policy_id
                )
                try:
                    attempt_count = int(
                        previous_attempt.get("count")
                        if isinstance(previous_attempt, dict)
                        and previous_attempt.get("boot_id") == boot_id
                        else 0
                    )
                except (TypeError, ValueError):
                    attempt_count = 0
                attempt_count = max(attempt_count, 1)
                repaired_source_ranked_crowd_attempts[policy_id] = {
                    "boot_id": boot_id,
                    "count": attempt_count,
                }
                if attempt_count >= _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD:
                    preserved_result["crowd_exhausted"] = True
                if policy_id not in repaired_crowd_cooldowns:
                    repaired_crowd_cooldowns[policy_id] = (
                        _DEFAULT_RESEARCH_CROWD_COOLDOWN
                    )
                repaired_cooldowns.pop(policy_id, None)
                changed = True
            elif repaired_crowd_cooldowns.pop(policy_id, None) is not None:
                changed = True
            continue
        crowd_result = {
            "observed": False,
            "viable": False,
            "crowded": True,
            "boot_id": boot_id,
        }
        if repaired_results.get(policy_id) != crowd_result:
            repaired_results[policy_id] = crowd_result
            changed = True
        if repaired_cooldowns.pop(policy_id, None) is not None:
            changed = True
        if repaired_crowd_cooldowns.get(policy_id) != (
            _DEFAULT_RESEARCH_CROWD_COOLDOWN
        ):
            repaired_crowd_cooldowns[policy_id] = (
                _DEFAULT_RESEARCH_CROWD_COOLDOWN
            )
            changed = True
        if policy_id in cleared_research_policies:
            cleared_research_policies.discard(policy_id)
            changed = True
    if not changed:
        return state
    repaired = dict(state)
    repaired["campaign_research_results"] = repaired_results
    if repaired_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = repaired_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if repaired_crowd_cooldowns:
        repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = repaired_crowd_cooldowns
    else:
        repaired.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if repaired_source_ranked_crowd_attempts:
        repaired[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = (
            repaired_source_ranked_crowd_attempts
        )
    else:
        repaired.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    if cleared_research_policies:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    if retry_marker is not None:
        repaired[_EXPLICIT_RESEARCH_RETRY_KEY] = retry_marker
    else:
        repaired.pop(_EXPLICIT_RESEARCH_RETRY_KEY, None)
    return repaired


def _repair_provision_funding_history(
    storage: RunStorage,
    campaign_id: int,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Recover funding attempts that older metadata checkpoints discarded."""
    successful_emergency_sales = False
    for segment in _runtime_campaign_segments(storage, campaign_id):
        if (
            segment["phase"] != "liquidate-loot"
            or segment["status"] != "success"
            or segment["run_id"] is None
        ):
            continue
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            start_state = {}
        if (
            start_state.get(_PROVISION_FUNDING_REQUIRED_KEY)
            and storage.list_loot_sales_for_run(int(segment["run_id"]))
        ):
            successful_emergency_sales = True
            break
    records: list[dict[str, Any]] = []
    invalid_navigation_attempts: set[tuple[str, str]] = set()

    def attempt_key(record: Mapping[str, Any]) -> tuple[str, str]:
        return (
            str(record.get("boot_id")),
            str(record.get("candidate_key")),
        )

    def grouped_attempts(
        raw_attempts: Any,
    ) -> dict[tuple[str, str], list[dict[str, Any]]]:
        grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
        if not isinstance(raw_attempts, list):
            return grouped
        for raw_record in raw_attempts:
            if not isinstance(raw_record, dict):
                continue
            record = dict(raw_record)
            if record.get("candidate_key") is None:
                continue
            grouped.setdefault(attempt_key(record), []).append(record)
        return grouped

    def changed_attempt_keys(
        start_attempts: Any,
        end_attempts: Any,
    ) -> set[tuple[str, str]]:
        start_grouped = grouped_attempts(start_attempts)
        end_grouped = grouped_attempts(end_attempts)
        return {
            key
            for key, end_records in end_grouped.items()
            if end_records != start_grouped.get(key, [])
        }

    current_attempts = state.get(_PROVISION_FUNDING_ATTEMPTS_KEY)
    if isinstance(current_attempts, list):
        # The checkpoint state can lag a completed segment when a metadata
        # repair was recorded during the previous campaign invocation. Seed
        # the merge with that state, then let the durable segment history
        # overwrite it in chronological order. Appending the checkpoint last
        # can resurrect an older candidate as the apparent latest failure.
        records.extend(
            dict(record)
            for record in current_attempts
            if isinstance(record, dict)
        )
    for segment in _runtime_campaign_segments(storage, campaign_id):
        if segment["phase"] != "provision-funding":
            continue
        try:
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        raw_attempts = end_state.get(_PROVISION_FUNDING_ATTEMPTS_KEY)
        if isinstance(raw_attempts, list):
            segment_records = [
                dict(record)
                for record in raw_attempts
                if isinstance(record, dict)
            ]
            error = str(segment["error"] or "").casefold()
            if segment["status"] == "failed" and (
                "without observing its endpoint" in error
                or "progress watchdog" in error
            ):
                try:
                    start_state = json.loads(
                        segment["start_state_json"] or "{}"
                    )
                except (TypeError, json.JSONDecodeError):
                    start_state = {}
                invalid_navigation_attempts.update(
                    changed_attempt_keys(
                        start_state.get(_PROVISION_FUNDING_ATTEMPTS_KEY),
                        raw_attempts,
                    )
                )
            else:
                # A later segment that actually appends or changes an
                # attempt is fresh live evidence, even if an older route
                # failure for the same candidate was discarded.
                try:
                    start_state = json.loads(
                        segment["start_state_json"] or "{}"
                    )
                except (TypeError, json.JSONDecodeError):
                    start_state = {}
                invalid_navigation_attempts.difference_update(
                    changed_attempt_keys(
                        start_state.get(_PROVISION_FUNDING_ATTEMPTS_KEY),
                        raw_attempts,
                    )
                )
                records.extend(segment_records)
    if invalid_navigation_attempts:
        records = [
            record
            for record in records
            if attempt_key(record) not in invalid_navigation_attempts
        ]
    proceeds_state = dict(state)
    for segment in _runtime_campaign_segments(storage, campaign_id):
        if (
            segment["phase"] != "liquidate-loot"
            or segment["status"] != "success"
            or segment["run_id"] is None
        ):
            continue
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not (
            start_state.get(_PROVISION_FUNDING_REQUIRED_KEY)
            or start_state.get(_FLIGHT_FUNDING_RETRY_KEY)
        ):
            continue
        proceeds_state = _record_provision_funding_proceeds(
            start_state,
            proceeds_state,
            sales=storage.list_loot_sales_for_run(int(segment["run_id"])),
            boot_id=start_state.get("world_boot_id"),
        )
    if not records:
        if (
            successful_emergency_sales
            and state.get(_PROVISION_FUNDING_REQUIRED_KEY)
            and _has_campaign_food(state, gear_catalog=None)
        ):
            repaired = dict(state)
            repaired.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
            if proceeds_state.get(_PROVISION_FUNDING_PROCEEDS_KEY) != state.get(
                _PROVISION_FUNDING_PROCEEDS_KEY
            ):
                repaired[_PROVISION_FUNDING_PROCEEDS_KEY] = proceeds_state[
                    _PROVISION_FUNDING_PROCEEDS_KEY
                ]
            return repaired
        if proceeds_state != state:
            return proceeds_state
        return state

    by_candidate: dict[tuple[str, str], dict[str, Any]] = {}
    for record in records:
        key = (
            str(record.get("boot_id")),
            str(record.get("candidate_key")),
        )
        # Reassigning an existing dict key preserves its original insertion
        # position. Remove it first so the bounded history follows the latest
        # observed candidate order rather than an old discovery order.
        by_candidate.pop(key, None)
        by_candidate[key] = record
    repaired_attempts = list(by_candidate.values())[-_PROVISION_FUNDING_HISTORY_LIMIT:]
    repaired = dict(state)
    if proceeds_state.get(_PROVISION_FUNDING_PROCEEDS_KEY) != state.get(
        _PROVISION_FUNDING_PROCEEDS_KEY
    ):
        repaired[_PROVISION_FUNDING_PROCEEDS_KEY] = proceeds_state[
            _PROVISION_FUNDING_PROCEEDS_KEY
        ]
    if repaired_attempts != current_attempts:
        repaired[_PROVISION_FUNDING_ATTEMPTS_KEY] = repaired_attempts
    latest = records[-1]
    if latest.get("candidate_key") is not None:
        repaired[_PROVISION_FUNDING_LAST_ATTEMPT_KEY] = {
            "boot_id": latest.get("boot_id"),
            "candidate_key": str(latest.get("candidate_key")),
            "completed_kill": latest.get("completed_kill") is True,
        }
    if latest.get("completed_kill") is False:
        repaired[_PROVISION_FUNDING_REQUIRED_KEY] = True
    elif latest.get("completed_kill") is True:
        repaired.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
    if successful_emergency_sales and _has_campaign_food(state, gear_catalog=None):
        repaired.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
    return repaired if repaired != state else state


def _level(state: dict[str, Any]) -> int:
    level = state.get("level")
    return int(level) if isinstance(level, (int, float)) else 0


def _live_subclass(state: Mapping[str, Any]) -> str | None:
    value = state.get("subclass")
    if not isinstance(value, str):
        return None
    normalized = value.strip()
    return normalized if normalized.casefold() not in {"", "none"} else None


def _campaign_needs_healer_recovery(state: Mapping[str, Any]) -> bool:
    """Keep an under-resourced checkpoint out of the field-policy selector."""
    if state.get("dead") or _numeric_progress(dict(state), "hp") <= 0:
        return False

    def below_ratio(value_key: str, maximum_key: str, threshold: float) -> bool:
        value = state.get(value_key)
        maximum = state.get(maximum_key)
        if not isinstance(value, (int, float)) or not isinstance(
            maximum, (int, float)
        ) or maximum <= 0:
            return False
        return value / maximum < threshold

    return _has_poison_affect(state.get("affects")) or any(
        (
            below_ratio(
                "hp",
                "max_hp",
                _CAMPAIGN_HEALER_READY_HEALTH_RATIO,
            ),
            below_ratio(
                "mana",
                "max_mana",
                _CAMPAIGN_HEALER_READY_MANA_RATIO,
            ),
            below_ratio(
                "move",
                "max_move",
                _CAMPAIGN_HEALER_READY_MOVE_RATIO,
            ),
        )
    )


def _campaign_checkpoint_needs_return_home(state: Mapping[str, Any]) -> bool:
    """Route an out-of-town checkpoint home before city maintenance."""
    if state.get("dead") or _numeric_progress(dict(state), "hp") <= 0:
        return False
    room_vnum = str(state.get("room_vnum") or "")
    if not room_vnum or room_vnum in _MUD_SCHOOL_ACCESSORY_ROOMS:
        return False
    area = str(state.get("area") or "").strip().casefold()
    return bool(area and area != "midgaard")


_FUNDING_ROUTE_DIRECTIONS = {
    "north": "n",
    "east": "e",
    "south": "s",
    "west": "w",
    "up": "u",
    "down": "d",
}


def _funding_route_notation(commands: Collection[str]) -> str:
    """Convert source graph directions into a Fastwalk notation string."""
    return ";".join(
        _FUNDING_ROUTE_DIRECTIONS.get(command, command)
        for command in commands
    )


def _source_ranked_route_live_navigation(
    world: Any,
    candidate: HuntCandidate,
    *,
    character_level: int | None = None,
    origin_paths: Mapping[int, Any] | None = None,
    randomized_components: dict[tuple[str, str], set[str]] | None = None,
) -> dict[str, Any]:
    """Add live-VNUM navigation for randomized source route segments.

    ``R`` resets permute the directions inside a room set at reboot.  Keep
    the source path as the preferred destination order, but make the actual
    movement decisions from the live GMCP VNUM graph.  Low-level aggressive
    resets remain traversable when they are below the useful XP band; only a
    source-dangerous reset should be excluded from the maze search.
    """
    paths = (
        origin_paths
        if origin_paths is not None
        else _shortest_paths_from(world.rooms, 3001)
    )
    path = paths.get(candidate.room_vnum)
    if path is None:
        return {}
    room_vnums = tuple(str(room_vnum) for room_vnum in path[1])

    def command_index_for_room(room_index: int) -> int:
        """Map a source-path room index to the live route command index."""
        movement_count = 0
        for command_index, command in enumerate(path[0]):
            if movement_count == room_index:
                return command_index
            if not str(command).startswith("open "):
                movement_count += 1
        if movement_count == room_index:
            return len(path[0])
        raise ValueError(f"source path has no room index {room_index}")

    def source_room(room_vnum: str) -> Any | None:
        try:
            return world.rooms.get(int(room_vnum))
        except (TypeError, ValueError):
            return None

    def is_random_room(room_vnum: str, *, area_file: str | None = None) -> bool:
        room = source_room(room_vnum)
        return bool(
            room is not None
            and room.random_exits
            and (area_file is None or room.area_file == area_file)
        )

    def randomized_component(entry_room_vnum: str, area_file: str) -> set[str]:
        """Return the source-connected randomized room component."""
        random_rooms = {
            str(room.vnum)
            for room in world.rooms.values()
            if room.area_file == area_file and room.random_exits
        }
        if not random_rooms:
            return set()
        allowed = random_rooms | {entry_room_vnum}
        neighbors = {room_vnum: set() for room_vnum in allowed}
        for room_vnum in allowed:
            room = source_room(room_vnum)
            if room is None:
                continue
            for exit_source in room.exits.values():
                destination = str(exit_source.destination)
                if destination not in allowed:
                    continue
                neighbors[room_vnum].add(destination)
                neighbors[destination].add(room_vnum)
        visited = {entry_room_vnum}
        pending = [entry_room_vnum]
        while pending:
            current = pending.pop()
            for destination in neighbors[current]:
                if destination in visited:
                    continue
                visited.add(destination)
                pending.append(destination)
        return visited & random_rooms

    for start_index, room_vnum in enumerate(room_vnums):
        room = source_room(room_vnum)
        if room is None or not room.random_exits:
            continue
        if (
            start_index > 0
            and is_random_room(
                room_vnums[start_index - 1], area_file=room.area_file
            )
        ):
            continue
        target_index = start_index
        while (
            target_index < len(room_vnums)
            and is_random_room(
                room_vnums[target_index], area_file=room.area_file
            )
        ):
            target_index += 1

        entry_index = max(0, start_index - 1)
        if target_index >= len(room_vnums):
            # A candidate can itself reset inside a randomized component.
            # In that case the final source room is the live-maze target and
            # the resume index is the end of the ordinary route.
            if candidate.room_vnum != int(room_vnums[-1]):
                continue
            target_index = len(room_vnums) - 1
        entry_room_vnum = room_vnums[entry_index]
        component_key = (str(entry_room_vnum), str(room.area_file))
        if randomized_components is not None and component_key in randomized_components:
            random_component = randomized_components[component_key]
        else:
            random_component = randomized_component(
                entry_room_vnum,
                room.area_file,
            )
            if randomized_components is not None:
                randomized_components[component_key] = random_component
        if not random_component:
            random_component = {
                value
                for value in room_vnums[start_index:target_index + 1]
                if is_random_room(value, area_file=room.area_file)
            }

        effective_level = (
            character_level
            if isinstance(character_level, int)
            else candidate.level
        )
        useful_floor = effective_level - 5
        blocked_rooms: set[str] = set()
        for reset in world.mob_resets:
            reset_room = str(reset.room_vnum)
            if reset_room not in random_component:
                continue
            if (
                reset.mobile_vnum == candidate.mobile_vnum
                and reset.room_vnum == candidate.room_vnum
            ):
                continue
            mobile = world.mobiles.get(reset.mobile_vnum)
            if mobile is None:
                continue
            specials = world.mobile_specials.get(mobile.vnum, ())
            # Source-proven below-band mobiles may join a useful target's
            # combat, but they must not turn an otherwise navigable route
            # into an unsafe crowd.  Keep special and aggressive blockers
            # inside the useful band hard; the runner's ordinary combat
            # gates still handle an unavoidable lower-level interruption.
            source_level_upper = mobile.level + 2
            if (
                (specials and source_level_upper > useful_floor)
                or (
                    mobile.aggressive
                    and source_level_upper > useful_floor
                )
            ):
                blocked_rooms.add(reset_room)

        return {
            "live_navigation_target": room_vnums[target_index],
            "live_navigation_entry_room": str(entry_room_vnum),
            # FastwalkRoute indexes are command positions, while the source
            # path indexes above are room positions.  Door-opening commands
            # do not advance the room path, so keep the two coordinate
            # systems separate here.
            "live_navigation_start_index": command_index_for_room(entry_index),
            "live_navigation_resume_index": command_index_for_room(target_index),
            "live_navigation_room_vnums": tuple(
                sorted(random_component | {entry_room_vnum, room_vnums[target_index]})
            ),
            "live_navigation_blocked_room_vnums": tuple(sorted(blocked_rooms)),
            "live_navigation_preferred_destinations": tuple(
                dict.fromkeys(room_vnums[start_index:target_index + 1])
            ),
        }
    return {}


def _source_ranked_route_has_static_safe_live_navigation_path(
    world: Any,
    candidate: HuntCandidate,
    *,
    character_level: int,
    origin_paths: Mapping[int, Any] | None = None,
    randomized_components: dict[tuple[str, str], set[str]] | None = None,
    navigation_metadata: Mapping[str, Any] | None = None,
) -> bool:
    """Return whether a randomized route has a source-safe path to its target.

    The live runner can only choose among the VNUM graph exposed by GMCP.  A
    source route whose only connection crosses a blocked aggressive or special
    reset will therefore fail before target presence can be checked.  Reject
    that case during selection, while leaving routes without randomized
    segments unchanged.
    """
    metadata = navigation_metadata or _source_ranked_route_live_navigation(
        world,
        candidate,
        character_level=character_level,
        origin_paths=origin_paths,
        randomized_components=randomized_components,
    )
    if not metadata:
        return True
    paths = (
        origin_paths
        if origin_paths is not None
        else _shortest_paths_from(world.rooms, 3001)
    )
    path = paths.get(candidate.room_vnum)
    if path is None:
        return True
    room_vnums = tuple(str(room_vnum) for room_vnum in path[1])
    try:
        start_command_index = int(metadata["live_navigation_start_index"])
        target = str(metadata["live_navigation_target"])
    except (KeyError, TypeError, ValueError):
        return False
    if not 0 <= start_command_index <= len(path[0]):
        return False
    start_index = sum(
        not str(command).startswith("open ")
        for command in path[0][:start_command_index]
    )
    if not 0 <= start_index < len(room_vnums):
        return False
    start = room_vnums[start_index]
    allowed = {
        str(room_vnum)
        for room_vnum in metadata.get("live_navigation_room_vnums", ())
    }
    blocked = {
        str(room_vnum)
        for room_vnum in metadata.get("live_navigation_blocked_room_vnums", ())
    }
    if start not in allowed or target not in allowed or start in blocked:
        return False

    neighbors = {room_vnum: set() for room_vnum in allowed}
    for room_vnum in allowed:
        room = world.rooms.get(int(room_vnum))
        if room is None:
            continue
        for exit_source in room.exits.values():
            destination = str(exit_source.destination)
            if destination not in allowed:
                continue
            neighbors[room_vnum].add(destination)
            # Randomized exits preserve the source-connected component, so
            # the preflight treats the component as an undirected graph.
            neighbors[destination].add(room_vnum)

    visited = {start}
    pending = [start]
    while pending:
        current = pending.pop()
        for destination in neighbors[current]:
            if destination in visited or destination in blocked:
                continue
            visited.add(destination)
            pending.append(destination)
    return target in visited


def _provision_funding_candidate_key(candidate: HuntCandidate) -> str:
    if candidate.is_coin_stash:
        keywords = ",".join(candidate.ground_loot_keywords)
        return ":".join(
            (
                candidate.area_file,
                "coin-stash",
                str(candidate.room_vnum),
                keywords or candidate.target_keyword,
            )
        )
    return ":".join(
        (
            candidate.area_file,
            str(candidate.mobile_vnum),
            str(candidate.room_vnum),
        )
    )


def _candidate_has_saleable_funding_drop(
    candidate: HuntCandidate,
    *,
    gear_catalog: GearCatalog | None,
) -> bool:
    if candidate.contained_coins > 0:
        return True
    if gear_catalog is None:
        return bool(candidate.loot)
    # ``HuntCandidate.loot`` is parsed from the exact reset objects.  Do not
    # let ``GearCatalog.match`` turn a zero-value prototype into a funding
    # target merely because another prototype shares its display name.
    if candidate.source_value <= 0:
        return False
    return any(
        (
            (item := gear_catalog.match(description)) is not None
            and item.source_cost > 0
            and is_releasable_funding_item(item)
            and safe_shop_for_item(
                item.short_description,
                item_type=item.item_type,
                item_value=item.source_cost,
            )
            is not None
        )
        for description in candidate.loot
    )


def _provision_funding_capacity_relief_actions(
    state: Mapping[str, Any] | None,
    *,
    gear_catalog: GearCatalog | None,
) -> tuple[str, ...]:
    """Free one item slot before funding when safe redundant loot exists."""
    if gear_catalog is None or not isinstance(state, Mapping):
        return ()
    stats = state.get("stats")
    if not isinstance(stats, Mapping):
        return ()
    try:
        carry_num = int(stats.get("carry_num"))
        maximum_num = int(stats.get("maxcarry_num"))
    except (TypeError, ValueError):
        return ()
    if maximum_num <= 0 or carry_num < maximum_num:
        return ()

    descriptions = _inventory_descriptions(state.get("inventory"))
    counts = Counter(normalize_item_name(description) for description in descriptions)
    for description in descriptions:
        normalized = normalize_item_name(description)
        if counts[normalized] <= 2:
            continue
        item = gear_catalog.match(description)
        if item is None or item.item_type != ITEM_POTION:
            continue
        # Prefer a distinctive source keyword over the ambiguous noun
        # ``potion`` so the command cannot donate the wrong prototype.
        keyword = _combat_potion_item_keyword(
            item,
            gear_catalog.candidates(description),
        )
        if keyword:
            return (f"donate {keyword}",)
    return ()


def _source_candidate_loot_container(
    world: WorldSource,
    candidate: HuntCandidate,
) -> str | None:
    """Return the source keyword for a mob-carried money container."""
    for reset in world.mob_resets:
        if (
            reset.mobile_vnum != candidate.mobile_vnum
            or reset.room_vnum != candidate.room_vnum
        ):
            continue
        for container_vnum in reset.object_vnums:
            container = world.objects.get(container_vnum)
            if container is None or not world.container_contents.get(container_vnum):
                continue
            pending = list(world.container_contents.get(container_vnum, ()))
            visited: set[int] = set()
            contains_money = False
            while pending:
                object_vnum = pending.pop()
                if object_vnum in visited:
                    continue
                visited.add(object_vnum)
                item = world.objects.get(object_vnum)
                if item is None:
                    continue
                if item.item_type == ITEM_MONEY:
                    contains_money = True
                    break
                pending.extend(world.container_contents.get(object_vnum, ()))
            if contains_money:
                return item_keyword(container)
    return None


def _source_money_container_keyword(
    state: Mapping[str, Any] | None,
    *,
    gear_catalog: GearCatalog | None,
    world: WorldSource | None,
) -> str | None:
    """Find a carried source container whose reset contents include money."""
    if not isinstance(state, Mapping) or gear_catalog is None or world is None:
        return None
    for description in _inventory_descriptions(state.get("inventory")):
        for container in gear_catalog.candidates(description):
            if container.item_type != ITEM_CONTAINER:
                continue
            pending = list(world.container_contents.get(container.vnum, ()))
            visited: set[int] = set()
            while pending:
                object_vnum = pending.pop()
                if object_vnum in visited:
                    continue
                visited.add(object_vnum)
                item = world.objects.get(object_vnum)
                if item is None:
                    continue
                if item.item_type == ITEM_MONEY:
                    return item_keyword(container)
                pending.extend(world.container_contents.get(object_vnum, ()))
    return None


def _funding_candidate_source_value(candidate: HuntCandidate) -> int:
    """Use source loot and contained coins as a conservative funding proxy."""
    return max(0, int(candidate.source_value)) + max(
        0,
        int(candidate.contained_coins),
    )


def _funding_candidate_is_below_band(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    boot_id: str | int | None,
) -> bool:
    """Honor live below-band evidence before selecting a funding kill."""
    raw = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw, dict):
        return False
    target = normalize_item_name(candidate.target)
    source_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    for policy_id, record in raw.items():
        # Source-ranked evidence belongs to one exact mobile reset.  Two
        # source mobiles can share a display name (for example, the two
        # cityguard prototypes), so a below-band result for one VNUM must not
        # suppress its distinct source policy.
        if (
            str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and str(policy_id) != source_policy_id
        ):
            continue
        if (
            not isinstance(record, dict)
            or record.get("level") != character_level
            or record.get("boot_id") != boot_id
        ):
            continue
        targets = record.get("targets")
        if isinstance(targets, (list, tuple, set)) and any(
            normalize_item_name(str(item)) == target for item in targets
        ):
            return True
    return False


def _funding_candidate_has_persisted_below_band_sighting(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    boot_id: str | int | None,
) -> bool:
    """Avoid re-routing to a carrier the starter already skipped live."""
    raw = state.get(_BELOW_BAND_SIGHTINGS_KEY)
    if not isinstance(raw, dict):
        return False
    identities = {
        normalize_item_name(candidate.target),
        normalize_item_name(candidate.target_identity),
    }
    identities.discard("")
    for record in raw.values():
        if (
            not isinstance(record, dict)
            or record.get("level") != character_level
            or record.get("boot_id") != boot_id
        ):
            continue
        sightings = record.get("sightings")
        if not isinstance(sightings, (list, tuple, set)):
            continue
        for sighting in sightings:
            if not isinstance(sighting, dict):
                continue
            observed = normalize_item_name(str(sighting.get("target", "")))
            if observed in identities:
                return True
    return False


def _source_ranked_target_identity(candidate: HuntCandidate) -> str:
    """Convert a source short description into the starter target identity."""
    target = normalize_item_name(
        candidate.target_identity or candidate.target
    )
    return re.sub(r"^(?:a|an|the)\s+", "", target)


def _source_candidate_required_move(
    candidate: HuntCandidate,
    state: Mapping[str, Any] | None = None,
) -> int:
    """Return the absolute movement gate for a source-ranked departure.

    A live flight affect makes the source route cheaper, but an unknown affect
    snapshot is treated as no-flight evidence.  Zero-cost hand-built test
    candidates retain the old unconstrained behavior.
    """
    flying = bool(
        state is not None
        and (
            _has_named_affect(state.get("affects"), "fly")
            or _has_named_affect(state.get("affects"), "levitation")
        )
    )
    route_cost = (
        candidate.estimated_flying_move_cost
        if flying
        else candidate.estimated_move_cost
    )
    if route_cost <= 0:
        return 0
    required = route_cost + _SOURCE_ROUTE_MOVEMENT_RESERVE
    if candidate.area_file.casefold() == "abyss.are" and state is not None:
        maximum_move = state.get("max_move")
        if isinstance(maximum_move, (int, float)) and maximum_move > 0:
            # Enter the aerial randomized area only with a full pool. The
            # worker separately preserves a 36-point nearest-recall reserve.
            required = max(required, int(maximum_move))
    return required


def _source_candidate_fits_movement(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
) -> bool:
    """Reject source routes that cannot fit the character's move pool."""
    maximum_move = state.get("max_move")
    if not isinstance(maximum_move, (int, float)) or maximum_move <= 0:
        return True
    required_move = _source_candidate_required_move(candidate, state)
    return required_move == 0 or required_move <= int(maximum_move)


# Keep the source-backed locator bounded, while covering the largest current
# source-reachable wandering area (274 rooms in the checked-in DD4 source).
_SOURCE_RANKED_WANDER_SEARCH_LIMIT = 512

# Keep a cross-target source-ranked circuit short enough to fit the existing
# bounded segment while still avoiding the one-long-route-per-kill bottleneck.
_SOURCE_RANKED_AREA_CIRCUIT_TARGET_LIMIT = 3
_SOURCE_RANKED_AREA_CIRCUIT_ROUTE_LIMIT = 20
_SOURCE_RANKED_AREA_CIRCUIT_PRIMARY_SCAN_LIMIT = 40
_SOURCE_RANKED_POST_KILL_COOLDOWN_SEGMENTS = 2


def _source_room_label(value: str) -> str:
    """Normalize an area-file room name for matching ``where`` output."""
    return " ".join(str(value).casefold().split())


def _source_mobile_is_trivial_bystander(
    world: Any,
    mobile: Any,
    *,
    character_level: int,
) -> bool:
    """Return whether source evidence permits ignoring a room companion.

    ``update.c`` only starts an unsolicited NPC attack for an aggressive
    mobile.  A source mobile with no aggressive flag and no special procedure
    therefore cannot join an unrelated player-vs-mobile fight, even when its
    own level is above the controlled character.  Keep the level check for
    mobiles with known safe special behavior, but admit this stronger
    non-assisting case as a crowd bystander as well.
    """
    level_range = (
        mobile.level - 2,
        mobile.level + 2,
    )
    source_specials = tuple(
        world.mobile_specials.get(mobile.vnum, ())
    )
    return bool(
        level_range[1] <= character_level - 5
        or (
            not mobile.aggressive
            and not source_specials
        )
    )


def _source_trivial_bystanders_by_room(
    world: Any,
    *,
    room_vnums: Collection[int],
    target_mobile_vnum: int,
    character_level: int,
) -> dict[int, tuple[str, ...]]:
    """Index source-identified companions safe to exclude by destination.

    Include ordinary wanderers whose source movement graph reaches the room,
    not only mobiles reset there.  A shared display identity remains unsafe if
    any materially dangerous prototype with that identity can also reach the
    room, so a low-level ``citizen`` cannot mask a different dangerous one.

    Build the index once for the complete hunt circuit. Large wandering target
    graphs can contain hundreds of rooms, so repeating the world scan for each
    destination would make policy selection CPU-bound for minutes.
    """
    destinations = {
        room_vnum: room
        for room_vnum in dict.fromkeys(room_vnums)
        if (room := world.rooms.get(room_vnum)) is not None
    }
    if not destinations:
        return {}
    destination_vnums = frozenset(destinations)
    destination_areas = {
        room.area_file for room in destinations.values()
    }
    grouped_resets: dict[int, list[int]] = {}
    for reset in world.mob_resets:
        if reset.room_vnum in world.rooms:
            grouped_resets.setdefault(reset.mobile_vnum, []).append(
                reset.room_vnum
            )
    reset_rooms_by_mobile = {
        mobile_vnum: tuple(dict.fromkeys(reset_room_vnums))
        for mobile_vnum, reset_room_vnums in grouped_resets.items()
    }
    reachable_destinations_by_mobile: dict[int, frozenset[int]] = {}
    reverse_open_exits: dict[int, set[int]] = {}
    reverse_confused_exits: dict[int, set[int]] = {}
    for source_room in world.rooms.values():
        for exit_source in source_room.exits.values():
            destination = world.rooms.get(exit_source.destination)
            if destination is None or exit_source.closed:
                continue
            reverse_confused_exits.setdefault(destination.vnum, set()).add(
                source_room.vnum
            )
            if not destination.no_mob:
                reverse_open_exits.setdefault(destination.vnum, set()).add(
                    source_room.vnum
                )
    reverse_reachability: dict[tuple[int, bool], frozenset[int]] = {}

    def rooms_reaching_destination(
        destination: int,
        *,
        confused: bool,
    ) -> frozenset[int]:
        key = (destination, confused)
        cached = reverse_reachability.get(key)
        if cached is not None:
            return cached
        reverse_exits = (
            reverse_confused_exits if confused else reverse_open_exits
        )
        pending = [destination]
        reachable: set[int] = set()
        while pending:
            room_vnum = pending.pop()
            if room_vnum in reachable:
                continue
            reachable.add(room_vnum)
            pending.extend(reverse_exits.get(room_vnum, ()))
        result = frozenset(reachable)
        reverse_reachability[key] = result
        return result

    def reachable_destinations(mobile_vnum: int, mobile: Any) -> frozenset[int]:
        cached = reachable_destinations_by_mobile.get(mobile_vnum)
        if cached is not None:
            return cached
        reset_rooms = reset_rooms_by_mobile.get(mobile_vnum, ())
        reachable = destination_vnums.intersection(reset_rooms)
        if mobile.wanders and reset_rooms:
            if mobile.stay_area and not mobile.confused:
                reachable = destination_vnums.intersection(
                    source_mobile_search_rooms(world, mobile_vnum)
                )
            else:
                reachable = {
                    destination
                    for destination in destination_vnums
                    if any(
                        reset_room
                        in rooms_reaching_destination(
                            destination,
                            confused=mobile.confused,
                        )
                        for reset_room in reset_rooms
                    )
                }
        result = frozenset(reachable)
        reachable_destinations_by_mobile[mobile_vnum] = result
        return result

    target_mobile = world.mobiles.get(target_mobile_vnum)
    target_identities = {
        normalize_item_name(identity)
        for identity in (
            source_mobile_identities(
                target_mobile.room_description,
                target_mobile.short_description,
                target_mobile.keywords,
            )
            if target_mobile is not None
            else ()
        )
        if identity
    }
    candidate_identities_by_room: dict[int, list[str]] = {
        room_vnum: [] for room_vnum in destinations
    }
    for mobile_vnum, reset_rooms in reset_rooms_by_mobile.items():
        if mobile_vnum == target_mobile_vnum:
            continue
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None:
            continue
        reset_areas = {
            reset_room.area_file
            for reset_room_vnum in reset_rooms
            if (reset_room := world.rooms.get(reset_room_vnum)) is not None
        }
        if not destination_vnums.intersection(reset_rooms) and not (
            mobile.wanders
            and (
                mobile.confused
                or not mobile.stay_area
                or reset_areas.intersection(destination_areas)
            )
        ):
            continue
        if not _source_mobile_is_trivial_bystander(
            world,
            mobile,
            character_level=character_level,
        ):
            continue
        identity = normalize_item_name(mobile.short_description)
        if (
            identity
            and identity not in target_identities
        ):
            for destination in reachable_destinations(mobile_vnum, mobile):
                if (
                    destination not in reset_rooms
                    and mobile.stay_area
                    and not mobile.confused
                    and destinations[destination].area_file not in reset_areas
                ):
                    continue
                identities = candidate_identities_by_room[destination]
                if identity not in identities:
                    identities.append(identity)

    # A source-closed door can be open during live play, allowing an ordinary
    # wanderer into a room outside the static movement graph. Admit that live
    # possibility only when every same-identity prototype that could enter the
    # destination area is source-proven trivial.
    dynamic_candidates_by_room: dict[int, dict[str, list[Any]]] = {
        room_vnum: {} for room_vnum in destinations
    }
    for mobile_vnum, reset_rooms in reset_rooms_by_mobile.items():
        if mobile_vnum == target_mobile_vnum:
            continue
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None:
            continue
        identity = normalize_item_name(mobile.short_description)
        if not identity or identity in target_identities:
            continue
        reset_areas = {
            reset_room.area_file
            for reset_room_vnum in reset_rooms
            if (reset_room := world.rooms.get(reset_room_vnum)) is not None
        }
        for destination, destination_room in destinations.items():
            can_enter_dynamic_area = bool(
                destination in reset_rooms
                or (
                    mobile.wanders
                    and destination_room.area_file in reset_areas
                )
            )
            if not can_enter_dynamic_area:
                continue
            dynamic_candidates_by_room[destination].setdefault(
                identity,
                [],
            ).append(mobile)
    for destination, identities_by_mobile in dynamic_candidates_by_room.items():
        identities = candidate_identities_by_room[destination]
        for identity, matching_mobiles in identities_by_mobile.items():
            if identity in identities or not matching_mobiles:
                continue
            if all(
                _source_mobile_is_trivial_bystander(
                    world,
                    mobile,
                    character_level=character_level,
                )
                for mobile in matching_mobiles
            ):
                identities.append(identity)

    candidate_identities = {
        identity
        for identities in candidate_identities_by_room.values()
        for identity in identities
    }
    dangerous_identities_by_room: dict[int, set[str]] = {
        room_vnum: set() for room_vnum in destinations
    }
    for mobile_vnum, mobile in world.mobiles.items():
        if mobile_vnum == target_mobile_vnum:
            continue
        identity = normalize_item_name(mobile.short_description)
        if identity not in candidate_identities:
            continue
        if _source_mobile_is_trivial_bystander(
            world,
            mobile,
            character_level=character_level,
        ):
            continue
        for destination in reachable_destinations(mobile_vnum, mobile):
            dangerous_identities_by_room[destination].add(identity)

    return {
        room_vnum: tuple(
            identity
            for identity in identities
            if identity not in dangerous_identities_by_room[room_vnum]
        )
        for room_vnum, identities in candidate_identities_by_room.items()
    }


def _source_room_trivial_bystanders(
    world: Any,
    *,
    room_vnum: int,
    target_mobile_vnum: int,
    character_level: int,
) -> tuple[str, ...]:
    """List source-identified companions safe to exclude from one room."""
    return _source_trivial_bystanders_by_room(
        world,
        room_vnums=(room_vnum,),
        target_mobile_vnum=target_mobile_vnum,
        character_level=character_level,
    ).get(room_vnum, ())


def _source_ranked_hunt_stops(
    candidate: HuntCandidate,
    world: Any,
    *,
    character_level: int | None = None,
    hunt_route_origin_room_vnum: int | None = None,
    state: Mapping[str, Any] | None = None,
    maximum_level_offset_override: int | None = None,
) -> tuple[FieldHuntStop, ...]:
    """Build source-aware stops for sentinel and wandering target mobiles.

    Sentinel mobiles are checked at every source reset room.  A non-sentinel
    mobile is first located with DD4's area-scoped ``where`` command, then
    checked only across the bounded, source-reachable room set.  For a
    stay-area wanderer, an absent or unmappable locator result is authoritative;
    for a global wanderer, ``where`` is only an optimization because DD4 cannot
    report mobiles in a different area.  An exact miss in an area-scoped
    response also skips the current area for a global wanderer; it is
    current-area evidence, not a reboot-wide absence claim.  The locator keeps
    a large area from becoming a blind room-by-room expedition while preserving
    a source-graph fallback for cross-area movement.  When the registered fastwalk ends at a
    staging room, ``hunt_route_origin_room_vnum`` moves the first locator or
    sentinel stop into the target's source area before any area-scoped
    presence result is interpreted.
    """
    target = _source_ranked_target_identity(candidate)
    if candidate.is_coin_stash:
        actions = tuple(
            f"get all.{keyword}"
            for keyword in candidate.ground_loot_keywords
        ) or (f"get all.{candidate.target_keyword}",)
        return (
            FieldHuntStop(
                (),
                None,
                actions=actions,
                minimum_health_ratio=0.85,
            ),
        )
    if character_level is None:
        character_level = candidate.level
    source_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    source_target_armed = bool(candidate.equipped_weapons)
    source_critical_hit_damage = candidate.estimated_critical_hit_damage
    if source_critical_hit_damage <= 0:
        source_level = max(
            candidate.level,
            candidate.estimated_level_range[1],
        )
        if source_level > 0:
            source_critical_hit_damage = _mobile_critical_hit_damage(
                source_level,
                wielding=source_target_armed,
            )
    bounded_peak_probe = (
        _SOURCE_PEAK_DAMAGE_REJECTION in candidate.autonomy_rejections
    )
    state_max_hp = (
        int(state["max_hp"])
        if isinstance(state, Mapping)
        and isinstance(state.get("max_hp"), (int, float))
        else None
    )
    protected_peak_probe = bounded_peak_probe and (
        _source_ranked_protected_peak_probe_allowed(
            candidate,
            state=state or {},
            character_level=character_level,
            character_max_hp=state_max_hp,
        )
    )
    mobile = world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return (
            FieldHuntStop(
                (),
                target,
                command_keyword=candidate.target_keyword,
                exact_target=True,
                source_mobile_vnum=candidate.mobile_vnum,
                maximum_target_count=1,
                require_isolated=True,
                minimum_health_ratio=(0.95 if candidate.specials else 0.85),
                require_sanctuary=(
                    _source_ranked_candidate_requires_sanctuary_for_state(
                        candidate,
                        state or {},
                        character_level=character_level,
                    )
                ),
                maximum_level_offset=(
                    2
                    if protected_peak_probe
                    else _source_ranked_maximum_level_offset(candidate)
                ),
                source_policy_id=source_policy_id,
                source_target_armed=source_target_armed,
                source_critical_hit_damage=(
                    source_critical_hit_damage or None
                ),
                source_specials=tuple(candidate.specials),
            ),
        )
    source_identities = source_mobile_identities(
        mobile.room_description,
        mobile.short_description,
        mobile.keywords,
    )
    if source_identities and source_identities[0]:
        # Recompute this from the source prototype so a persisted candidate
        # made before the shared parser existed cannot miss a live room line.
        target = normalize_item_name(source_identities[0])

    reset_rooms = tuple(
        sorted(
            {
                reset.room_vnum
                for reset in world.mob_resets
                if reset.mobile_vnum == candidate.mobile_vnum
                and reset.room_vnum in world.rooms
            }
        )
    )

    def source_loot_object_vnums(room_vnum: int) -> tuple[int, ...]:
        return tuple(
            dict.fromkeys(
                object_vnum
                for reset in world.mob_resets
                if reset.mobile_vnum == candidate.mobile_vnum
                and reset.room_vnum == room_vnum
                for object_vnum in reset.object_vnums
            )
        )
    # Other materially dangerous aggressive resets are route hazards, but the
    # requested mobile's own reset room is a legitimate destination. A source
    # proven trivial bystander must not make a useful target unreachable: the
    # live runner already ignores that mobile for crowd and flee decisions.
    # Excluding the target from this set matters for aggressive sentinels and
    # wanderers: otherwise a present target can be made unreachable before
    # live room isolation runs.
    blocked_rooms = {
        reset.room_vnum
        for reset in world.mob_resets
        if reset.room_vnum in world.rooms
        and reset.mobile_vnum != candidate.mobile_vnum
        and (reset_mobile := world.mobiles.get(reset.mobile_vnum)) is not None
        and reset_mobile.aggressive
        and not _source_mobile_is_trivial_bystander(
            world,
            reset_mobile,
            character_level=character_level,
        )
    }
    if not mobile.wanders:
        destination_rooms = tuple(
            dict.fromkeys((candidate.room_vnum, *reset_rooms))
        )
        locator_stop: FieldHuntStop | None = None
        unsafe_room_labels: tuple[str, ...] = ()
    else:
        reachable_rooms = source_mobile_search_rooms(
            world,
            candidate.mobile_vnum,
            maximum_rooms=_SOURCE_RANKED_WANDER_SEARCH_LIMIT,
        )
        safe_reachable_rooms = tuple(
            room_vnum
            for room_vnum in reachable_rooms
            if room_vnum not in blocked_rooms
        )
        destination_rooms = tuple(
            dict.fromkeys((candidate.room_vnum, *safe_reachable_rooms))
        )[:_SOURCE_RANKED_WANDER_SEARCH_LIMIT]
        unsafe_room_labels = ()
        locator_stop = None

    minimum_health_ratio = (
        0.95 if candidate.specials or bounded_peak_probe else 0.85
    )
    require_sanctuary = (
        _source_ranked_candidate_requires_sanctuary_for_state(
            candidate,
            state or {},
            character_level=character_level,
        )
    )
    maximum_level_offset = (
        maximum_level_offset_override
        if maximum_level_offset_override is not None
        else (
            2
            if protected_peak_probe
            else _source_ranked_maximum_level_offset(candidate)
        )
    )
    ordered_destinations = [candidate.room_vnum]
    route_by_destination: dict[int, tuple[str, ...]] = {}
    remaining_destinations = set(destination_rooms)
    remaining_destinations.discard(candidate.room_vnum)
    current_room = candidate.room_vnum
    while remaining_destinations:
        paths = _shortest_paths_from(
            world.rooms,
            current_room,
            blocked_rooms=blocked_rooms,
        )
        choices = [
            (len(path[1]), destination, path)
            for destination in remaining_destinations
            if (path := paths.get(destination)) is not None
            and not path[2]
            and _source_ranked_route_is_traversable(
                world,
                path[1],
                state,
            )
        ]
        if not choices:
            break
        _, destination, path = min(choices, key=lambda item: (item[0], item[1]))
        route_by_destination[destination] = tuple(
            str(room_vnum) for room_vnum in path[1][1:]
        )
        ordered_destinations.append(destination)
        remaining_destinations.remove(destination)
        current_room = destination

    if mobile.wanders:
        location_routes: dict[str, list[str]] = {}
        for room_vnum in ordered_destinations:
            room = world.rooms.get(room_vnum)
            if room is None:
                continue
            label = _source_room_label(room.name)
            if label:
                location_routes.setdefault(label, []).append(str(room_vnum))
        for room_vnum in reachable_rooms:
            room = world.rooms.get(room_vnum)
            if room is None:
                continue
            label = _source_room_label(room.name)
            if label:
                # Keep every source-reachable location in the locator map.
                # Empty routes identify rooms that require an unsafe or
                # otherwise unavailable transition, rather than losing a
                # wandering target during discovery.
                location_routes.setdefault(label, [])
        unsafe_room_labels = tuple(
            sorted(
                label
                for label, route in location_routes.items()
                if not route
            )
        )
        relocation_routes: list[tuple[str, str, tuple[str, ...]]] = []
        for relocation_origin in ordered_destinations:
            relocation_paths = _shortest_paths_from(
                world.rooms,
                relocation_origin,
                blocked_rooms=blocked_rooms,
            )
            for destination in ordered_destinations:
                room = world.rooms.get(destination)
                path = relocation_paths.get(destination)
                if (
                    room is None
                    or path is None
                    or path[2]
                    or not _source_ranked_route_is_traversable(
                        world,
                        path[1],
                        state,
                    )
                ):
                    continue
                label = _source_room_label(room.name)
                if not label:
                    continue
                relocation_routes.append(
                    (
                        str(relocation_origin),
                        label,
                        tuple(str(room_vnum) for room_vnum in path[1][1:]),
                    )
                )
        locator_stop = FieldHuntStop(
            (),
            None,
            # ``where`` reports the generic short name, while room output and
            # TARGETMODE selectors use the source-distinct identity above.
            where_target=normalize_item_name(mobile.short_description),
            command_keyword=candidate.target_keyword,
            actions=(f"where {candidate.target_keyword}",),
            where_location_routes=tuple(
                (label, tuple(room_vnums))
                for label, room_vnums in sorted(location_routes.items())
            ),
            where_relocation_routes=tuple(relocation_routes),
            maximum_where_relocations=1,
            abort_if_where_target_absent=(
                mobile.stay_area and not mobile.confused
            ),
            abort_if_where_target_unlisted=(
                not mobile.stay_area and not mobile.confused
            ),
            abort_if_where_room_names=unsafe_room_labels,
            abort_if_where_location_unknown=(
                mobile.stay_area and not mobile.confused
            ),
            preserve_where_route_waypoints=True,
            exact_target=True,
            maximum_target_count=1,
            require_isolated=True,
        )

    initial_route_vnums: tuple[str, ...] = ()
    initial_route_commands: tuple[str, ...] = ()
    if (
        hunt_route_origin_room_vnum is not None
        and hunt_route_origin_room_vnum != candidate.room_vnum
    ):
        initial_path = _shortest_paths_from(
            world.rooms,
            hunt_route_origin_room_vnum,
            # The registered fastwalk owns its explicit route-hazard
            # preflight.  Do not let an aggressive mobile reset in a known
            # transit room make the target area's source path look absent.
            blocked_rooms=frozenset(),
        ).get(candidate.room_vnum)
        if initial_path is not None:
            initial_route_commands = initial_path[0]
            if not initial_path[2]:
                initial_route_vnums = tuple(
                    str(room_vnum) for room_vnum in initial_path[1][1:]
                )

    stops: list[FieldHuntStop] = []
    trivial_bystanders_by_room = _source_trivial_bystanders_by_room(
        world,
        room_vnums=ordered_destinations,
        target_mobile_vnum=candidate.mobile_vnum,
        character_level=character_level,
    )
    if locator_stop is not None:
        if initial_route_vnums:
            locator_stop = replace(
                locator_stop,
                route_vnums=initial_route_vnums,
            )
        elif initial_route_commands:
            locator_stop = replace(
                locator_stop,
                route=initial_route_commands,
            )
        stops.append(locator_stop)
    for destination in ordered_destinations:
        route_vnums = route_by_destination.get(destination, ())
        route_commands: tuple[str, ...] = ()
        destination_policy_id = source_policy_id
        if not mobile.wanders:
            destination_policy_id = _source_ranked_policy_id(
                replace(candidate, room_vnum=destination),
                character_level=character_level,
            )
        if (
            destination == ordered_destinations[0]
            and locator_stop is None
            and (initial_route_vnums or initial_route_commands)
        ):
            route_vnums = initial_route_vnums
            if not initial_route_vnums:
                route_commands = initial_route_commands
        trivial_bystanders = trivial_bystanders_by_room.get(destination, ())
        crowd_retry_limit = _source_ranked_wander_crowd_retry_limit(
            mobile,
            world,
            room_vnum=destination,
        )
        stops.append(
            FieldHuntStop(
                route_commands,
                target,
                command_keyword=candidate.target_keyword,
                trivial_bystanders=trivial_bystanders,
                exact_target=True,
                source_mobile_vnum=candidate.mobile_vnum,
                source_mobile_room_description=mobile.room_description,
                source_policy_id=destination_policy_id,
                source_target_armed=source_target_armed,
                source_critical_hit_damage=(
                    source_critical_hit_damage or None
                ),
                source_loot_object_vnums=source_loot_object_vnums(destination),
                source_specials=tuple(candidate.specials),
                maximum_target_count=1,
                require_isolated=True,
                crowd_retry_limit=crowd_retry_limit,
                crowd_retry_delay_seconds=(
                    _SOURCE_RANKED_WANDER_CROWD_RETRY_DELAY_SECONDS
                    if crowd_retry_limit
                    else 0.0
                ),
                minimum_health_ratio=minimum_health_ratio,
                require_sanctuary=require_sanctuary,
                maximum_level_offset=maximum_level_offset,
                route_vnums=(
                    (str(candidate.room_vnum),)
                    if (
                        destination == candidate.room_vnum
                        and not route_vnums
                        and not route_commands
                    )
                    else route_vnums
                ),
            )
        )
    if len(stops) > (1 if locator_stop is not None else 0):
        return tuple(stops)
    fallback_crowd_retry_limit = _source_ranked_wander_crowd_retry_limit(
        mobile,
        world,
        room_vnum=candidate.room_vnum,
    )
    return (
        FieldHuntStop(
            (),
            target,
            command_keyword=candidate.target_keyword,
            exact_target=True,
            source_mobile_vnum=candidate.mobile_vnum,
            source_mobile_room_description=mobile.room_description,
            source_policy_id=source_policy_id,
            source_target_armed=source_target_armed,
            source_critical_hit_damage=(source_critical_hit_damage or None),
            source_loot_object_vnums=source_loot_object_vnums(
                candidate.room_vnum
            ),
            source_specials=tuple(candidate.specials),
            maximum_target_count=1,
            require_isolated=True,
            crowd_retry_limit=fallback_crowd_retry_limit,
            crowd_retry_delay_seconds=(
                _SOURCE_RANKED_WANDER_CROWD_RETRY_DELAY_SECONDS
                if fallback_crowd_retry_limit
                else 0.0
            ),
            minimum_health_ratio=minimum_health_ratio,
            require_sanctuary=require_sanctuary,
            maximum_level_offset=maximum_level_offset,
        ),
    )


def _source_ranked_wander_crowd_retry_limit(
    mobile: Any,
    world: Any,
    *,
    room_vnum: int,
) -> int:
    """Budget a roughly even chance for a crowded wanderer to move away."""
    if not mobile.wanders:
        return 0
    room = world.rooms.get(room_vnum)
    if room is None:
        return _SOURCE_RANKED_WANDER_CROWD_MIN_RETRIES
    reachable_exits = 0
    for exit_source in room.exits.values():
        destination = world.rooms.get(exit_source.destination)
        if destination is None or exit_source.closed:
            continue
        if not mobile.confused and (
            destination.no_mob
            or (
                mobile.stay_area
                and destination.area_file != room.area_file
            )
        ):
            continue
        reachable_exits += 1
    if reachable_exits <= 0:
        return 0
    # update.c runs mobile_update every four seconds and selects one of 32
    # direction values. Translate a 50% move chance into 12-second looks.
    move_probability = min(reachable_exits, 6) / 32.0
    updates = math.ceil(math.log(0.5) / math.log(1.0 - move_probability))
    retries = math.ceil(
        updates * 4 / _SOURCE_RANKED_WANDER_CROWD_RETRY_DELAY_SECONDS
    )
    return max(
        _SOURCE_RANKED_WANDER_CROWD_MIN_RETRIES,
        min(_SOURCE_RANKED_WANDER_CROWD_MAX_RETRIES, retries),
    )


def _source_ranked_fixed_single_reset(
    candidate: HuntCandidate,
    world: Any,
) -> bool:
    """Return whether a circuit target has one deterministic source room."""
    mobile = world.mobiles.get(candidate.mobile_vnum)
    if mobile is None or mobile.wanders or mobile.aggressive:
        return False
    matching_resets = [
        reset
        for reset in world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    ]
    return bool(
        candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and len(matching_resets) == 1
        and matching_resets[0].room_vnum == candidate.room_vnum
        and matching_resets[0].maximum_count == 1
    )


def _source_ranked_area_circuit_blocked_rooms(
    world: Any,
    *,
    character_level: int,
    state: Mapping[str, Any] | None = None,
) -> frozenset[int]:
    """Build the reusable useful-band hazard mask for area circuits."""
    useful_floor = character_level - 5
    raw_max_hp = (state or {}).get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    blocked_rooms: set[int] = set()
    for mobile_vnum in {
        reset.mobile_vnum for reset in world.mob_resets
    }:
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None:
            continue
        source_specials = tuple(world.mobile_specials.get(mobile.vnum, ()))
        special_transit_hazard = bool(source_specials) and not (
            _source_ranked_circuit_special_transit_safe(
                source_specials,
                state,
            )
        )
        matching_resets = tuple(
            reset
            for reset in world.mob_resets
            if reset.mobile_vnum == mobile.vnum
        )
        bounded_borderline_aggressor = bool(
            matching_resets
            and all(
                _bounded_borderline_route_aggressor(
                    world,
                    reset,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                )
                for reset in matching_resets
            )
        )
        if mobile.level + 2 <= useful_floor or not (
            mobile.aggressive or special_transit_hazard
        ) or bounded_borderline_aggressor:
            continue
        blocked_rooms.update(
            source_mobile_search_rooms(
                world,
                mobile.vnum,
                maximum_rooms=_SOURCE_RANKED_WANDER_SEARCH_LIMIT,
            )
        )
    return frozenset(blocked_rooms)


def _source_ranked_circuit_special_transit_safe(
    specials: Collection[str],
    state: Mapping[str, Any] | None,
) -> bool:
    """Allow only source-proven nonattacking specials on a circuit path."""
    economic_special_seen = False
    for special in specials:
        profile = source_special_profile(special)
        if special in TRANSIT_SAFE_COMBAT_ONLY_SPECIALS:
            continue
        if (
            special in SAFE_NONCOMBAT_SPECIALS
            and profile.risk == "noncombat"
            and profile.xp_bonus == 0
        ):
            continue
        if (
            special in ECONOMIC_SPECIALS
            and profile.risk == "economic"
            and profile.xp_bonus == 0
        ):
            economic_special_seen = True
            continue
        return False
    if not economic_special_seen:
        return True
    if state is None:
        return False
    carried_coins = _state_copper_value(dict(state))
    return carried_coins * 20 // 100 <= _SPEC_THIEF_MAX_EXPOSURE_COINS


def _source_ranked_inter_candidate_route(
    world: Any,
    origin: HuntCandidate,
    destination: HuntCandidate,
    *,
    character_level: int,
    blocked_rooms: Collection[int] | None = None,
    state: Mapping[str, Any] | None = None,
) -> tuple[str, ...] | None:
    """Return a short same-area route that excludes source combat hazards."""
    if origin.area_file != destination.area_file:
        return None
    if blocked_rooms is None:
        blocked_rooms = _source_ranked_area_circuit_blocked_rooms(
            world,
            character_level=character_level,
            state=state,
        )
    path = _shortest_paths_from(
        world.rooms,
        origin.room_vnum,
        blocked_rooms=blocked_rooms,
    ).get(destination.room_vnum)
    if path is None or len(path[0]) > _SOURCE_RANKED_AREA_CIRCUIT_ROUTE_LIMIT:
        return None
    if (
        state is not None
        and source_route_requires_flight(world, path[1])
        and not _source_ranked_movement_capability_available(state)
    ):
        return None
    if any(
        world.rooms.get(room_vnum) is None
        or world.rooms[room_vnum].area_file != destination.area_file
        for room_vnum in path[1]
    ):
        return None
    return tuple(str(room_vnum) for room_vnum in path[1][1:])


def _source_ranked_inter_route_live_navigation(
    world: Any,
    origin: HuntCandidate,
    destination: HuntCandidate,
    *,
    character_level: int,
    blocked_rooms: Collection[int] | None = None,
) -> dict[str, Any]:
    """Add live-GMCP navigation metadata to a same-area circuit leg."""
    if origin.area_file != destination.area_file:
        return {}
    if blocked_rooms is None:
        blocked_rooms = _source_ranked_area_circuit_blocked_rooms(
            world,
            character_level=character_level,
        )
    origin_paths = _shortest_paths_from(
        world.rooms,
        origin.room_vnum,
        blocked_rooms=blocked_rooms,
    )
    path = origin_paths.get(destination.room_vnum)
    if path is None or path[2]:
        return {}
    return _source_ranked_route_live_navigation(
        world,
        destination,
        character_level=character_level,
        origin_paths=origin_paths,
    )


def _source_ranked_movement_capability_available(
    state: Mapping[str, Any] | None,
) -> bool:
    """Return whether a live character can traverse a source water route."""
    if state is None:
        return True
    if any(
        _state_has_active_affect(state.get("affects"), affect_name)
        for affect_name in (
            "fly",
            "levitation",
            "swim",
            "mist walk",
            "astral sidestep",
        )
    ):
        return True
    race = state.get("race")
    if isinstance(race, str) and race.casefold().strip() in {
        "sahuagin",
        "grung",
    }:
        return True
    return _state_has_item(state.get("inventory"), "boat")


def _source_ranked_route_is_traversable(
    world: Any,
    path_rooms: Collection[int],
    state: Mapping[str, Any] | None,
) -> bool:
    """Reject water transitions whose live movement capability is absent."""
    return not (
        state is not None
        and source_route_requires_flight(world, path_rooms)
        and not _source_ranked_movement_capability_available(state)
    )


def _source_ranked_area_circuit_candidates(
    selected: HuntCandidate,
    candidates: Collection[HuntCandidate],
    world: Any,
    state: Mapping[str, Any],
    *,
    character_level: int,
    blocked_rooms: Collection[int] | None = None,
    allow_repeated_policy_ids: Collection[str] = (),
) -> tuple[HuntCandidate, ...]:
    """Choose additional one-kill probes reachable inside the selected area."""
    if (
        selected.is_coin_stash
        or selected.specials
        or selected.requires_flight
        or not _source_ranked_fixed_single_reset(selected, world)
    ):
        return ()
    max_hp = state.get("max_hp")
    character_max_hp = (
        int(max_hp)
        if isinstance(max_hp, (int, float)) and max_hp > 0
        else None
    )
    eligible: list[tuple[bool, int, HuntCandidate]] = []
    for index, candidate in enumerate(candidates):
        if (
            candidate == selected
            or candidate.area_file != selected.area_file
            or candidate.is_coin_stash
            or candidate.specials
            or candidate.requires_flight
            or not candidate.autonomous_safe
            or not _source_ranked_fixed_single_reset(candidate, world)
        ):
            continue
        status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        candidate_policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        candidate_repeat_ids = (
            frozenset(
                {candidate_policy_id}
            )
            if (
                status == "productive"
                or candidate_policy_id in allow_repeated_policy_ids
            )
            else frozenset()
        )
        if _select_source_ranked_hunt_candidate(
            (candidate,),
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_policy_ids=candidate_repeat_ids,
        ) is None:
            continue
        eligible.append((status != "productive", index, candidate))

    selected_extras: list[HuntCandidate] = []
    origin = selected
    for _, _, candidate in sorted(eligible):
        if _source_ranked_inter_candidate_route(
            world,
            origin,
            candidate,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
            state=state,
        ) is None:
            continue
        selected_extras.append(candidate)
        origin = candidate
        if (
            len(selected_extras) + 1
            >= _SOURCE_RANKED_AREA_CIRCUIT_TARGET_LIMIT
        ):
            break
    return tuple(selected_extras)


def _source_ranked_preferred_area_circuit(
    selected: HuntCandidate | None,
    candidates: Collection[HuntCandidate],
    world: Any,
    state: Mapping[str, Any],
    *,
    character_level: int,
    allow_repeated_policy_ids: Collection[str] = (),
) -> tuple[HuntCandidate | None, tuple[HuntCandidate, ...]]:
    """Prefer a high-throughput safe circuit over an ordinary singleton hunt.

    The highest-ranked source candidate may be a wandering mobile and therefore
    cannot itself anchor a fixed-reset circuit.  That must not hide a nearby
    fixed-reset area with several safe targets.  Compare those alternatives by
    source score per outbound/inter-target step, with only a mild peak-damage
    penalty so the planner balances XP/min against risk instead of treating
    every non-zero risk as disqualifying.
    """
    if selected is None:
        return None, ()
    ranked_candidates = tuple(candidates)
    blocked_rooms = _source_ranked_area_circuit_blocked_rooms(
        world,
        character_level=character_level,
        state=state,
    )
    throughput_limit = _active_source_ranked_throughput_limit(
        state,
        character_level=character_level,
    )
    if throughput_limit is not None:
        max_hp = state.get("max_hp")
        character_max_hp = (
            int(max_hp)
            if isinstance(max_hp, (int, float)) and max_hp > 0
            else None
        )
        circuit_options: list[
            tuple[HuntCandidate, tuple[HuntCandidate, ...]]
        ] = []
        seen_policy_ids: set[str] = set()
        for candidate in (
            selected,
            *ranked_candidates[:_SOURCE_RANKED_AREA_CIRCUIT_PRIMARY_SCAN_LIMIT],
        ):
            policy_id = _source_ranked_policy_id(
                candidate,
                character_level=character_level,
            )
            if policy_id in seen_policy_ids:
                continue
            seen_policy_ids.add(policy_id)
            status = _source_ranked_result_status(
                candidate,
                state,
                character_level=character_level,
            )
            candidate_repeat_ids = (
                frozenset({policy_id})
                if (
                    status == "productive"
                    or policy_id in allow_repeated_policy_ids
                )
                else frozenset()
            )
            if _select_source_ranked_hunt_candidate(
                (candidate,),
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                allow_repeated_policy_ids=candidate_repeat_ids,
            ) is None:
                continue
            extras = _source_ranked_area_circuit_candidates(
                candidate,
                ranked_candidates,
                world,
                state,
                character_level=character_level,
                blocked_rooms=blocked_rooms,
                allow_repeated_policy_ids=allow_repeated_policy_ids,
            )
            if extras:
                circuit_options.append((candidate, extras))
        if circuit_options:
            def throughput_rank(
                option: tuple[HuntCandidate, tuple[HuntCandidate, ...]],
            ) -> tuple[int, int, int, int, float, int]:
                primary, extras = option
                circuit = (primary, *extras)
                peak_damage = [
                    max(0, candidate.estimated_peak_round_damage)
                    for candidate in circuit
                ]
                return (
                    len(circuit),
                    -max(peak_damage, default=0),
                    -sum(peak_damage),
                    sum(candidate.estimated_level_range[1] for candidate in circuit),
                    sum(candidate.score for candidate in circuit),
                    -sum(len(candidate.route) for candidate in circuit),
                )

            return max(circuit_options, key=throughput_rank)
    circuit_options: list[
        tuple[HuntCandidate, tuple[HuntCandidate, ...]]
    ] = []
    if (
        not selected.specials
        and not selected.requires_flight
        and selected.autonomous_safe
        and _source_ranked_fixed_single_reset(selected, world)
    ):
        selected_extras = _source_ranked_area_circuit_candidates(
            selected,
            ranked_candidates,
            world,
            state,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
            allow_repeated_policy_ids=allow_repeated_policy_ids,
        )
        if selected_extras:
            circuit_options.append((selected, selected_extras))

    max_hp = state.get("max_hp")
    character_max_hp = (
        int(max_hp)
        if isinstance(max_hp, (int, float)) and max_hp > 0
        else None
    )
    for candidate in ranked_candidates[
        :_SOURCE_RANKED_AREA_CIRCUIT_PRIMARY_SCAN_LIMIT
    ]:
        if candidate == selected:
            continue
        if (
            candidate.specials
            or candidate.requires_flight
            or not candidate.autonomous_safe
            or not _source_ranked_fixed_single_reset(candidate, world)
        ):
            continue
        status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        candidate_repeat_ids = (
            frozenset(
                {policy_id}
            )
            if (
                status == "productive"
                or policy_id in allow_repeated_policy_ids
            )
            else frozenset()
        )
        if _select_source_ranked_hunt_candidate(
            (candidate,),
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_policy_ids=candidate_repeat_ids,
        ) is None:
            continue
        extras = _source_ranked_area_circuit_candidates(
            candidate,
            ranked_candidates,
            world,
            state,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
            allow_repeated_policy_ids=allow_repeated_policy_ids,
        )
        if extras:
            circuit_options.append((candidate, extras))
    if circuit_options:
        def circuit_rank(
            option: tuple[HuntCandidate, tuple[HuntCandidate, ...]],
        ) -> tuple[float, float, int, float, int, int]:
            primary, extras = option
            circuit = (primary, *extras)
            travel_steps = max(1, len(primary.route))
            origin = primary
            for candidate in extras:
                inter_route = _source_ranked_inter_candidate_route(
                    world,
                    origin,
                    candidate,
                    character_level=character_level,
                    blocked_rooms=blocked_rooms,
                    state=state,
                )
                travel_steps += len(inter_route or ())
                origin = candidate
            total_score = sum(max(0.0, item.score) for item in circuit)
            reward_per_step = total_score / max(1, travel_steps)
            peak_damage = max(
                (max(0, item.estimated_peak_round_damage) for item in circuit),
                default=0,
            )
            risk_ratio = (
                peak_damage / character_max_hp
                if character_max_hp
                else 0.0
            )
            risk_adjusted_efficiency = reward_per_step / (1.0 + risk_ratio)
            return (
                risk_adjusted_efficiency,
                reward_per_step,
                len(circuit),
                total_score,
                -risk_ratio,
                -travel_steps,
            )

        return max(circuit_options, key=circuit_rank)
    return selected, ()


def _source_ranked_circuit_hunt_stops(
    selected: HuntCandidate,
    circuit_candidates: Collection[HuntCandidate],
    world: Any,
    *,
    character_level: int,
    state: Mapping[str, Any] | None = None,
) -> tuple[FieldHuntStop, ...]:
    """Build one destination-guided stop sequence for several source targets."""
    circuit_candidates = tuple(circuit_candidates)
    blocked_rooms = _source_ranked_area_circuit_blocked_rooms(
        world,
        character_level=character_level,
        state=state,
    )
    stops = list(
        _source_ranked_hunt_stops(
            selected,
            world,
            character_level=character_level,
            state=state,
        )
    )
    origin = selected
    candidates_by_mobile_vnum = {
        candidate.mobile_vnum: candidate
        for candidate in (selected, *circuit_candidates)
    }
    for candidate in circuit_candidates:
        route_vnums = _source_ranked_inter_candidate_route(
            world,
            origin,
            candidate,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
            state=state,
        )
        if route_vnums is None:
            continue
        candidate_stops = list(
            _source_ranked_hunt_stops(
                candidate,
                world,
                character_level=character_level,
                state=state,
            )
        )
        if not candidate_stops:
            continue
        live_navigation = _source_ranked_inter_route_live_navigation(
            world,
            origin,
            candidate,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
        )
        candidate_stops[0] = replace(
            candidate_stops[0],
            route=(),
            route_vnums=route_vnums,
            **live_navigation,
        )
        stops.extend(candidate_stops)
        origin = candidate

    # The first target owns the full departure gate. Once a safe ordinary
    # fight is complete, keep using the field continuation threshold so a
    # small amount of recoverable damage does not collapse a multi-kill
    # circuit into one expensive journey per mobile.
    adjusted: list[FieldHuntStop] = []
    target_stop_seen = False
    for stop in stops:
        if stop.target is None:
            adjusted.append(stop)
            continue
        if not target_stop_seen:
            target_stop_seen = True
            adjusted.append(stop)
            continue
        candidate = candidates_by_mobile_vnum.get(
            stop.source_mobile_vnum or -1
        )
        high_risk = bool(
            stop.require_sanctuary
            or (
                candidate is not None
                and (
                    candidate.specials
                    or _SOURCE_PEAK_DAMAGE_REJECTION
                    in candidate.autonomy_rejections
                )
            )
        )
        continuation_ratio = (
            _SOURCE_RANKED_HIGH_RISK_CONTINUATION_HEALTH_RATIO
            if high_risk
            else _SOURCE_RANKED_CONTINUATION_HEALTH_RATIO
        )
        adjusted.append(
            replace(
                stop,
                minimum_health_ratio=min(
                    stop.minimum_health_ratio,
                    continuation_ratio,
                ),
            )
        )
    return tuple(adjusted)


def _source_ranked_segment_kill_limit(
    candidates: Collection[HuntCandidate],
    hunt_stops: Collection[FieldHuntStop],
    *,
    minimum: int = 1,
) -> int:
    """Bound a circuit by each targeted mobile global source capacity."""
    capacities: dict[int, int] = {}
    for candidate in candidates:
        capacities[candidate.mobile_vnum] = max(
            capacities.get(candidate.mobile_vnum, 0),
            candidate.source_spawn_limit,
        )
    targeted_mobile_vnums: set[int] = set()
    for stop in hunt_stops:
        if (
            stop.target is None
            or stop.source_mobile_vnum is None
            or stop.source_policy_id is None
        ):
            continue
        targeted_mobile_vnums.add(stop.source_mobile_vnum)
    # A wandering prototype uses one reusable policy id across every searched
    # room. Its source capacity can still place distinct live instances in
    # different rooms; each stop retains the exact-one room isolation gate.
    planned_kills = sum(
        max(1, capacities.get(mobile_vnum, 1))
        for mobile_vnum in targeted_mobile_vnums
    )
    return max(minimum, planned_kills, 1)


def _source_ranked_maximum_level_offset(candidate: HuntCandidate) -> int:
    """Return the live level ceiling for a source-ranked target."""
    if candidate.specials in {
        ("spec_breath_any",),
        ("spec_breath_gas",),
        ("spec_breath_lightning",),
    }:
        # The selector admits a nominally current-level lightning target
        # through additional source-fuzz steps, under sanctuary and the
        # full-health direct-damage bound. Carry the same ceiling into the
        # live fastwalk stop so executor and selector cannot disagree.
        return 2
    if candidate.specials == ("spec_thief",):
        # special.c steals only while standing and returns before that branch
        # once the mobile is fighting; retain ordinary live level fuzz here.
        return 1
    if (
        len(candidate.specials) == 1
        and candidate.specials[0] in SAFE_NONCOMBAT_SPECIALS
    ):
        # These source procedures do not add a combat action against a player,
        # so their audited current-band proof remains valid through one level
        # of ordinary DD4 mobile fuzz.
        return 1
    return (
        0
        if candidate.specials
        or _SOURCE_PEAK_DAMAGE_REJECTION in candidate.autonomy_rejections
        else 1
    )


def _source_ranked_special_candidate_in_live_level_ceiling(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Keep audited special-procedure targets within their live ceiling."""
    maximum_level_offset = _source_ranked_maximum_level_offset(candidate)
    if candidate.specials == ("spec_thief",) or (
        len(candidate.specials) == 1
        and candidate.specials[0] in SAFE_NONCOMBAT_SPECIALS
    ):
        # These procedures already have a source-backed one-level live-fuzz
        # exception. Their nominal source level is the admission boundary;
        # the runtime still verifies the actual live level before combat.
        return candidate.level <= character_level + maximum_level_offset
    if candidate.specials == ("spec_breath_lightning",):
        # Lightning breath has no acid/fire/frost/steam inventory side effect.
        # Permit one source-fuzz step above the ordinary special ceiling for a
        # nominally current-level target.  A source one level below the
        # character can also have a useful current-band roll (for example, a
        # level-17 eel at character level 18); admit that case through the
        # smaller +1 ceiling.  The HP and sanctuary bounds in
        # _source_ranked_candidate_in_current_band remain authoritative.
        if candidate.level not in {character_level - 1, character_level}:
            return False
        allowed_level_ceiling = character_level + (
            2 if candidate.level == character_level else 1
        )
        return (
            candidate.estimated_level_range[1] <= allowed_level_ceiling
        )
    if len(candidate.specials) == 1 and candidate.specials[0] in {
        "spec_breath_any",
        "spec_breath_gas",
    }:
        # ``magic.c`` bounds both generic and gas breath by the mobile's hit
        # points, while gas nausea is handled by the healer-return gate. A
        # A nominally current-level source prototype may therefore cross the
        # full two-level reset fuzz. A lower nominal level keeps the older,
        # ordinary ceiling, so a borderline target cannot become a generic
        # higher-level hunt merely because it has a breath special.
        maximum_level = candidate.estimated_level_range[1]
        if candidate.level == character_level:
            return maximum_level <= character_level + 2
        return maximum_level <= character_level
    return candidate.estimated_level_range[1] <= (
        character_level + maximum_level_offset
    )


def _source_mobile_candidate(
    world: Any,
    *,
    mobile_vnum: int,
    origin_room_vnum: int,
    target_keyword: str,
    target: str | None = None,
) -> HuntCandidate:
    """Build the minimal source identity needed for a registered mobile hunt."""
    mobile = world.mobiles.get(mobile_vnum)
    room = world.rooms.get(origin_room_vnum)
    reset = next(
        (
            value
            for value in world.mob_resets
            if value.mobile_vnum == mobile_vnum
            and value.room_vnum == origin_room_vnum
        ),
        None,
    )
    if mobile is None or room is None or reset is None:
        raise RuntimeError(
            "source mobile hunt identity drifted: "
            f"mobile={mobile_vnum} room={origin_room_vnum}"
        )
    source_identity = next(
        (
            identity
            for identity in source_mobile_identities(
                mobile.room_description,
                mobile.short_description,
                mobile.keywords,
            )
            if identity
        ),
        _source_mobile_identity(
            mobile.room_description,
            mobile.short_description,
            mobile.keywords,
        ),
    )
    effective_target = target or source_identity or mobile.short_description
    return HuntCandidate(
        status="caution",
        score=0.0,
        area_file=mobile.area_file,
        mobile_vnum=mobile_vnum,
        target=effective_target,
        target_keyword=target_keyword,
        level=mobile.level,
        room_vnum=origin_room_vnum,
        room_name=room.name,
        route=(),
        source_spawn_limit=reset.maximum_count,
        room_spawn_count=reset.maximum_count,
        boot_kills=0,
        loot=(),
        source_value=0,
        contained_coins=0,
        hazards=(),
        target_identity=target or source_identity,
        autonomy_rejections=(),
        specials=world.mobile_specials.get(mobile_vnum, ()),
        sentinel=mobile.sentinel,
        stay_area=mobile.stay_area,
    )


def _source_registered_hunt_stops(
    world: Any,
    *,
    mobile_vnum: int,
    origin_room_vnum: int,
    target_keyword: str,
    consider_only: bool,
    minimum_health_ratio: float,
    maximum_level_offset: int | None,
    target: str | None = None,
    abort_after_consider_rejection: bool = False,
    hunt_route_origin_room_vnum: int | None = None,
) -> tuple[FieldHuntStop, ...]:
    """Use source mobility flags for a named policy target as well as fallback hunts."""
    candidate = _source_mobile_candidate(
        world,
        mobile_vnum=mobile_vnum,
        origin_room_vnum=origin_room_vnum,
        target_keyword=target_keyword,
        target=target,
    )
    return tuple(
        replace(
            stop,
            consider_only=consider_only,
            minimum_health_ratio=minimum_health_ratio,
            maximum_level_offset=maximum_level_offset,
            abort_after_consider_rejection=abort_after_consider_rejection,
        )
        for stop in _source_ranked_hunt_stops(
            candidate,
            world,
            hunt_route_origin_room_vnum=hunt_route_origin_room_vnum,
        )
    )


def _source_ranked_policy_id(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> str:
    """Return a stable, character-independent identity for one source reset."""
    area = re.sub(
        r"[^a-z0-9]+",
        "-",
        Path(candidate.area_file).stem.casefold(),
    ).strip("-") or "area"
    return (
        f"{_SOURCE_RANKED_POLICY_PREFIX}{area}-"
        f"{candidate.mobile_vnum}-{candidate.room_vnum}-{character_level}"
    )


def _source_ranked_candidate_record(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_revision: str | None = None,
) -> dict[str, Any]:
    """Serialize the selected source candidate into a checkpoint-safe record."""
    record = {
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "status": candidate.status,
        "score": candidate.score,
        "area_file": candidate.area_file,
        "mobile_vnum": candidate.mobile_vnum,
        "target": candidate.target,
        "target_identity": candidate.target_identity,
        "target_keyword": candidate.target_keyword,
        "level": candidate.level,
        "room_vnum": candidate.room_vnum,
        "room_name": candidate.room_name,
        "route": list(candidate.route),
        "source_spawn_limit": candidate.source_spawn_limit,
        "room_spawn_count": candidate.room_spawn_count,
        "boot_kills": candidate.boot_kills,
        "loot": list(candidate.loot),
        "source_value": candidate.source_value,
        "contained_coins": candidate.contained_coins,
        "hazards": list(candidate.hazards),
        "equipped_weapons": list(candidate.equipped_weapons),
        "estimated_level_range": list(candidate.estimated_level_range),
        "estimated_base_hp_range": list(candidate.estimated_base_hp_range),
        "estimated_peak_round_damage": candidate.estimated_peak_round_damage,
        "estimated_min_peak_round_damage": candidate.estimated_min_peak_round_damage,
        "estimated_critical_hit_damage": candidate.estimated_critical_hit_damage,
        "autonomy_rejections": list(candidate.autonomy_rejections),
        "specials": list(candidate.specials),
        "route_preflight_room_vnum": candidate.route_preflight_room_vnum,
        "route_preflight_command": candidate.route_preflight_command,
        "route_preflight_target": candidate.route_preflight_target,
        "route_preflight_level_range": list(candidate.route_preflight_level_range),
        "route_preflight_hard_hazard": candidate.route_preflight_hard_hazard,
        "route_hard_hazard_targets": list(candidate.route_hard_hazard_targets),
        "sentinel": candidate.sentinel,
        "stay_area": candidate.stay_area,
        "estimated_move_cost": candidate.estimated_move_cost,
        "estimated_flying_move_cost": candidate.estimated_flying_move_cost,
        "requires_flight": candidate.requires_flight,
        "ground_loot_keywords": list(candidate.ground_loot_keywords),
        "ground_loot_object_vnums": list(
            candidate.ground_loot_object_vnums
        ),
        "is_coin_stash": candidate.is_coin_stash,
        "is_food_stash": candidate.is_food_stash,
    }
    if source_revision:
        record["source_revision"] = source_revision
    return record


def _source_ranked_candidate_from_record(
    value: object,
    *,
    source_revision: str | None = None,
) -> HuntCandidate | None:
    """Restore a selected source candidate after a disconnect or process exit."""
    if not isinstance(value, Mapping):
        return None
    if source_revision is not None and value.get("source_revision") != source_revision:
        return None

    def text_tuple(key: str) -> tuple[str, ...]:
        raw = value.get(key)
        if not isinstance(raw, (list, tuple)):
            return ()
        return tuple(str(item) for item in raw)

    def int_pair(key: str) -> tuple[int, int]:
        raw = value.get(key)
        if not isinstance(raw, (list, tuple)) or len(raw) != 2:
            return (0, 0)
        try:
            return int(raw[0]), int(raw[1])
        except (TypeError, ValueError):
            return (0, 0)

    try:
        area_file = str(value.get("area_file") or "")
        target = str(value.get("target") or "")
        target_keyword = str(value.get("target_keyword") or "")
        if not area_file or not target or not target_keyword:
            return None
        return HuntCandidate(
            status=str(value.get("status") or "caution"),
            score=float(value.get("score") or 0),
            area_file=area_file,
            mobile_vnum=int(value.get("mobile_vnum") or 0),
            target=target,
            target_identity=str(value.get("target_identity") or ""),
            target_keyword=target_keyword,
            level=int(value.get("level") or 0),
            room_vnum=int(value.get("room_vnum") or 0),
            room_name=str(value.get("room_name") or ""),
            route=text_tuple("route"),
            source_spawn_limit=int(value.get("source_spawn_limit") or 0),
            room_spawn_count=int(value.get("room_spawn_count") or 0),
            boot_kills=int(value.get("boot_kills") or 0),
            loot=text_tuple("loot"),
            source_value=int(value.get("source_value") or 0),
            contained_coins=int(value.get("contained_coins") or 0),
            hazards=text_tuple("hazards"),
            equipped_weapons=text_tuple("equipped_weapons"),
            estimated_level_range=int_pair("estimated_level_range"),
            estimated_base_hp_range=int_pair("estimated_base_hp_range"),
            estimated_peak_round_damage=int(
                value.get("estimated_peak_round_damage") or 0
            ),
            estimated_min_peak_round_damage=int(
                value.get("estimated_min_peak_round_damage") or 0
            ),
            estimated_critical_hit_damage=int(
                value.get("estimated_critical_hit_damage") or 0
            ),
            autonomy_rejections=text_tuple("autonomy_rejections"),
            specials=text_tuple("specials"),
            route_preflight_room_vnum=(
                str(value["route_preflight_room_vnum"])
                if value.get("route_preflight_room_vnum") is not None
                else None
            ),
            route_preflight_command=(
                str(value["route_preflight_command"])
                if value.get("route_preflight_command") is not None
                else None
            ),
            route_preflight_target=(
                str(value["route_preflight_target"])
                if value.get("route_preflight_target") is not None
                else None
            ),
            route_preflight_level_range=int_pair(
                "route_preflight_level_range"
            ),
            route_preflight_hard_hazard=bool(
                value.get("route_preflight_hard_hazard", False)
            ),
            route_hard_hazard_targets=text_tuple("route_hard_hazard_targets"),
            sentinel=bool(value["sentinel"])
            if "sentinel" in value
            else True,
            stay_area=bool(value["stay_area"])
            if "stay_area" in value
            else True,
            estimated_move_cost=int(value.get("estimated_move_cost") or 0),
            estimated_flying_move_cost=int(
                value.get("estimated_flying_move_cost") or 0
            ),
            requires_flight=bool(value.get("requires_flight", False)),
            ground_loot_keywords=text_tuple("ground_loot_keywords"),
            ground_loot_object_vnums=tuple(
                int(item)
                for item in (
                    value.get("ground_loot_object_vnums") or ()
                )
            ),
            is_coin_stash=bool(value.get("is_coin_stash", False)),
            is_food_stash=bool(value.get("is_food_stash", False)),
        )
    except (TypeError, ValueError):
        return None


def _source_ranked_circuit_from_record(
    value: object,
    *,
    source_revision: str | None = None,
) -> tuple[HuntCandidate, ...]:
    """Restore supplementary source targets from a checkpointed candidate."""
    if not isinstance(value, Mapping):
        return ()
    raw_circuit = value.get("circuit")
    if not isinstance(raw_circuit, (list, tuple)):
        return ()
    restored = []
    for raw_candidate in raw_circuit:
        candidate = _source_ranked_candidate_from_record(
            raw_candidate,
            source_revision=source_revision,
        )
        if candidate is not None:
            restored.append(candidate)
    return tuple(restored)


def _source_mobile_kill_counts_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> Counter[int]:
    """Count source-ranked kills by mobile prototype, not display name.

    DD4 can have distinct mobile prototypes with the same short description.
    Campaign segment evidence retains the selected source VNUM, so use that
    identity when applying reboot-local kill caps to source candidates.
    """
    counts: Counter[int] = Counter()
    for segment in segments:
        if not _execution_records_objective_kills(
            str(segment.get("phase") or "")
        ):
            continue
        try:
            start_raw = segment.get("start_state_json")
            end_raw = segment.get("end_state_json")
        except AttributeError:
            continue
        if not isinstance(end_raw, str):
            continue
        try:
            start = json.loads(start_raw) if isinstance(start_raw, str) else {}
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        candidate_record = end.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            continue
        try:
            mobile_vnum = int(candidate_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        if mobile_vnum <= 0:
            continue
        # A field run can kill an incidental mobile while its selected source
        # target is rejected.  Only deliberate objective kills may consume
        # the selected source mobile's reboot-local cap.  Preserve the legacy
        # fallback for older segment records that did not persist the
        # objective-kill field.
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if not isinstance(kills, list) or not kills:
            continue
        untagged_kills = 0
        for kill in kills:
            if not isinstance(kill, Mapping):
                untagged_kills += 1
                continue
            try:
                kill_mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
            except (TypeError, ValueError):
                kill_mobile_vnum = 0
            if kill_mobile_vnum > 0:
                counts[kill_mobile_vnum] += 1
            else:
                untagged_kills += 1
        # Preserve source-VNUM accounting for historical records and for any
        # incidental objective entry that predates per-stop identity tags.
        counts[mobile_vnum] += untagged_kills
    return counts


def _source_mobile_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
    best: bool,
) -> dict[int, int]:
    """Return each source mobile's latest or best objective reward this reboot."""
    latest: dict[int, int] = {}
    for segment in segments:
        if not _execution_records_objective_kills(
            str(segment.get("phase") or "")
        ):
            continue
        end_raw = segment.get("end_state_json")
        if not isinstance(end_raw, str):
            continue
        start_raw = segment.get("start_state_json")
        try:
            start = json.loads(start_raw) if isinstance(start_raw, str) else {}
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            start = {}
            end = {}
        if not isinstance(start, Mapping):
            start = {}
        if not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        candidate_record = end.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = None
        try:
            selected_mobile_vnum = int(
                (candidate_record or {}).get("mobile_vnum") or 0
            )
        except (TypeError, ValueError):
            selected_mobile_vnum = 0
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if not isinstance(kills, list):
            continue
        for kill in kills:
            if not isinstance(kill, Mapping):
                continue
            try:
                mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
                xp_gained = int(kill.get("xp_gained") or 0)
            except (TypeError, ValueError):
                mobile_vnum = 0
                xp_gained = 0
            if mobile_vnum <= 0:
                # Older source-ranked segments stored the selected target's
                # name and XP but not its prototype VNUM. The selected
                # candidate is the same durable identity used by the legacy
                # kill-count fallback, so carry that reward across a level
                # boundary without assigning it to an unrelated mobile.
                mobile_vnum = selected_mobile_vnum
            if mobile_vnum > 0:
                reward = max(0, xp_gained)
                if best:
                    latest[mobile_vnum] = max(
                        latest.get(mobile_vnum, 0),
                        reward,
                    )
                else:
                    latest[mobile_vnum] = reward
    return latest


def _source_mobile_latest_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> dict[int, int]:
    """Return each source mobile's latest objective reward this reboot."""
    return _source_mobile_xp_from_segments(
        segments,
        boot_id=boot_id,
        best=False,
    )


def _source_mobile_best_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> dict[int, int]:
    """Return each source mobile's best objective reward this reboot."""
    return _source_mobile_xp_from_segments(
        segments,
        boot_id=boot_id,
        best=True,
    )


def _source_mobile_recent_kill_vnums_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
    cooldown_segments: int = _SOURCE_RANKED_POST_KILL_COOLDOWN_SEGMENTS,
) -> frozenset[int]:
    """Block a killed source prototype for two later source hunt segments."""
    if cooldown_segments <= 0:
        return frozenset()
    recent: set[int] = set()
    later_source_segments = 0
    for segment in reversed(tuple(segments)):
        if later_source_segments >= cooldown_segments:
            break
        phase = str(segment.get("phase") or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if str(segment.get("status") or "") not in {"success", "ready"}:
            continue
        end_raw = segment.get("end_state_json")
        if not isinstance(end_raw, str):
            continue
        try:
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if isinstance(kills, list):
            for kill in kills:
                if not isinstance(kill, Mapping):
                    continue
                try:
                    mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
                except (TypeError, ValueError):
                    continue
                if mobile_vnum > 0:
                    recent.add(mobile_vnum)
        later_source_segments += 1
    return frozenset(recent)


def _source_ranked_kill_policy_ids(kills: object) -> tuple[str, ...]:
    """Return distinct source policy identities attached to objective kills."""
    if not isinstance(kills, (list, tuple)):
        return ()
    policy_ids = []
    for kill in kills:
        if not isinstance(kill, Mapping):
            continue
        policy_id = str(kill.get("source_policy_id") or "")
        if (
            policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and policy_id not in policy_ids
        ):
            policy_ids.append(policy_id)
    return tuple(policy_ids)


def _objective_kill_xp_stats(kills: object) -> tuple[int, int, bool]:
    """Return total, best, and presence of explicit XP evidence."""
    if not isinstance(kills, (list, tuple)):
        return 0, 0, False
    values: list[int] = []
    saw_xp = False
    for kill in kills:
        if not isinstance(kill, Mapping):
            continue
        saw_xp = saw_xp or "xp_gained" in kill
        try:
            values.append(max(0, int(kill.get("xp_gained") or 0)))
        except (TypeError, ValueError):
            continue
    return sum(values), max(values, default=0), saw_xp


def _source_ranked_target_tokens(candidate: HuntCandidate) -> frozenset[str]:
    identity_tokens = frozenset(
        token
        for token in re.findall(
            r"[a-z0-9]+",
            _source_ranked_target_identity(candidate),
        )
        if token not in {"a", "an", "the"}
    )
    keyword_tokens = frozenset(
        token
        for token in re.findall(r"[a-z0-9]+", candidate.target_keyword.casefold())
        if token not in {"a", "an", "the"}
    )
    if keyword_tokens and keyword_tokens.issubset(identity_tokens):
        return keyword_tokens
    return identity_tokens


def _source_ranked_result_status(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    allow_cooldown_retry: bool = False,
) -> str:
    """Classify a candidate against current-reboot research evidence."""
    boot_id = state.get("world_boot_id")
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    crowd_cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    matching_results: list[tuple[str, Mapping[str, Any]]] = []
    target_tokens = _source_ranked_target_tokens(candidate)
    for raw_policy_id, raw_result in results.items():
        policy_id = str(raw_policy_id)
        if not isinstance(raw_result, Mapping):
            continue
        if raw_result.get("boot_id") != boot_id:
            continue
        if policy_id == candidate_policy_id:
            matching_results.append((policy_id, raw_result))
            continue
        # Source-ranked policy ids include the source mobile and reset room.
        # Do not fall back to target-word matching here: one crowded or absent
        # reset must not suppress another source reset for the same mobile.
        # Legacy named policies below still use the alias path so older
        # research evidence can continue to inform the generic frontier.
        if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        policy_tokens = frozenset(re.findall(r"[a-z0-9]+", policy_id))
        if target_tokens and target_tokens.issubset(policy_tokens):
            matching_results.append((policy_id, raw_result))

    retryable = False
    cooldown_active = False
    productive = False
    low_reward = False
    productive_history = _state_productive_policy_ids(state)
    history_is_present = isinstance(
        state.get(_PRODUCTIVE_POLICY_HISTORY_KEY),
        Mapping,
    )
    for policy_id, result in matching_results:
        if result.get("crowd_exhausted") is True:
            # A source-ranked route has already checked its source-vetted
            # destinations twice in this reboot.  Its target may still be
            # present, but replaying the same crowded route is no longer a
            # useful discovery action until the area state changes.
            cooldown_active = True
            continue
        if result.get("unattackable"):
            # A live unattackable response is a static command boundary for
            # this mobile, not a temporary absence or failed route. Legacy
            # target aliases can still surface that evidence for a newer
            # source-ranked reset policy, so never turn it into a retryable
            # candidate.
            cooldown_active = True
            continue
        if result.get("target_vnum_mismatch"):
            # A target line can be shared by distinct source mobiles. Once
            # GMCP identifies the live VNUM, never retry a source policy that
            # was aimed at the wrong prototype.
            cooldown_active = True
            continue
        if result.get("consider_viable") is False:
            # A live negative consider is level-band evidence, not a failed
            # combat attempt. Keep the target closed until level or reboot
            # changes rather than replaying it after a short cooldown.
            cooldown_active = True
            continue
        if result.get("viable") is True and result.get("completed_kill") is True:
            if (
                history_is_present
                and candidate_policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and "-hunt-" in candidate_policy_id
                and candidate_policy_id not in productive_history
            ):
                # A wandering kill may have been recorded under its selected
                # anchor room. Once startup rebuilds history from the tagged
                # source VNUM, that anchor result is no longer productive.
                continue
            if result.get("low_reward") is True:
                low_reward = True
                continue
            if "max_objective_kill_xp" in result:
                try:
                    max_kill_xp = int(result.get("max_objective_kill_xp") or 0)
                except (TypeError, ValueError):
                    max_kill_xp = 0
                if max_kill_xp < _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP:
                    # Preserve the observation, but do not let a low-value
                    # target become the campaign's productive repeat.
                    low_reward = True
                    continue
            if result.get("crowded") is True:
                try:
                    remaining = max(
                        int(cooldowns.get(policy_id) or 0),
                        int(crowd_cooldowns.get(policy_id) or 0),
                    )
                except (TypeError, ValueError):
                    remaining = 0
                if remaining > 0:
                    cooldown_active = True
                else:
                    retryable = True
                continue
            productive = True
            continue
        if result.get("route_hazard"):
            if not _is_retryable_dynamic_route_hazard(
                policy_id,
                result.get("route_hazard"),
            ):
                # Static legacy route hazards are still hard exclusions. A
                # dynamic no-combat interruption is different: its cooldown
                # can expire and reopen a newer source-ranked alias.
                cooldown_active = True
                continue
        if _is_capability_blocked_source_ranked_route_hazard(
            policy_id,
            result.get("route_hazard"),
        ):
            # Swimming, boats, and other missing movement capabilities are
            # character-state blockers, not reboot-local target absences.
            # Skip this route for the current frontier even when a reset retry
            # was requested; a later source candidate may still be executable.
            cooldown_active = True
            continue
        negative = bool(
            result.get("absent") is True
            or result.get("crowded") is True
            or result.get("route_hazard")
            or result.get("unattackable")
            or result.get("target_vnum_mismatch")
            or result.get("viable") is False
            or result.get("completed_kill") is False
        )
        if not negative:
            continue
        try:
            remaining = max(
                int(cooldowns.get(policy_id) or 0),
                int(crowd_cooldowns.get(policy_id) or 0),
            )
        except (TypeError, ValueError):
            remaining = 0
        if remaining > 0:
            if allow_cooldown_retry and (
                result.get("absent") is True
                or result.get("retryable_failure") is True
            ):
                retryable = True
            else:
                cooldown_active = True
        else:
            retryable = True
    if not matching_results:
        # Metadata repair can preserve a reboot-local cooldown after the
        # result payload that created it has been cleared. Treat that marker
        # as authoritative until the reset controller explicitly consumes it;
        # otherwise the same source reset becomes fresh too early.
        try:
            orphaned_cooldown = max(
                int(cooldowns.get(candidate_policy_id) or 0),
                int(crowd_cooldowns.get(candidate_policy_id) or 0),
            )
        except (AttributeError, TypeError, ValueError):
            orphaned_cooldown = 0
        if orphaned_cooldown > 0:
            cooldown_active = True
    if cooldown_active:
        return "cooldown"
    if retryable:
        return "retryable"
    if productive:
        return "productive"
    if low_reward:
        return "low_reward"
    return "fresh"


def _source_ranked_frontier_retry_attempted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether the current reboot already used its one frontier retry."""
    record = state.get(_SOURCE_RANKED_FRONTIER_RETRY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("boot_id") != state.get("world_boot_id"):
        return False
    policy_ids = record.get("policy_ids")
    if not isinstance(policy_ids, (list, tuple, set, frozenset)):
        return False
    return policy_id in {str(value) for value in policy_ids}


def _source_ranked_frontier_retry_candidate(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Allow one bounded retry for a live target after the normal frontier stalls."""
    if not candidate.autonomous_safe:
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_frontier_retry_attempted(state, policy_id):
        return False
    if not _source_ranked_candidate_in_current_band(
        candidate,
        state,
        character_level=character_level,
    ):
        return False
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
        )
    ):
        return False
    if not (
        result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("completed_kill") is False
        and result.get("retryable_failure") is True
    ):
        return False
    return (
        _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        == "cooldown"
    )


def _record_source_ranked_frontier_retry(
    state: dict[str, Any],
    *,
    policy_id: str,
) -> None:
    """Persist the one-attempt guard before a live frontier retry starts."""
    record = state.get(_SOURCE_RANKED_FRONTIER_RETRY_KEY)
    policy_ids: set[str] = set()
    if (
        isinstance(record, Mapping)
        and record.get("boot_id") == state.get("world_boot_id")
        and isinstance(record.get("policy_ids"), (list, tuple, set, frozenset))
    ):
        policy_ids = {str(value) for value in record["policy_ids"]}
    policy_ids.add(policy_id)
    state[_SOURCE_RANKED_FRONTIER_RETRY_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "policy_ids": sorted(policy_ids),
    }


def _source_ranked_policy_needs_rotation(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    character_level: int,
    retry_stalled: bool,
) -> bool:
    """Rotate a persisted source route after a current-reboot field result.

    A retry-stalled invocation may reopen a route blocked only by trailing
    no-progress history, but it must still rotate away from current-reboot
    absence, crowd, route, and viability evidence.
    """
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return False
    candidate = _source_ranked_candidate_from_record(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=state.get(_SOURCE_REVISION_KEY),
    )
    if candidate is None or _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    ) != policy_id:
        return False
    result = _campaign_research_results(state).get(policy_id)
    boot_id = state.get("world_boot_id")
    if isinstance(result, Mapping) and result.get("boot_id") == boot_id:
        if any(
            (
                result.get("absent") is True,
                result.get("crowded") is True,
                result.get("crowd_exhausted") is True,
                result.get("route_hazard"),
                result.get("unattackable"),
                result.get("target_vnum_mismatch"),
                result.get("viable") is False,
                result.get("completed_kill") is False,
            )
        ):
            return True
        if (
            not retry_stalled
            and result.get("completed_kill") is True
            and result.get("viable") is True
        ):
            return True
    if state.get("campaign_last_policy") != policy_id:
        return False
    if state.get("campaign_fastwalk_target_absent") or state.get(
        "campaign_fastwalk_crowded"
    ) or state.get("campaign_fastwalk_abort_reason"):
        return True
    if retry_stalled:
        return False
    return False


def _source_ranked_retry_exclusion(state: Mapping[str, Any]) -> str:
    """Return the non-productive retry exclusion for the current reboot."""
    policy_id = str(state.get(_SOURCE_RANKED_RETRY_EXHAUSTED_KEY) or "")
    marker_boot = state.get(_SOURCE_RANKED_RETRY_EXHAUSTED_BOOT_KEY)
    current_boot = state.get("world_boot_id")
    if marker_boot and current_boot and marker_boot != current_boot:
        return ""
    return policy_id


def _source_ranked_retry_marker_should_clear(
    state: Mapping[str, Any],
    *,
    source_ranked_progress_xp: int,
) -> bool:
    """Keep a long absent route closed after only minimum-value contact."""
    if source_ranked_progress_xp <= 0:
        return False
    policy_id = _source_ranked_retry_exclusion(state)
    if not policy_id:
        return True
    result = _campaign_research_results(state).get(policy_id)
    return not (
        source_ranked_progress_xp <= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        and isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("absent") is True
    )


def _active_source_ranked_throughput_limit(
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> Mapping[str, Any] | None:
    """Return same-level evidence that one kill exhausted field reserves."""
    marker = state.get(_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY)
    if not isinstance(marker, Mapping):
        return None
    try:
        marker_level = int(marker.get("level") or -1)
    except (TypeError, ValueError):
        return None
    if marker_level != character_level:
        return None
    policy_id = str(marker.get("policy_id") or "")
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return None
    return marker


def _source_ranked_training_reaudit_required(
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Force one fresh trainer listing after measured low hunt throughput."""
    marker = _active_source_ranked_throughput_limit(
        state,
        character_level=character_level,
    )
    return bool(
        marker is not None
        and (
            not marker.get("training_reaudit_completed")
            or marker.get("training_reaudit_policy_revision")
            != _CAMPAIGN_POLICY_REVISION
        )
    )


def _training_policy_revision_stale(state: Mapping[str, Any]) -> bool:
    """Return whether the persisted trainer audit predates this policy graph."""
    try:
        revision = int(state.get(_TRAINING_POLICY_REVISION_KEY) or -1)
    except (TypeError, ValueError):
        return True
    return revision != _CAMPAIGN_POLICY_REVISION


def _with_source_ranked_throughput_reaudit(
    start_state: Mapping[str, Any],
    end_state: Mapping[str, Any],
    *,
    character_level: int,
    run_id: int,
    training_complete: bool,
    gear_audit_complete: bool,
) -> dict[str, Any]:
    """Attach completed repair evidence without clearing the throughput gate."""
    merged = dict(end_state)
    if not training_complete or _active_source_ranked_throughput_limit(
        start_state,
        character_level=character_level,
    ) is None:
        return merged
    current = merged.get(_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY)
    if not isinstance(current, Mapping):
        return merged
    marker = dict(current)
    marker.update(
        {
            "training_reaudit_completed": True,
            "training_reaudit_run_id": run_id,
            "training_reaudit_policy_revision": _CAMPAIGN_POLICY_REVISION,
            "gear_audit_completed": gear_audit_complete,
        }
    )
    merged[_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY] = marker
    return merged


def _select_source_ranked_hunt_candidate(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None = None,
    allow_cooldown_retry: bool = False,
    allow_retry_exhausted_repeat: bool = False,
    allow_frontier_retry: bool = False,
    allow_no_progress_fallback: bool = True,
    allow_sanctuary_recovery: bool = False,
    allow_repeated_policy_ids: Collection[str] = (),
    additional_blocked_policy_ids: Collection[str] = (),
) -> HuntCandidate | None:
    """Choose the safest fresh current-band source target for one segment."""
    if character_level < _SOURCE_RANKED_FALLBACK_MINIMUM_LEVEL:
        return None
    valid: list[tuple[HuntCandidate, str]] = []
    capacity_research: list[tuple[HuntCandidate, str]] = []
    level_ceiling_probes: list[tuple[HuntCandidate, str]] = []
    bounded_peak_probes: list[tuple[HuntCandidate, str]] = []
    protected_peak_probes: list[tuple[HuntCandidate, str]] = []
    dynamic_wanderer_probes: list[tuple[HuntCandidate, str]] = []
    audited_specials: list[tuple[HuntCandidate, str]] = []
    sanctuary_recovery: list[tuple[HuntCandidate, str]] = []
    for candidate in candidates:
        if _source_ranked_candidate_excluded_by_below_band_evidence(
            candidate,
            state,
            character_level=character_level,
        ):
            # A live below-band consider applies to the source mobile, not
            # only to the reset room used for that particular segment.
            continue
        candidate_policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if _source_ranked_candidate_blocked_by_protection_recovery(
            candidate,
            state,
            character_level=character_level,
        ):
            continue
        current_band = _source_ranked_candidate_in_current_band(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_kills=(
                candidate_policy_id in allow_repeated_policy_ids
            ),
        )
        protected_peak_probe_in_band = (
            _source_ranked_protected_peak_probe_in_current_band(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                allow_repeated_kills=(
                    candidate_policy_id in allow_repeated_policy_ids
                ),
            )
        )
        dynamic_wanderer_probe_in_band = current_band and (
            _source_ranked_dynamic_wanderer_probe_allowed(
                candidate,
                character_level=character_level,
                character_max_hp=character_max_hp,
                allow_cooldown_retry=allow_cooldown_retry,
            )
            or (
                candidate_policy_id in allow_repeated_policy_ids
                and _source_ranked_dynamic_wanderer_repeatability_allowed(
                    candidate,
                    state,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                )
            )
        )
        level_ceiling_probe_in_band = False
        if not current_band:
            capacity_research_in_band = (
                _source_ranked_capacity_research_in_current_band(
                    candidate,
                    state,
                    character_level=character_level,
                    allow_repeated_kills=(
                        candidate_policy_id in allow_repeated_policy_ids
                    ),
                )
            )
            level_ceiling_probe_in_band = (
                _source_ranked_level_ceiling_probe_in_current_band(
                    candidate,
                    state,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                    allow_repeated_kills=(
                        candidate_policy_id in allow_repeated_policy_ids
                    ),
                )
            )
            bounded_peak_probe_in_band = (
                _source_ranked_bounded_peak_probe_in_current_band(
                    candidate,
                    state,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                    allow_cooldown_retry=allow_cooldown_retry,
                    allow_repeated_kills=(
                        candidate_policy_id in allow_repeated_policy_ids
                    ),
                )
            )
            if not (
                capacity_research_in_band
                or level_ceiling_probe_in_band
                or bounded_peak_probe_in_band
                or protected_peak_probe_in_band
            ):
                continue
        status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
            allow_cooldown_retry=allow_cooldown_retry,
        )
        if (
            status == "fresh"
            and candidate_policy_id in allow_repeated_policy_ids
        ):
            # A level transition changes the generated policy suffix even
            # though the source mobile and reboot-local reward evidence are
            # unchanged. Let that proven cross-level repeat compete with
            # other productive routes instead of ranking below a much weaker
            # current-level repeat solely because its new policy ID is fresh.
            status = "productive"
        if candidate.autonomous_safe or (
            _source_ranked_candidate_has_only_safe_noncombat_special_rejections(
                candidate
            )
        ):
            if current_band:
                valid.append((candidate, status))
            elif level_ceiling_probe_in_band:
                level_ceiling_probes.append((candidate, status))
        elif _source_ranked_capacity_research_candidate(candidate):
            capacity_research.append((candidate, status))
        elif _source_ranked_bounded_peak_probe_allowed(
            candidate,
            state=state,
            character_max_hp=character_max_hp,
            allow_cooldown_retry=allow_cooldown_retry,
        ):
            bounded_peak_probes.append((candidate, status))
        elif protected_peak_probe_in_band:
            protected_peak_probes.append((candidate, status))
        elif dynamic_wanderer_probe_in_band:
            dynamic_wanderer_probes.append((candidate, status))
        elif _audited_source_special_candidate_allowed(
            candidate,
            state=state,
            character_max_hp=character_max_hp,
        ) and _source_ranked_special_candidate_in_live_level_ceiling(
            candidate,
            character_level=character_level,
        ):
            audited_specials.append((candidate, status))
        elif (
            allow_sanctuary_recovery
            and _source_ranked_candidate_requires_sanctuary(candidate)
        ):
            recovery_state = dict(state)
            recovery_pouch = dict(
                recovery_state.get("combat_pouch_potions") or {}
            )
            recovery_pouch["purple"] = max(
                2,
                int(recovery_pouch.get("purple") or 0),
            )
            recovery_state["combat_pouch_potions"] = recovery_pouch
            if _audited_source_special_candidate_allowed(
                candidate,
                state=recovery_state,
                character_max_hp=character_max_hp,
            ) and _source_ranked_special_candidate_in_live_level_ceiling(
                candidate,
                character_level=character_level,
            ):
                sanctuary_recovery.append((candidate, status))
    if (
        not valid
        and not capacity_research
        and not level_ceiling_probes
        and not bounded_peak_probes
        and not protected_peak_probes
        and not dynamic_wanderer_probes
    ):
        valid = audited_specials or sanctuary_recovery
    if (
        not valid
        and not capacity_research
        and not level_ceiling_probes
        and not bounded_peak_probes
        and not protected_peak_probes
        and not dynamic_wanderer_probes
    ):
        return None

    last_policy_id = str(state.get("campaign_last_policy") or "")
    retry_exhausted_policy_id = _source_ranked_retry_exclusion(state)
    if (
        allow_retry_exhausted_repeat
        and retry_exhausted_policy_id in set(allow_repeated_policy_ids)
    ):
        # ``retry-stalled`` is an explicit recovery request. Reopen only a
        # same-reboot route whose latest kill remained meaningful; ordinary
        # selection and unrelated cooldowns continue honoring the marker.
        retry_exhausted_policy_id = ""
    throughput_limit = _active_source_ranked_throughput_limit(
        state,
        character_level=character_level,
    )
    throughput_limited_policy_id = (
        str(throughput_limit.get("policy_id") or "")
        if throughput_limit is not None
        else ""
    )
    blocked_policy_ids = {
        policy_id
        for policy_id in (
            last_policy_id,
            retry_exhausted_policy_id,
            throughput_limited_policy_id,
        )
        if policy_id
    }
    additional_blocked = {
        str(policy_id) for policy_id in additional_blocked_policy_ids
    }
    blocked_policy_ids.update(additional_blocked)
    if (
        _has_independent_productive_source_history(state)
        and _research_retry_cooldown_active(
            state,
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
        )
        and _protection_recovery_required(state)
    ):
        # A protection failure must keep its sanctuary recovery requirement,
        # but a current-reboot productive route is still a valid fallback when
        # the recovery route is cooling.  Remove only the trailing no-progress
        # block; the last-policy, absence, crowd, health, and live-consider
        # gates remain authoritative.
        blocked_policy_ids.difference_update(
            additional_blocked.intersection(
                _state_productive_policy_ids(state)
            )
        )

    def candidate_policy_id(candidate: HuntCandidate) -> str:
        return _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )

    persisted = _source_ranked_candidate_from_record(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=state.get(_SOURCE_REVISION_KEY),
    )
    if (
        persisted is not None
        and candidate_policy_id(persisted) == last_policy_id
        and candidate_policy_id(persisted) not in blocked_policy_ids
        and _source_ranked_result_status(
            persisted,
            state,
            character_level=character_level,
            allow_cooldown_retry=allow_cooldown_retry,
        )
        == "fresh"
    ):
        return persisted

    def rank(item: tuple[HuntCandidate, str]) -> tuple[float, float, int, int]:
        candidate = item[0]
        return (
            float(candidate.estimated_level_range[1]),
            candidate.score,
            -len(candidate.route),
            candidate.source_value,
        )

    def reward_per_travel(candidate: HuntCandidate) -> float:
        """Estimate source reward per outbound step with a soft risk cost."""
        reference_hp = max(1, int(character_max_hp or 1))
        peak_risk = min(
            2.0,
            max(0, candidate.estimated_peak_round_damage) / reference_hp,
        )
        return max(0.0, float(candidate.score)) / max(
            1, len(candidate.route)
        ) / (1.0 + 0.5 * peak_risk)

    def best_by_reward(
        choices: Collection[tuple[HuntCandidate, str]],
    ) -> tuple[HuntCandidate, str]:
        return max(
            choices,
            key=lambda item: (reward_per_travel(item[0]), *rank(item)),
        )

    pools = (
        valid,
        capacity_research,
        level_ceiling_probes,
        bounded_peak_probes,
        protected_peak_probes,
        dynamic_wanderer_probes,
        audited_specials,
        sanctuary_recovery,
    )
    revalidation_policy_id = str(
        state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or ""
    )
    if revalidation_policy_id:
        # A policy repair may need one direct live revalidation even when a
        # more productive route is currently ranked higher. Keep this marker
        # narrow and one-shot; all normal source, crowd, consider, and health
        # gates have already run while building the pools above.
        for pool in pools:
            for candidate, status in pool:
                if (
                    status == "fresh"
                    and candidate_policy_id(candidate) == revalidation_policy_id
                ):
                    return candidate
    # Exhaust the fully source-safe current-band progress pool before opening
    # fresh special-procedure research. A fresh research record is useful, but
    # it must not displace a verified route that can actually earn XP.
    safe_progress_pools = (valid,)
    for preferred_status in ("productive", "fresh", "retryable"):
        for pool in safe_progress_pools:
            choices = [
                item
                for item in pool
                if item[1] == preferred_status
                and candidate_policy_id(item[0]) not in blocked_policy_ids
            ]
            if choices:
                if preferred_status == "productive" and not allow_repeated_policy_ids:
                    fresh_choices = [
                        item
                        for item in pool
                        if item[1] == "fresh"
                        and candidate_policy_id(item[0]) not in blocked_policy_ids
                    ]
                    if fresh_choices:
                        best_productive = best_by_reward(choices)
                        best_fresh = best_by_reward(fresh_choices)
                        if reward_per_travel(best_fresh[0]) >= (
                            reward_per_travel(best_productive[0])
                            * _SOURCE_RANKED_FRESH_REWARD_ADVANTAGE
                        ):
                            return best_fresh[0]
                return best_by_reward(choices)[0]
    research_pools = (
        capacity_research,
        level_ceiling_probes,
        bounded_peak_probes,
        protected_peak_probes,
        dynamic_wanderer_probes,
        audited_specials,
        sanctuary_recovery,
    )
    useful_fresh_research_available = any(
        status == "fresh"
        and candidate_policy_id(candidate) not in blocked_policy_ids
        and _source_ranked_useful_fuzz_probability(
            candidate,
            character_level=character_level,
        )
        >= _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
        for pool in research_pools
        for candidate, status in pool
    )
    for preferred_status in ("fresh", "retryable", "productive"):
        for pool in research_pools:
            choices = [
                item
                for item in pool
                if item[1] == preferred_status
                and candidate_policy_id(item[0]) not in blocked_policy_ids
                and (
                    preferred_status != "fresh"
                    or not useful_fresh_research_available
                    or _source_ranked_useful_fuzz_probability(
                        item[0],
                        character_level=character_level,
                    )
                    >= _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
                )
            ]
            if choices:
                return max(choices, key=rank)[0]
    # The no-progress guard is a rotation aid, not a terminal frontier. If
    # every ordinary safe route is unavailable, reopen one fresh candidate
    # from the already-audited research pools when it was blocked only by
    # trailing history. A current crowd, absence, hazard, protection, or
    # explicit last-policy block still has priority and cannot be bypassed by
    # this fallback.
    no_progress_policy_ids = {
        str(policy_id) for policy_id in additional_blocked_policy_ids
    }
    hard_blocked_policy_ids = {
        last_policy_id,
        retry_exhausted_policy_id,
        throughput_limited_policy_id,
    }
    if allow_no_progress_fallback:
        relaxed_choices = [
            item
            for pool in (valid, *research_pools)
            for item in pool
            if item[1] == "fresh"
            and candidate_policy_id(item[0]) in no_progress_policy_ids
            and candidate_policy_id(item[0]) not in hard_blocked_policy_ids
        ]
        if relaxed_choices:
            return best_by_reward(relaxed_choices)[0]
    if allow_frontier_retry:
        frontier_choices = [
            item[0]
            for item in valid
            if _source_ranked_frontier_retry_candidate(
                item[0],
                state,
                character_level=character_level,
            )
        ]
        if frontier_choices:
            return max(
                frontier_choices,
                key=lambda candidate: (
                    float(candidate.estimated_level_range[1]),
                    candidate.score,
                    -len(candidate.route),
                    candidate.source_value,
                ),
            )
    # A productive route normally yields to another policy so the campaign
    # can rotate through the frontier. If every other current-band choice is
    # blocked, keep one still-available same-reboot kill from stalling the
    # campaign. The normal cap, research status, and all safety gates above
    # still apply; this only relaxes the last-policy handoff.
    fallback_choices = [
        item[0]
        for pool in pools
        for item in pool
        if candidate_policy_id(item[0]) == last_policy_id
        and item[1] == "productive"
        and (
            item[0].boot_kills < 3
            or candidate_policy_id(item[0])
            in set(allow_repeated_policy_ids)
        )
    ]
    if fallback_choices:
        return max(
            fallback_choices,
            key=lambda candidate: (
                float(candidate.estimated_level_range[1]),
                candidate.score,
                -len(candidate.route),
                candidate.source_value,
            ),
        )
    return None


def _source_ranked_repeatable_policy_ids(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    policy_xp_deltas: Mapping[str, int],
    source_mobile_xp_deltas: Mapping[int, int] | None = None,
    source_mobile_best_xp_deltas: Mapping[int, int] | None = None,
) -> frozenset[str]:
    """Return same-reboot productive routes safe to reuse after kill caps."""
    research_results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    productive_policy_ids = _state_productive_policy_ids(state)
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    repeatable: set[str] = set()
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if candidate.boot_kills < 3:
            if _source_ranked_dynamic_wanderer_repeatability_allowed(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
            ):
                repeatable.add(policy_id)
            continue
        latest_xp_delta = int(policy_xp_deltas.get(policy_id, 0) or 0)
        if latest_xp_delta < 0:
            # Productive history must not resurrect a route whose latest
            # bounded attempt lost XP, typically through death.
            continue
        latest_source_xp = int(
            (source_mobile_xp_deltas or {}).get(candidate.mobile_vnum, 0)
            or 0
        )
        best_source_xp = int(
            (source_mobile_best_xp_deltas or {}).get(candidate.mobile_vnum, 0)
            or 0
        )
        has_meaningful_latest_result = (
            max(latest_xp_delta, latest_source_xp)
            >= _MEANINGFUL_FIELD_SEGMENT_XP
        )
        has_meaningful_historical_result = (
            best_source_xp >= _MEANINGFUL_FIELD_SEGMENT_XP
        )
        if not (
            has_meaningful_latest_result
            or has_meaningful_historical_result
            or policy_id in productive_policy_ids
        ):
            continue
        result = research_results.get(policy_id)
        if isinstance(result, Mapping):
            if result.get("low_reward") is True:
                # Older positive source evidence must not resurrect a route
                # whose current level/reboot result has already fallen to the
                # no-progress floor.
                continue
            try:
                current_max_xp = int(
                    result.get("max_objective_kill_xp") or 0
                )
            except (TypeError, ValueError):
                current_max_xp = 0
            if (
                result.get("completed_kill") is True
                and "max_objective_kill_xp" in result
                and current_max_xp < _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
            ):
                continue
        if result is None and (
            policy_id in productive_policy_ids
            or latest_source_xp >= _MEANINGFUL_FIELD_SEGMENT_XP
            or best_source_xp >= _MEANINGFUL_FIELD_SEGMENT_XP
        ):
            # A later absence scan may leave no source-ranked result after
            # metadata repair. Same-reboot productive history still proves
            # that this exact reset once produced a confirmed kill; let the
            # normal live presence, crowd, consider, and health gates decide
            # whether it is useful again.
            repeatable.add(policy_id)
            continue
        if (
            (
                policy_id in productive_policy_ids
                or latest_source_xp >= _MEANINGFUL_FIELD_SEGMENT_XP
            )
            and isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("absent") is True
        ):
            # Absence is temporary area-state evidence, not a replacement for
            # an earlier same-reboot productive kill. Keep the route eligible
            # for reuse once its ordinary absence cooldown expires.
            repeatable.add(policy_id)
            continue
        if not (
            isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("viable") is True
            and result.get("completed_kill") is True
            and not result.get("crowded")
        ):
            continue
        repeatable.add(policy_id)
    return frozenset(repeatable)


def _source_ranked_useful_fuzz_probability(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> float:
    """Return the source-fuzz share inside the ordinary live hunt band."""
    minimum_level, maximum_level = candidate.estimated_level_range
    if minimum_level <= 0 or maximum_level < minimum_level:
        minimum_level = candidate.level - 2
        maximum_level = candidate.level + 2
    useful_minimum = character_level - 4
    useful_maximum = character_level + 1
    useful_count = max(
        0,
        min(maximum_level, useful_maximum)
        - max(minimum_level, useful_minimum)
        + 1,
    )
    return useful_count / max(1, maximum_level - minimum_level + 1)


def _source_ranked_candidate_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None = None,
    allow_repeated_kills: bool = False,
) -> bool:
    if candidate.status == "reject":
        return False
    if candidate.boot_kills >= 3 and not allow_repeated_kills:
        return False
    if character_max_hp is None:
        character_max_hp = (
            int(state["max_hp"])
            if isinstance(state.get("max_hp"), (int, float))
            else None
        )
    nominal_level_fuzz_probe = _source_ranked_nominal_level_fuzz_probe_allowed(
        candidate,
        character_level=character_level,
        character_max_hp=character_max_hp,
    )
    if not nominal_level_fuzz_probe:
        # A source special can be safe even when the ordinary nominal-level
        # fuzz gate rejects all specials.  Reuse the same source.c-backed
        # damage, affect, and resource bounds used by the audited fallback so
        # a safe noncombat/economic special is not lost at a level boundary.
        nominal_level_fuzz_probe = _audited_source_special_candidate_allowed(
            candidate,
            state=state,
            character_max_hp=character_max_hp,
        )
    target_is_aggressive = (
        "target is aggressive" in candidate.autonomy_rejections
        or "target is aggressive" in candidate.hazards
    )
    if (
        target_is_aggressive
        and candidate.estimated_level_range[0] < character_level - 5
    ):
        # An aggressive target can enter combat as soon as the endpoint room
        # loads, before the live consider response can reject a below-band
        # fuzz roll. Do not spend an XP-losing flee on a prototype whose
        # minimum source fuzz is already below the useful floor.
        return False
    return not (
        candidate.estimated_level_range[1] <= character_level - 5
        or (
            candidate.estimated_level_range[1] > character_level + 1
            and not nominal_level_fuzz_probe
        )
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_candidate_needs_flight_refresh(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
) -> bool:
    """Require enough affect time to complete a source-backed aerial route."""
    if not candidate.requires_flight:
        return False
    if candidate.estimated_flying_move_cost <= 0:
        return False
    if state.get("affects") is None:
        # An unknown affect snapshot is deliberately kept compatible with the
        # existing optimistic route behavior; the live fastwalk gate remains
        # the final authority.
        return False
    route_steps = max(1, len(candidate.route))
    # DD4 decrements affects once per 30-second PULSE_TICK. The source
    # ``get_move_ws`` returns one pulse for ordinary flying movement and
    # ``PULSE_PER_SECOND`` is four, so count a quarter-second per route step
    # and keep one extra tick as a latency/combat reserve. Open-door commands
    # are included in ``route_steps`` conservatively.
    required_duration = max(
        2,
        math.ceil(route_steps * 0.25 / 30.0) + 1,
    )
    if candidate.area_file.casefold() == "abyss.are":
        # Every Abyss room is an air sector and its randomized search can use
        # most of a bounded segment. A level-30 potion grants 33 ticks; retain
        # enough time for the search plus the source-proven four-step return.
        required_duration = max(required_duration, 16)
    duration = _state_flight_duration(state.get("affects"))
    return duration is None or duration < required_duration


def _source_ranked_candidate_benefits_from_flight(
    candidate: HuntCandidate,
) -> bool:
    """Return whether optional flight materially shortens a safe ground route."""
    ground_cost = candidate.estimated_move_cost
    flying_cost = candidate.estimated_flying_move_cost
    return bool(
        not candidate.requires_flight
        and ground_cost >= _OPTIONAL_FLIGHT_MINIMUM_GROUND_COST
        and flying_cost > 0
        and ground_cost - flying_cost >= _OPTIONAL_FLIGHT_MINIMUM_SAVINGS
    )


def _source_ranked_level_ceiling_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow one source level above the band only under a full HP bound."""
    if character_max_hp is None or character_max_hp <= 0:
        return False
    if candidate.is_coin_stash or not candidate.autonomous_safe:
        return False
    if candidate.level != character_level + 1:
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    if candidate.estimated_level_range[1] <= character_level + 1:
        return False
    return (
        candidate.estimated_peak_round_damage > 0
        and candidate.estimated_peak_round_damage < character_max_hp
    )


def _source_ranked_nominal_level_fuzz_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow a safe nominal-current-level target through one fuzz step."""
    if character_max_hp is None or character_max_hp <= 0:
        return False
    if candidate.is_coin_stash or not candidate.autonomous_safe:
        return False
    if candidate.level != character_level:
        return False
    if not (
        character_level + 1
        < candidate.estimated_level_range[1]
        <= character_level + 2
    ):
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    if candidate.autonomy_rejections or candidate.specials:
        return False
    return (
        candidate.estimated_peak_round_damage > 0
        and candidate.estimated_peak_round_damage < character_max_hp
    )


def _source_ranked_level_ceiling_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply reboot, movement, and useful-XP gates to a ceiling probe."""
    if not _source_ranked_level_ceiling_probe_allowed(
        candidate,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


_SOURCE_CAPACITY_RESEARCH_RE = re.compile(
    r"target reset permits up to \d+ matching mobiles in the room"
    )


def _source_ranked_candidate_requires_sanctuary(
    candidate: HuntCandidate,
) -> bool:
    """Return whether the audited special needs a protection reserve first."""
    return bool(
        set(candidate.specials)
        & (_SOURCE_SANCTUARY_SPECIALS | _SOURCE_BREATH_SPECIALS)
    )


def _source_ranked_candidate_requires_sanctuary_for_state(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Bind a carried sanctuary reserve only to the hunt that needs it."""
    if _source_ranked_candidate_requires_sanctuary(candidate):
        return True
    if _SOURCE_PEAK_DAMAGE_REJECTION in candidate.autonomy_rejections:
        # A protected peak probe is selected only with a carried or active
        # reserve; make the field executor consume/maintain that protection.
        return True
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    loss_record = _source_ranked_xp_loss_record(state, candidate_policy_id)
    if (
        loss_record is not None
        and _source_ranked_xp_loss_count(loss_record) < 2
        and _state_has_sanctuary_reserve(state)
    ):
        # A protected retry must actually spend the reserve before combat;
        # merely allowing the route back into the selector is insufficient.
        return True
    marker = state.get(_PROTECTION_RECOVERY_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
    ):
        return False
    return marker.get("policy_id") == candidate_policy_id


def _source_ranked_sanctuary_reserve_cooldown_active(
    state: Mapping[str, Any],
) -> bool:
    """Keep an unsuccessful reserve route out of the selector temporarily."""
    return _research_retry_cooldown_active(
        state,
        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
    )


def _source_ranked_candidate_has_absence_cooldown(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Keep a plainly absent source reset out of failure rotation."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    results = _campaign_research_results(state)
    result = results.get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if result.get("absent") is not True:
        return False
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    try:
        return int(cooldowns.get(policy_id) or 0) > 0
    except (AttributeError, TypeError, ValueError):
        return False


def _source_ranked_capacity_research_candidate(candidate: HuntCandidate) -> bool:
    """Allow live isolation research for an otherwise clean crowded reset."""
    capacity_only = (
        candidate.autonomy_rejections == ("target reset capacity exceeds one",)
        and candidate.source_spawn_limit == 2
        and candidate.room_spawn_count == 1
    )
    return bool(
        candidate.status == "reject"
        and not candidate.specials
        and candidate.autonomy_rejections
        and (
            capacity_only
            or all(
                _SOURCE_CAPACITY_RESEARCH_RE.fullmatch(reason)
                for reason in candidate.autonomy_rejections
            )
        )
    )


def _source_ranked_capacity_research_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply ordinary level, movement, and reboot gates to a research reset."""
    if not _source_ranked_capacity_research_candidate(candidate):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or candidate.estimated_level_range[1] <= character_level - 5
        or candidate.estimated_level_range[1] > character_level + 1
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


_SOURCE_PEAK_DAMAGE_REJECTION = "source peak round can exceed character HP"
_SOURCE_BOUNDED_PEAK_SPECIALS = frozenset({"spec_thief"})
_SOURCE_DYNAMIC_WANDERER_REJECTION = (
    "an aggressive wanderer inside the useful XP band can reach the route"
)
_SOURCE_DYNAMIC_WANDERER_HAZARD_PREFIXES = (
    "room companion:",
    "source-backed trivial companion:",
    "source-backed noncombat route special:",
    "reachable wanderer:",
)


def _source_ranked_bounded_peak_probe_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
) -> bool:
    """Allow an explicit live level probe below a conservative peak bound."""
    if not allow_cooldown_retry or character_max_hp is None:
        return False
    if character_max_hp <= 0 or candidate.is_coin_stash:
        return False
    rejections = set(candidate.autonomy_rejections)
    if _SOURCE_PEAK_DAMAGE_REJECTION not in rejections:
        return False
    remaining_rejections = rejections - {_SOURCE_PEAK_DAMAGE_REJECTION}
    specials = frozenset(candidate.specials)
    if remaining_rejections:
        if remaining_rejections != {
            "target has special procedure spec_thief"
        } or specials != _SOURCE_BOUNDED_PEAK_SPECIALS:
            return False
        carried_coins = _state_copper_value(dict(state))
        if carried_coins * 20 // 100 > _SPEC_THIEF_MAX_EXPOSURE_COINS:
            return False
    elif specials:
        return False

    minimum_peak = candidate.estimated_min_peak_round_damage
    if minimum_peak <= 0:
        minimum_level = max(1, candidate.estimated_level_range[0])
        weapon_count = len(candidate.equipped_weapons)
        minimum_peak = _mobile_peak_round_damage(
            minimum_level,
            wielding=weapon_count > 0,
            dual_wielding=weapon_count > 1,
        )
    return minimum_peak < character_max_hp


def _source_ranked_bounded_peak_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply ordinary level, movement, and reboot gates to a peak probe."""
    if not _source_ranked_bounded_peak_probe_allowed(
        candidate,
        state=state,
        character_max_hp=character_max_hp,
        allow_cooldown_retry=allow_cooldown_retry,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or candidate.estimated_level_range[1] <= character_level - 5
        or candidate.estimated_level_range[1] > character_level + 1
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_dynamic_wanderer_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
) -> bool:
    """Allow one bounded probe when only a reachable useful-band wanderer blocks it."""
    if not allow_cooldown_retry or character_max_hp is None:
        return False
    if (
        character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.status == "reject"
        or candidate.specials
        or set(candidate.autonomy_rejections)
        != {_SOURCE_DYNAMIC_WANDERER_REJECTION}
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if minimum_level <= character_level - 5 or maximum_level > character_level + 1:
        return False
    if (
        candidate.estimated_peak_round_damage <= 0
        or candidate.estimated_peak_round_damage >= character_max_hp
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
    ):
        return False
    return all(
        hazard.startswith(_SOURCE_DYNAMIC_WANDERER_HAZARD_PREFIXES)
        for hazard in candidate.hazards
    )


def _source_ranked_dynamic_wanderer_repeatability_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow one post-kill repeatability probe for a dynamic-wanderer route."""
    if not _source_ranked_dynamic_wanderer_probe_allowed(
        candidate,
        character_level=character_level,
        character_max_hp=character_max_hp,
        allow_cooldown_retry=True,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("viable") is True
        and result.get("completed_kill") is True
        and not result.get("crowded")
        and not result.get("low_reward")
    ):
        return False
    marker = state.get(_SOURCE_DYNAMIC_WANDERER_REPEATABILITY_KEY)
    return not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("policy_id") == policy_id
    )


def _record_source_ranked_dynamic_wanderer_repeatability(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> None:
    """Persist the one repeatability attempt before its live segment starts."""
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    if not _source_ranked_dynamic_wanderer_repeatability_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        return
    state[_SOURCE_DYNAMIC_WANDERER_REPEATABILITY_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
    }


def _source_ranked_protected_peak_probe_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow a source peak probe only behind a carried sanctuary reserve."""
    if character_max_hp is None or character_max_hp <= 0:
        return False
    if not _state_has_sanctuary_reserve(state):
        return False
    if candidate.is_coin_stash or candidate.specials:
        return False
    if set(candidate.autonomy_rejections) != {
        _SOURCE_PEAK_DAMAGE_REJECTION
    }:
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    # Match the existing one-fuzz-step ceiling policy, but apply the source
    # peak after sanctuary's verified half-damage reduction.
    if candidate.estimated_level_range[1] > character_level + 2:
        return False
    protected_peak = (candidate.estimated_peak_round_damage + 1) // 2
    return (
        candidate.estimated_peak_round_damage > 0
        and protected_peak < character_max_hp
    )


def _source_ranked_protected_peak_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply reboot, movement, and useful-XP gates to a protected probe."""
    if not _source_ranked_protected_peak_probe_allowed(
        candidate,
        state=state,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_candidate_has_only_safe_noncombat_special_rejections(
    candidate: HuntCandidate,
) -> bool:
    """Recognize source-safe specials in legacy serialized candidates."""
    specials = set(candidate.specials)
    if not specials or not specials <= SAFE_NONCOMBAT_SPECIALS:
        return False
    return set(candidate.autonomy_rejections) <= {
        f"target has special procedure {special}" for special in specials
    }


def _audited_source_special_candidate_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_max_hp: int | None,
) -> bool:
    """Allow a source-audited, bounded special procedure as fallback."""
    specials = set(candidate.specials)
    rejections = set(candidate.autonomy_rejections)
    if not specials or not specials <= _AUDITED_SOURCE_SPECIALS:
        return False
    if (
        specials & _SOURCE_SANCTUARY_SPECIALS
        and not _has_named_affect(state.get("affects"), "sanctuary")
        and not _state_has_blindness_recovery_reserve(state)
    ):
        # Both audited caster specials can blind before the first protected
        # round.  If sanctuary will be consumed as the opener, the selector
        # must also see a trained cure or a second source-verified potion.
        return False
    if (
        specials & _SOURCE_BREATH_SPECIALS
        and not _state_has_sanctuary_reserve(state)
    ):
        # Breath variants are direct damage pulses.  Sanctuary halves that
        # damage, while gas breath's poison-backed nausea remains covered by
        # the field runner's immediate healer-return path.
        return False
    if specials == {"spec_cast_mage"} and not _state_has_sanctuary_reserve(
        state
    ):
        # The source damage bound covers one pulse, not repeated spell casts.
        # Require an active or carried sanctuary reserve before exposing a
        # character to a source mage special.
        return False
    maximum_level = candidate.estimated_level_range[1]
    if specials == {"spec_cast_mage"} and rejections == {
        "target has special procedure spec_cast_mage"
    }:
        # special.c can choose fireball at levels below 25; magic.c bounds its
        # direct damage at 6d6, while level 25 also opens energy drain. Keep
        # that later spell set research-gated until the runner has a dedicated
        # policy.
        if maximum_level >= 25:
            return False
        worst_special_damage = maximum_level * 6
    elif specials == {"spec_cast_cleric"} and rejections == {
        "target has special procedure spec_cast_cleric"
    }:
        if not _state_has_sanctuary_reserve(state):
            # A cleric special can cast harm, flamestrike, earthquake, or
            # dispel magic depending on the loaded mobile level.  Sanctuary
            # is required because dispel magic can remove it during combat;
            # the field runner turns that loss into an immediate withdrawal.
            return False
        # special.c's highest direct-damage choice is harm (100) or
        # flamestrike (6 * level).  Dispel magic has no direct damage but is
        # handled as a sanctuary-loss withdrawal boundary by the runner.
        worst_special_damage = max(100, maximum_level * 6)
    elif specials == {"spec_breath_any"} and rejections == {
        "target has special procedure spec_breath_any"
    }:
        # magic.c uses UMAX(10, ch->hit) / 4 as the maximum direct damage for
        # every breath variant. This deliberately ignores saves and resistances
        # and therefore bounds the unmitigated one-round special hit.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_breath_gas"} and rejections == {
        "target has special procedure spec_breath_gas"
    }:
        # special.c fires gas breath only while fighting. magic.c uses the
        # same UMAX(10, ch->hit) / 4 damage ceiling and may add nausea, which
        # the field runner treats as a poison-affect withdrawal boundary.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_breath_lightning"} and rejections == {
        "target has special procedure spec_breath_lightning"
    }:
        # special.c delegates this variant to dragon(), and magic.c applies
        # only the direct hp/8+1..hp/4 lightning pulse plus save/resistance
        # mitigation. It does not damage carried objects or add an affect.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_cast_undead"} and rejections == {
        "target has special procedure spec_cast_undead"
    }:
        # special.c only runs this procedure after the player is fighting. Its
        # spell table is level-gated: energy drain begins at 15, harm at 18,
        # and gate at 20. Keep those branches research-only until their field
        # effects have dedicated recovery policies. At lower levels, chill
        # touch is the largest direct pulse (level + 20); blindness adds at
        # most level/2 + 10 and poison is handled as a withdrawal affect.
        if maximum_level >= 15:
            return False
        if (
            maximum_level >= 9
            and not _state_has_blindness_recovery_reserve(
                state,
                required_purple_count=1,
            )
        ):
            return False
        chill_damage = maximum_level + 20 if maximum_level >= 6 else 0
        blindness_damage = (
            maximum_level // 2 + 10 if maximum_level >= 9 else 0
        )
        worst_special_damage = max(chill_damage, blindness_damage)
    elif specials == {"spec_guard"} and rejections == {
        "target has special procedure spec_guard"
    }:
        # special.c only makes a guard attack a normal player when the player
        # is already fighting. In combat it chooses headbutt, smash, or kick;
        # fight.c bounds the NPC headbutt at level/2 + 3*level, while smash
        # replaces a normal hit and kick is bounded below that value. Charge
        # only the headbutt's excess over one normal hit, since the special
        # pulse replaces that round's ordinary attack.
        headbutt_damage = maximum_level // 2 + maximum_level * 3
        normal_attack_count = 6 if maximum_level >= 20 else 5
        normal_hit_bound = candidate.estimated_peak_round_damage // normal_attack_count
        worst_special_damage = max(0, headbutt_damage - normal_hit_bound)
    elif len(specials) == 1 and next(iter(specials)) not in ECONOMIC_SPECIALS:
        special = next(iter(specials))
        expected_rejection = {f"target has special procedure {special}"}
        # Source parsing intentionally omits an autonomy rejection for a
        # proven noncombat special. Accept both the modern empty form and the
        # legacy serialized form that retained a synthetic rejection.
        if rejections not in (set(), expected_rejection):
            return False
        profile = source_special_profile(special)
        if special in SAFE_NONCOMBAT_SPECIALS:
            # db.c assigns these procedures no XP bonus and special.c does
            # not issue a combat action against an ordinary player.
            if profile.xp_bonus != 0:
                return False
            worst_special_damage = 0
        elif special in WEAK_DEBILITATING_SPECIALS:
            # Poison is a withdrawal-triggering affect, not direct damage.
            # StarterBotRunner already recalls and waits for healer recovery
            # while the affect remains active.
            if profile.xp_bonus != 5:
                return False
            worst_special_damage = 0
        elif special in WEAK_EXTRA_ATTACK_SPECIALS:
            # These weak procedures issue one additional ordinary attack at
            # most. Bound that hit separately from the source round peak.
            if profile.xp_bonus != 5:
                return False
            normal_attack_count = 6 if maximum_level >= 20 else 5
            worst_special_damage = max(
                1,
                candidate.estimated_peak_round_damage
                // normal_attack_count,
            )
        elif special in WEAK_DIRECT_DAMAGE_SPECIALS:
            # special.c calls high explosive; magic.c bounds its damage at
            # six dice per caster level before saves.
            if profile.xp_bonus != 5:
                return False
            worst_special_damage = maximum_level * 6
        else:
            return False
    elif specials == {"spec_thief"} and rejections == {
        "target has special procedure spec_thief"
    }:
        # special.c returns before its theft branch unless the mobile is
        # standing, and the standing branch is skipped once it is fighting.
        # Its maximum theft is 20 percent of the player's carried coins;
        # keep that bounded resource loss explicit before entering the room.
        carried_coins = _state_copper_value(dict(state))
        if (
            carried_coins * 20 // 100
            > _SPEC_THIEF_MAX_EXPOSURE_COINS
        ):
            return False
        if source_special_profile("spec_thief").xp_bonus != 0:
            return False
        worst_special_damage = 0
    else:
        return False
    if character_max_hp is None:
        return False
    if specials & (_SOURCE_SANCTUARY_SPECIALS | _SOURCE_BREATH_SPECIALS):
        # Sanctuary halves both ordinary combat damage and the audited special
        # pulse.  The field runner withdraws if dispel, expiry, or a poison
        # backed breath effect removes the safe combat boundary, so use the
        # protected opening-round bound for caster and breath specials.
        protected_peak = (
            candidate.estimated_peak_round_damage + worst_special_damage + 1
        ) // 2
        if (
            max(candidate.estimated_peak_round_damage, protected_peak)
            > character_max_hp
        ):
            return False
    elif (
        candidate.estimated_peak_round_damage + worst_special_damage
        > character_max_hp
    ):
        return False
    return True


def _interrupted_run_target_evidence(
    storage: RunStorage,
    run_id: int,
    candidate: HuntCandidate | Mapping[str, Any] | None,
) -> tuple[bool, bool | None]:
    """Recover target presence and consider evidence from a stopped run."""
    if candidate is None:
        return False, None
    def candidate_value(key: str, default: Any = None) -> Any:
        if isinstance(candidate, Mapping):
            return candidate.get(key, default)
        return getattr(candidate, key, default)

    expected_vnum = str(candidate_value("mobile_vnum") or "")
    target_identity = str(
        candidate_value("target_identity")
        or candidate_value("target_keyword")
        or candidate_value("target")
        or ""
    ).casefold()
    target_seen = False
    consider_viable: bool | None = None
    for event in storage.list_events(run_id):
        try:
            payload = json.loads(event["payload_json"])
        except (TypeError, json.JSONDecodeError):
            continue
        if event["kind"] == "game_event" and payload.get("type") == "enemies_changed":
            data = payload.get("data")
            values = data.get("value") if isinstance(data, Mapping) else None
            if isinstance(values, list):
                target_seen = target_seen or any(
                    isinstance(enemy, Mapping)
                    and (
                        not expected_vnum
                        or str(enemy.get("isnpc") or "") == expected_vnum
                    )
                    and (
                        not target_identity
                        or target_identity in str(enemy.get("name") or "").casefold()
                    )
                    for enemy in values
                )
        elif event["kind"] == "response":
            text = str(payload.get("text") or "").casefold()
            if target_identity and target_identity in text and "kill" in text:
                target_seen = True
            if "looks like an easy kill" in text:
                consider_viable = True
            elif consider_viable is None and (
                "looks like a difficult kill" in text
                or "would be a difficult kill" in text
                or "would be impossible" in text
            ):
                consider_viable = False
    return target_seen, consider_viable


def _reconcile_interrupted_segment(
    storage: RunStorage,
    campaign_id: int,
    segment: Any,
    *,
    character_name: str,
) -> bool:
    """Turn a stopped, evidence-bearing segment into a resumable checkpoint."""
    if segment["status"] != "failed":
        return False
    run = (
        storage.get_run(int(segment["run_id"]))
        if segment["run_id"] is not None
        else _run_for_failed_segment(
            storage,
            segment,
            character_name=character_name,
        )
    )
    if run is None or str(run["status"]) != "failed":
        return False
    start_state = json.loads(segment["start_state_json"] or "{}")
    current_state = _run_latest_state(storage, int(run["id"]))
    if current_state is None:
        return False
    phase = str(segment["phase"])
    objective_kills = _objective_kills_for_execution(
        storage,
        int(run["id"]),
        execution=phase,
    ) or []
    end_state = _campaign_segment_end_state(
        start_state,
        current_state,
        execution=(
            "source-ranked-hunt"
            if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            else phase
        ),
    )
    end_state["campaign_last_policy"] = phase
    end_state["campaign_policy_revision"] = _CAMPAIGN_POLICY_REVISION
    end_state["campaign_completed_kills"] = objective_kills
    end_state["campaign_objective_kills"] = objective_kills

    if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        candidate = _source_ranked_candidate_from_record(
            start_state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            source_revision=start_state.get(_SOURCE_REVISION_KEY),
        )
        target_seen, consider_viable = _interrupted_run_target_evidence(
            storage,
            int(run["id"]),
            candidate,
        )
        if objective_kills:
            target_seen = True
            consider_viable = True
        end_state["campaign_fastwalk_target_present_observed"] = target_seen
        end_state["campaign_fastwalk_target_absent"] = not target_seen
        end_state["campaign_fastwalk_consider_outcomes"] = (
            {
                str(
                    (
                        candidate.get("target_identity")
                        if isinstance(candidate, Mapping)
                        else candidate.target_identity
                    )
                    or "target"
                ): consider_viable
            }
            if candidate is not None and consider_viable is not None
            else {}
        )
        end_state["campaign_fastwalk_abort_reason"] = (
            None
            if target_seen
            else "field route interrupted before target evaluation"
        )
        policy = replace(
            _SOURCE_RANKED_HUNT_POLICY,
            policy_id=phase,
            minimum_level=_level(start_state),
            maximum_level=_level(start_state),
        )
        end_state = _merge_campaign_research_result(
            start_state,
            end_state,
            policy=policy,
        )
        end_state = _merge_protection_recovery_metadata(
            end_state,
            policy=policy,
            xp_delta=_xp_delta(start_state, end_state),
            loss_event_id=int(segment["id"]),
        )
        interrupted_without_completion = str(segment["error"] or "").casefold() == (
            "previous campaign worker was interrupted before the next invocation"
        )
        if (
            _is_source_ranked_timeout_failure(segment["error"])
            or interrupted_without_completion
        ):
            end_state = _source_ranked_timeout_failure_state(
                end_state,
                policy_id=phase,
                error=str(segment["error"] or ""),
                objective_kill_count=len(objective_kills),
            )

    run_id = int(run["id"])
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=run_id,
        end_state=end_state,
        command_count=storage.count_events(run_id, kind="command"),
        duration_seconds=_run_duration(run),
        error=segment["error"],
    )
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=run_id,
        phase=phase,
        reason="segment_interrupted_recovered",
        state=end_state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=f"{phase} interruption recovered from run {run_id}; campaign resumed safely.",
    )
    return True


def _reconcile_orphaned_source_ranked_segment(
    storage: RunStorage,
    campaign_id: int,
    segment: Any,
) -> bool:
    """Rotate an unbound source route that stopped before a run was created."""
    phase = str(segment["phase"] or "")
    if not (
        segment["status"] == "failed"
        and phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
    ):
        return False
    checkpoint = storage.get_latest_campaign_checkpoint(campaign_id)
    state = _checkpoint_state(checkpoint)
    if not state:
        return False
    state["campaign_last_policy"] = phase
    state["campaign_completed_kills"] = []
    state["campaign_objective_kills"] = []
    state["campaign_policy_revision"] = _CAMPAIGN_POLICY_REVISION
    state = _source_ranked_timeout_failure_state(
        state,
        policy_id=phase,
        error=str(segment["error"] or "source route stopped before live work"),
    )
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=None,
        end_state=state,
        command_count=None,
        duration_seconds=None,
        error=segment["error"],
    )
    checkpoint_id = storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=None,
        phase=phase,
        reason="segment_route_timeout",
        state=state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"{phase} orphaned route rotated from failed segment "
            f"{segment['id']} (checkpoint {checkpoint_id})."
        ),
    )
    return True


def _source_ranked_timeout_policy_ids(
    state: Mapping[str, Any],
) -> set[str]:
    """Return exact current-reboot routes deferred after an outer timeout."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return set()
    return {
        str(record["policy_id"])
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and record.get("level") in {None, level}
        and isinstance(record.get("policy_id"), str)
    }


def _source_ranked_timeout_revalidation_attempts(
    record: Mapping[str, Any],
) -> int:
    """Read the bounded retry count, including legacy one-shot markers."""
    try:
        attempts = int(
            record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD)
            or (
                1
                if record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                else 0
            )
        )
    except (TypeError, ValueError):
        attempts = 1 if record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) else 0
    return min(
        _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
        max(0, attempts),
    )


def _source_ranked_timeout_revalidation_exhausted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return False
    return any(
        isinstance(raw_record, Mapping)
        and raw_record.get("boot_id") == boot_id
        and raw_record.get("policy_id") == policy_id
        and _source_ranked_timeout_revalidation_attempts(raw_record)
        >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
        for raw_record in raw_records
    )


def _source_ranked_timeout_revalidation_candidate(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None = None,
) -> HuntCandidate | None:
    """Find one safe route whose only current block is an old timeout.

    A bounded worker timeout can happen after a route spends its budget on
    navigation, before the target is ever evaluated. Reopen one such route
    once when the current source catalog still proves it is a special-free,
    current-band hunt. All live research evidence remains authoritative.
    """
    if state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY):
        return None
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return None
    eligible_policy_ids: set[str] = set()
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        if raw_record.get("boot_id") != boot_id:
            continue
        if raw_record.get("level") not in {None, character_level}:
            continue
        policy_id = raw_record.get("policy_id")
        if not isinstance(policy_id, str):
            continue
        if (
            _source_ranked_timeout_revalidation_attempts(raw_record)
            >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
        ):
            continue
        if raw_record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) is True:
            continue
        try:
            objective_kill_count = int(
                raw_record.get("objective_kill_count") or 0
            )
        except (TypeError, ValueError):
            objective_kill_count = 1
        if objective_kill_count > 0:
            continue
        reason = str(raw_record.get("reason") or "")
        if not (
            reason == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD
            or _is_source_ranked_timeout_failure(reason)
        ):
            continue
        eligible_policy_ids.add(policy_id)
    if not eligible_policy_ids:
        return None

    choices: list[HuntCandidate] = []
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if policy_id not in eligible_policy_ids:
            continue
        if not candidate.autonomous_safe or candidate.specials:
            continue
        if _source_ranked_candidate_excluded_by_below_band_evidence(
            candidate,
            state,
            character_level=character_level,
        ):
            continue
        if not _source_ranked_candidate_in_current_band(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
        ):
            continue
        if (
            _source_ranked_result_status(
                candidate,
                state,
                character_level=character_level,
            )
            != "fresh"
        ):
            continue
        # Temporarily remove only this timeout marker while checking the
        # remaining protection gates. Sanctuary, XP-loss, and route-hazard
        # requirements must still reject the candidate.
        probe_state = dict(state)
        probe_records = [
            dict(raw_record)
            for raw_record in raw_records
            if not (
                isinstance(raw_record, Mapping)
                and raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            )
        ]
        if probe_records:
            probe_state[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = probe_records
        else:
            probe_state.pop(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, None)
        if _source_ranked_candidate_blocked_by_protection_recovery(
            candidate,
            probe_state,
            character_level=character_level,
        ):
            continue
        choices.append(candidate)
    if not choices:
        return None
    return max(
        choices,
        key=lambda candidate: (
            float(candidate.estimated_level_range[1]),
            candidate.score,
            -len(candidate.route),
            candidate.source_value,
        ),
    )


def _mark_source_ranked_timeout_revalidation(
    state: dict[str, Any],
    *,
    policy_id: str,
) -> None:
    """Consume one bounded timeout revalidation before live work starts."""
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return
    records: list[dict[str, Any]] = []
    marked = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if (
            record.get("boot_id") == boot_id
            and record.get("policy_id") == policy_id
        ):
            attempts = _source_ranked_timeout_revalidation_attempts(record)
            record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
                _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
                max(0, attempts) + 1,
            )
            record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD] = True
            marked = True
        records.append(record)
    if marked:
        state[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]


def _rearm_source_ranked_timeout_revalidation_after_reset(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Allow one final timeout retry after an automatic reset wait.

    A reset wait is the only continuation that may consume reboot-local route
    evidence. Keep the retry bounded: a route that times out twice remains
    quarantined for this reboot.
    """
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return dict(state)
    records: list[dict[str, Any]] = []
    changed = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if (
            record.get("boot_id") == boot_id
            and record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) is True
        ):
            attempts = _source_ranked_timeout_revalidation_attempts(record)
            if attempts <= 0:
                attempts = 1
            if attempts < _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS:
                record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
                    _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
                    max(1, attempts),
                )
                record.pop(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD, None)
                changed = True
        records.append(record)
    if not changed:
        return dict(state)
    rearmed = dict(state)
    rearmed[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]
    rearmed.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
    return rearmed


def _repair_source_ranked_timeout_history(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Restore reboot-local route quarantine lost by an older selector."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    if boot_id is None or level <= 0:
        return dict(state)

    productive_policies = {
        str(segment["phase"])
        for segment in campaign_segments
        if str(segment["phase"] or "").startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and _segment_objective_kills(None, segment)
    }
    updated = dict(state)
    timeout_policy_ids = _source_ranked_timeout_policy_ids(updated)
    for segment in campaign_segments:
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if phase in productive_policies or phase in timeout_policy_ids:
            continue
        error = str(segment["error"] or "")
        interrupted_without_completion = error.casefold() == (
            "previous campaign worker was interrupted before the next invocation"
        )
        if not (_is_source_ranked_timeout_failure(error) or interrupted_without_completion):
            continue
        try:
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        if end_state.get("world_boot_id") != boot_id or _level(end_state) != level:
            continue
        objective_kills = _segment_objective_kills(None, segment)
        if objective_kills:
            continue
        updated = _remember_source_ranked_timeout(
            updated,
            policy_id=phase,
            level=level,
            boot_id=boot_id,
            reason=error,
        )
        timeout_policy_ids.add(phase)
    revalidation_policy_id = str(
        updated.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or ""
    )
    if revalidation_policy_id and _source_ranked_timeout_revalidation_exhausted(
        updated,
        revalidation_policy_id,
    ):
        updated.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
    return updated


def _source_ranked_candidate_blocked_by_timeout(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Defer one timed-out route until another source route gets a turn."""
    return (
        _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        in _source_ranked_timeout_policy_ids(state)
    )


def _remember_source_ranked_timeout(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    reason: str,
    objective_kill_count: int = 0,
) -> dict[str, Any]:
    """Persist a route timeout without treating productive work as unsafe."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) or boot_id is None:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    records: list[dict[str, Any]] = []
    revalidation_attempted = False
    revalidation_attempts = 0
    if isinstance(raw_records, (list, tuple)):
        for raw_record in raw_records:
            if not isinstance(raw_record, Mapping):
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
                and raw_record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                is True
            ):
                revalidation_attempted = True
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            ):
                revalidation_attempts = max(
                    revalidation_attempts,
                    _source_ranked_timeout_revalidation_attempts(raw_record),
                )
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") != policy_id
            ):
                records.append(dict(raw_record))
    record = {
            "boot_id": boot_id,
            "level": level,
            "policy_id": policy_id,
            "reason": reason,
            "objective_kill_count": max(0, int(objective_kill_count)),
        }
    if revalidation_attempted:
        record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD] = True
    if revalidation_attempts:
        record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
            _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
            revalidation_attempts,
        )
    records.append(record)
    updated = dict(state)
    updated[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]
    return updated


def _source_ranked_timeout_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
    objective_kill_count: int = 0,
) -> dict[str, Any]:
    """Record an outer-cap result and force one source-route rotation."""
    updated = _remember_source_ranked_timeout(
        state,
        policy_id=policy_id,
        level=_level(state),
        boot_id=state.get("world_boot_id"),
        reason=error,
        objective_kill_count=objective_kill_count,
    )
    updated["campaign_source_ranked_timeout_policy"] = policy_id
    updated["campaign_source_ranked_timeout_reason"] = error
    return updated


def _source_ranked_candidate_blocked_by_protection_recovery(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Defer the exact hunt that caused a current-reboot XP loss."""
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    timeout_revalidation_policy_id = str(
        state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or ""
    )
    if (
        candidate_policy_id in _source_ranked_timeout_policy_ids(state)
        and _source_ranked_timeout_revalidation_exhausted(
            state,
            candidate_policy_id,
        )
    ):
        return True
    if (
        candidate_policy_id in _source_ranked_timeout_policy_ids(state)
        and (
            candidate_policy_id != timeout_revalidation_policy_id
            or not candidate.autonomous_safe
            or bool(candidate.specials)
        )
    ):
        return True
    if (
        candidate_policy_id
        == str(state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or "")
        and candidate.autonomous_safe
        and not candidate.specials
    ):
        # A targeted repair marker is allowed one direct revalidation after a
        # single old loss.  Keep this exception source-safe and special-free;
        # durable timeout and second-loss quarantine still win above/below it.
        loss_record = _source_ranked_xp_loss_record(
            state,
            candidate_policy_id,
        )
        if loss_record is None or _source_ranked_xp_loss_count(loss_record) < 2:
            return False
    if candidate_policy_id in _source_ranked_xp_loss_policy_ids(state):
        # Permit one protected retry after the first current-reboot loss. A
        # second loss is durable route evidence, even if a later reserve is
        # available; otherwise the same bad route can consume a new potion on
        # every recovery cycle.
        loss_record = _source_ranked_xp_loss_record(
            state,
            candidate_policy_id,
        )
        if loss_record is not None and _source_ranked_xp_loss_count(
            loss_record
        ) >= 2:
            return True
        # Source-audited non-combat procedures such as fido and janitor do
        # not add an attack to the route. Keep them eligible for the same one
        # protected retry as an ordinary mobile when the candidate has no
        # other autonomy rejection. Combat-capable specials remain closed.
        safe_noncombat_special = bool(
            candidate.specials
            and candidate.autonomous_safe
            and set(candidate.specials) <= SAFE_NONCOMBAT_SPECIALS
        )
        if candidate.specials and not safe_noncombat_special:
            return True
        return not _state_has_sanctuary_reserve(state)
    if not _protection_recovery_required(state):
        return False
    record = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("level") not in {None, character_level}:
        return False
    policy_id = record.get("policy_id")
    if not isinstance(policy_id, str):
        return False
    return candidate_policy_id == policy_id


def _source_ranked_negative_incomplete_policy_ids(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    policy_xp_deltas: Mapping[str, int],
) -> frozenset[str]:
    """Defer current-reboot incomplete hunts whose latest result lost XP.

    A retryable research marker is normally useful for a route that reached a
    live target but ended without a kill. It must not, however, outrank a
    fresh target after the same policy has already produced a negative
    objective result. Explicit XP-loss records retain their separate
    sanctuary-protected retry contract.
    """
    boot_id = state.get("world_boot_id")
    research_results = _campaign_research_results(state)
    blocked: set[str] = set()
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        try:
            latest_xp_delta = int(policy_xp_deltas.get(policy_id) or 0)
        except (TypeError, ValueError):
            latest_xp_delta = 0
        if latest_xp_delta >= 0:
            continue
        result = research_results.get(policy_id)
        if not isinstance(result, Mapping) or result.get("boot_id") != boot_id:
            continue
        if result.get("completed_kill") is True:
            continue
        if _source_ranked_xp_loss_record(state, policy_id) is not None:
            # The protection-recovery gate owns the one protected retry for a
            # first explicit loss and the durable quarantine after the second.
            continue
        if not (
            result.get("retryable_failure") is True
            or result.get("viable") is False
            or result.get("completed_kill") is False
        ):
            continue
        blocked.add(policy_id)
    return frozenset(blocked)


def _source_ranked_xp_loss_records(
    state: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    """Return source-hunt XP-loss records for the current reboot."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return ()
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        return ()
    return tuple(
        record
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and isinstance(record.get("policy_id"), str)
    )


def _source_ranked_xp_loss_record(
    state: Mapping[str, Any],
    policy_id: str,
) -> Mapping[str, Any] | None:
    """Return one current-reboot loss record for an exact source policy."""
    return next(
        (
            record
            for record in _source_ranked_xp_loss_records(state)
            if record.get("policy_id") == policy_id
        ),
        None,
    )


def _source_ranked_xp_loss_count(record: Mapping[str, Any]) -> int:
    """Return the number of current-reboot losses represented by a record."""
    try:
        return max(1, int(record.get("loss_count") or 1))
    except (TypeError, ValueError):
        return 1


def _repair_source_ranked_xp_loss_attempt_counts(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill loss counts so legacy markers cannot reopen indefinitely."""
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return dict(state)

    observed = Counter()
    for segment in campaign_segments:
        try:
            phase = str(segment["phase"] or "")
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (KeyError, TypeError, json.JSONDecodeError):
            continue
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if not isinstance(start, dict) or not isinstance(end, dict):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        if _segment_objective_kills(None, segment):
            continue
        if _xp_delta(start, end) < 0:
            observed[phase] += 1

    updated_records: list[dict[str, Any]] = []
    changed = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if record.get("boot_id") == boot_id:
            policy_id = str(record.get("policy_id") or "")
            loss_count = max(
                _source_ranked_xp_loss_count(record),
                int(observed.get(policy_id, 0)),
            )
            if record.get("loss_count") != loss_count:
                record["loss_count"] = loss_count
                changed = True
        updated_records.append(record)
    if not changed:
        return dict(state)
    updated = dict(state)
    updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = updated_records
    return updated


def _source_ranked_xp_loss_policy_ids(
    state: Mapping[str, Any],
) -> set[str]:
    """Return exact source-hunt policies blocked by a current-reboot XP loss."""
    return {
        str(record["policy_id"])
        for record in _source_ranked_xp_loss_records(state)
    }


def _remember_source_ranked_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    xp_delta: int,
    observed_loss_count: int | None = None,
    loss_event_id: Any = None,
) -> dict[str, Any]:
    """Persist one exact source route that withdrew with a net XP loss.

    Live segment completion increments the count. Startup history repair passes
    the number observed in the bounded segment history so replay is idempotent.
    A segment identity makes repeated finalization of the same event idempotent
    as well.
    """
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) or boot_id is None:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    records: list[dict[str, Any]] = []
    previous_loss_count = 0
    duplicate_loss_event = False
    if isinstance(raw_records, (list, tuple)):
        for raw_record in raw_records:
            if not isinstance(raw_record, Mapping):
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            ):
                previous_loss_count = _source_ranked_xp_loss_count(raw_record)
                duplicate_loss_event = bool(
                    loss_event_id is not None
                    and raw_record.get("loss_event_id") == loss_event_id
                )
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") != policy_id
            ):
                records.append(dict(raw_record))
    if duplicate_loss_event:
        loss_count = previous_loss_count
    elif observed_loss_count is None:
        loss_count = max(1, previous_loss_count + 1)
    else:
        try:
            replayed_loss_count = max(1, int(observed_loss_count))
        except (TypeError, ValueError):
            replayed_loss_count = 1
        loss_count = max(1, previous_loss_count, replayed_loss_count)
    record = {
        "boot_id": boot_id,
        "level": level,
        "policy_id": policy_id,
        "xp_delta": xp_delta,
        "loss_count": loss_count,
        "reason": (
            "source-ranked hunt withdrew with an XP loss before an "
            "objective kill"
        ),
    }
    if loss_event_id is not None:
        record["loss_event_id"] = loss_event_id
    records.append(record)
    updated = dict(state)
    updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = records[-64:]
    return updated


def _clear_source_ranked_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_ids: Collection[str],
) -> dict[str, Any]:
    """Clear only source routes that have since produced their own kill."""
    target_policy_ids = {str(policy_id) for policy_id in policy_ids}
    if not target_policy_ids:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        return dict(state)
    retained = [
        dict(record)
        for record in raw_records
        if isinstance(record, Mapping)
        and str(record.get("policy_id") or "") not in target_policy_ids
    ]
    updated = dict(state)
    if retained:
        updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = retained
    else:
        updated.pop(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY, None)
    return updated


def _source_food_policy_id(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> str:
    """Return a reset-specific identity for one ground-food acquisition."""
    area = re.sub(
        r"[^a-z0-9]+",
        "-",
        Path(candidate.area_file).stem.casefold(),
    ).strip("-") or "area"
    object_identity = "-".join(
        str(vnum) for vnum in candidate.ground_loot_object_vnums
    ) or re.sub(
        r"[^a-z0-9]+",
        "-",
        candidate.target_keyword.casefold(),
    ).strip("-")
    return (
        f"{_SOURCE_RANKED_FOOD_POLICY_PREFIX}{area}-"
        f"{candidate.room_vnum}-{object_identity}-{character_level}"
    )


def _urgent_food_fullness_requirement(state: Mapping[str, Any]) -> int:
    """Return the minimum verified food value for an active starvation state."""
    hunger = state.get("hunger")
    if isinstance(hunger, bool) or not isinstance(hunger, (int, float)):
        return 0
    if hunger > 0:
        return 0
    return max(1, int(-hunger) + _URGENT_FOOD_FULLNESS_BUFFER)


def _urgent_food_survival_retry_allowed(state: Mapping[str, Any]) -> bool:
    """Allow a nourishing food retry when starvation has become dangerous."""
    hunger = state.get("hunger")
    hp = state.get("hp")
    max_hp = state.get("max_hp")
    return bool(
        isinstance(hunger, (int, float))
        and not isinstance(hunger, bool)
        and hunger <= 0
        and isinstance(hp, (int, float))
        and not isinstance(hp, bool)
        and isinstance(max_hp, (int, float))
        and not isinstance(max_hp, bool)
        and max_hp > 0
        and hp / max_hp <= _URGENT_FOOD_SURVIVAL_HEALTH_RATIO
    )


def _foodless_fame_hunt_allowed(state: Mapping[str, Any]) -> bool:
    """Allow productive hunting while fed when direct food is temporarily unavailable."""
    hunger = state.get("hunger")
    hp = state.get("hp")
    max_hp = state.get("max_hp")
    return bool(
        not state.get("dead")
        and not state.get("in_combat")
        and isinstance(hunger, (int, float))
        and not isinstance(hunger, bool)
        and hunger > 0
        and isinstance(hp, (int, float))
        and not isinstance(hp, bool)
        and isinstance(max_hp, (int, float))
        and not isinstance(max_hp, bool)
        and max_hp > 0
        and hp / max_hp >= _FOODLESS_FAME_HUNT_MIN_HEALTH_RATIO
    )


def _select_source_food_candidate(
    state: Mapping[str, Any],
    *,
    source_directory: Path,
    allow_pending_flight: bool = False,
    allow_cooldown_retry: bool = False,
) -> HuntCandidate | None:
    """Choose a safe direct food reset that does not require a shopkeeper."""
    character_level = _level(state)
    if character_level < 2 or not source_directory.is_dir():
        return None
    world = load_world_source(source_directory, include_all_areas=True)
    candidates = rank_food_stashes(
        world,
        character_level=character_level,
        include_all_areas=True,
    )
    minimum_fullness = _urgent_food_fullness_requirement(state)
    if minimum_fullness:
        nourishing = tuple(
            candidate
            for candidate in candidates
            if candidate.source_value >= minimum_fullness
        )
        candidates = (
            *nourishing,
            *(candidate for candidate in candidates if candidate not in nourishing),
        )
    active_flight = any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    survival_retry = _urgent_food_survival_retry_allowed(state)
    movement_state: Mapping[str, Any] = state
    if allow_pending_flight and not active_flight:
        # Evaluate a pending-flight food route with the movement cost it will
        # have after the purchase, while keeping the live route gate in charge
        # until the affect is actually observed.
        movement_state = {**state, "affects": [[{"name": "fly"}]]}
    for candidate in candidates:
        if (
            candidate.status == "reject"
            or not candidate.autonomous_safe
            or not candidate.loot
            or not candidate.ground_loot_object_vnums
            or not _source_candidate_fits_movement(candidate, movement_state)
        ):
            continue
        if candidate.requires_flight and not active_flight and not allow_pending_flight:
            continue
        if not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate,
            character_level=character_level,
        ):
            continue
        policy_id = _source_food_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            allow_cooldown_retry
            and state.get("campaign_last_policy") == policy_id
        ):
            # A bounded retry may reopen a cooled reset, but it must rotate
            # after the same food policy just ran without leaving a reserve.
            continue
        if (
            state.get("campaign_last_policy") == policy_id
            and str(state.get("campaign_fastwalk_abort_reason") or "")
            .startswith("field-route movement did not")
        ):
            continue
        if _research_fatal_failure_active(state, policy_id):
            continue
        if (
            _research_retry_cooldown_active(state, policy_id)
            and not (survival_retry or allow_cooldown_retry)
        ):
            continue
        return candidate
    return None


def _select_source_consumable_candidate(
    state: Mapping[str, Any],
    *,
    spell_name: str,
    short_description: str | None,
    source_directory: Path,
) -> tuple[HuntCandidate, tuple[int, ...]] | None:
    """Choose a bounded carrier by source effect rather than mobile identity."""
    character_level = _level(state)
    if character_level < 2 or not source_directory.is_dir():
        return None
    world = load_world_source(source_directory, include_all_areas=True)
    required_spell = spell_name.casefold()
    required_description = (
        normalize_item_name(short_description)
        if short_description
        else None
    )
    object_vnums = {
        item.vnum
        for item in world.objects.values()
        if item.item_type == ITEM_POTION
        and (
            required_description is None
            or normalize_item_name(item.short_description)
            == required_description
        )
        and required_spell in potion_spell_names(item)
        and not (
            set(potion_spell_names(item)) & _UNSAFE_SELF_POTION_SPELLS
        )
        and _source_consumable_command_keyword(
            world,
            item,
            required_spell=required_spell,
        )
        is not None
    }
    if not object_vnums:
        return None
    max_hp = state.get("max_hp")
    candidates = rank_hunt_candidates(
        world,
        character_level=character_level,
        include_below_band=True,
        character_max_hp=(
            int(max_hp)
            if isinstance(max_hp, (int, float)) and max_hp > 0
            else None
        ),
        include_all_areas=True,
        required_loot_object_vnums=object_vnums,
    )
    eligible: list[tuple[HuntCandidate, tuple[int, ...]]] = []
    for candidate in candidates:
        reset = next(
            (
                value
                for value in world.mob_resets
                if value.mobile_vnum == candidate.mobile_vnum
                and value.room_vnum == candidate.room_vnum
                and any(
                    object_vnum in object_vnums
                    for object_vnum in value.object_vnums
                )
            ),
            None,
        )
        if reset is None:
            continue
        matching_vnums = tuple(
            dict.fromkeys(
                object_vnum
                for object_vnum in reset.object_vnums
                if object_vnum in object_vnums
            )
        )
        remaining_rejections = set(candidate.autonomy_rejections).difference(
            {
                "target reset capacity exceeds one",
                # Required-loot acquisition has its own exact carrier,
                # isolation, health, and item-confirmation gates. A large
                # below-band crowd is still rejected for ordinary XP hunts,
                # but must not make every source-backed healing reserve
                # unreachable when the carrier itself is otherwise safe.
                "route crosses a large below-band aggressive crowd",
            }
        )
        if remaining_rejections:
            continue
        # A two-capacity reset is admissible only as an exact-one live probe.
        # Larger capacities are too likely to trigger same-prototype assists.
        if candidate.room_spawn_count > 2:
            continue
        if not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate,
            character_level=character_level,
        ):
            continue
        eligible.append((candidate, matching_vnums))
    if not eligible:
        return None
    return min(
        eligible,
        key=lambda value: (
            len(value[0].route),
            value[0].room_spawn_count,
            value[0].estimated_peak_round_damage,
            value[0].mobile_vnum,
            value[0].room_vnum,
        ),
    )


def _source_consumable_command_keyword(
    world: Any,
    item: Any,
    *,
    required_spell: str,
) -> str | None:
    """Choose a potion keyword whose source meaning remains unambiguous."""
    potion_peers = tuple(
        candidate
        for candidate in world.objects.values()
        if candidate.item_type == ITEM_POTION
    )
    keyword = _combat_potion_item_keyword(item, potion_peers)
    if not keyword:
        return None
    item_spells = set(potion_spell_names(item))
    if (
        required_spell not in item_spells
        or item_spells & _UNSAFE_SELF_POTION_SPELLS
    ):
        return None
    if keyword in {"black", "purple"}:
        # These legacy selectors retain exact reset provenance in the pouch
        # ledger. The acquisition segment first removes any unverified copy.
        return keyword
    matching_potions = tuple(
        candidate
        for candidate in potion_peers
        if keyword.casefold()
        in {word.casefold() for word in candidate.keywords.split()}
    )
    if not matching_potions or not all(
        required_spell in potion_spell_names(candidate)
        and not (
            set(potion_spell_names(candidate))
            & _UNSAFE_SELF_POTION_SPELLS
        )
        for candidate in matching_potions
    ):
        return None
    return keyword


def _select_provision_funding_candidate(
    state: dict[str, Any],
    *,
    character_level: int,
    boot_kill_counts: Mapping[str, int] | None,
    boot_id: str | int | None,
    source_directory: Path,
    gear_catalog: GearCatalog | None,
    boot_kill_counts_by_mobile_vnum: Mapping[int, int] | None = None,
    prefer_completed_funding_candidate: bool = False,
) -> HuntCandidate | None:
    """Choose one source-safe current-reboot target to fund provisions.

    When flight money is the immediate blocker, reuse a same-reboot successful
    funding target before spending another segment on an untried candidate.
    Ordinary food funding keeps the broader fresh-candidate rotation.
    """
    if character_level < 2 or not source_directory.is_dir():
        return None
    world = load_world_source(source_directory, include_all_areas=True)
    candidates = rank_hunt_candidates(
        world,
        character_level=character_level,
        boot_kill_counts=boot_kill_counts,
        boot_kill_counts_by_mobile_vnum=boot_kill_counts_by_mobile_vnum,
        include_below_band=True,
        character_max_hp=(
            int(state["max_hp"])
            if isinstance(state.get("max_hp"), (int, float))
            else None
        ),
        include_all_areas=True,
    )
    if hasattr(world, "room_object_resets"):
        candidates.extend(
            rank_coin_stashes(
                world,
                character_level=character_level,
                include_all_areas=True,
            )
        )
    attempted: set[str] = set()
    attempt_order: list[str] = []
    completed_attempts: set[str] = set()
    failed_attempts: set[str] = set()
    latest_attempt_completed: dict[str, bool] = {}
    last_attempted: str | None = None
    realized_proceeds: dict[str, int] = {}
    raw_proceeds = state.get(_PROVISION_FUNDING_PROCEEDS_KEY)
    if isinstance(raw_proceeds, (list, tuple)):
        for record in raw_proceeds:
            if not isinstance(record, Mapping) or record.get("boot_id") != boot_id:
                continue
            candidate_key = record.get("candidate_key")
            if candidate_key is None:
                continue
            try:
                realized_proceeds[str(candidate_key)] = max(
                    0,
                    int(record.get("proceeds") or 0),
                )
            except (TypeError, ValueError):
                continue
    raw_attempts = state.get(_PROVISION_FUNDING_ATTEMPTS_KEY)
    if isinstance(raw_attempts, (list, tuple)):
        for record in raw_attempts:
            if not isinstance(record, dict) or record.get("boot_id") != boot_id:
                continue
            candidate_key = record.get("candidate_key")
            if candidate_key is None:
                continue
            candidate_key = str(candidate_key)
            attempted.add(candidate_key)
            if candidate_key not in attempt_order:
                attempt_order.append(candidate_key)
            last_attempted = candidate_key
            if record.get("completed_kill") is True:
                completed_attempts.add(candidate_key)
            else:
                failed_attempts.add(candidate_key)
            latest_attempt_completed[candidate_key] = (
                record.get("completed_kill") is True
            )
    last_attempt = state.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
    if (
        isinstance(last_attempt, dict)
        and last_attempt.get("boot_id") == boot_id
        and last_attempt.get("candidate_key") is not None
    ):
        last_attempted = str(last_attempt["candidate_key"])

    funding_requirement_active = bool(
        state.get(_PROVISION_FUNDING_REQUIRED_KEY)
        or state.get(_FLIGHT_FUNDING_REQUIRED_KEY)
        or state.get(_FLIGHT_FUNDING_RETRY_KEY)
        or prefer_completed_funding_candidate
    )

    flight_shortfall = 0
    if prefer_completed_funding_candidate:
        flight_shortfall = max(
            0,
            _flight_purchase_minimum(state) - _state_copper_value(state),
        )

    def funding_eligible_candidate(candidate: HuntCandidate) -> bool:
        candidate_key = _provision_funding_candidate_key(candidate)
        source_policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        source_result = _campaign_research_results(state).get(source_policy_id)
        if (
            candidate.mobile_vnum is not None
            and isinstance(source_result, Mapping)
            and source_result.get("boot_id") == boot_id
            and (
                source_result.get("route_hazard")
                or source_result.get("unattackable")
                or source_result.get("target_vnum_mismatch")
                or source_result.get("consider_viable") is False
                or source_result.get("absent")
                or source_result.get("crowded")
                or source_result.get("viable") is False
                or source_result.get("completed_kill") is False
                or source_result.get("retryable_failure")
                or source_result.get("fatal_failure")
            )
        ):
            # Funding must not resurrect a mobile whose same-reboot hunt
            # already proved a route, identity, consider, retry, or fatal
            # boundary.
            return False
        return (
            candidate.status != "reject"
            and candidate.autonomous_safe
            and candidate.estimated_level_range[1] <= character_level
            and _source_candidate_fits_movement(candidate, state)
            and (
                not _funding_candidate_has_persisted_below_band_sighting(
                    state,
                    candidate,
                    character_level=character_level,
                    boot_id=boot_id,
                )
                or candidate_key in completed_attempts
                or (
                    prefer_completed_funding_candidate
                    and flight_shortfall > 0
                    and realized_proceeds.get(candidate_key, 0) > 0
                )
                or (
                    funding_requirement_active
                    and candidate.contained_coins > 0
                )
            )
            and (
                candidate.boot_kills < 3
                or (
                    prefer_completed_funding_candidate
                    and (
                        candidate_key in completed_attempts
                        or realized_proceeds.get(candidate_key, 0) > 0
                    )
                )
            )
            and _candidate_has_saleable_funding_drop(
                candidate,
                gear_catalog=gear_catalog,
            )
        )

    all_candidates = [
        candidate
        for candidate in candidates
        if funding_eligible_candidate(candidate)
    ]
    all_eligible = [
        candidate
        for candidate in all_candidates
        if _provision_funding_candidate_key(candidate) not in completed_attempts
    ]
    never_attempted = [
        candidate
        for candidate in all_eligible
        if _provision_funding_candidate_key(candidate) not in attempted
    ]
    fresh_coin_stashes = [
        candidate for candidate in never_attempted if candidate.is_coin_stash
    ]
    fresh_coin_carriers = [
        candidate
        for candidate in never_attempted
        if candidate.is_coin_stash or candidate.contained_coins > 0
    ]
    realized_coin_stashes = [
        candidate
        for candidate in all_candidates
        if (
            prefer_completed_funding_candidate
            and flight_shortfall > 0
            and candidate.is_coin_stash
            and realized_proceeds.get(
                _provision_funding_candidate_key(candidate),
                0,
            )
            > 0
            and _provision_funding_candidate_key(candidate) != last_attempted
            and not candidate.route_preflight_hard_hazard
        )
    ]
    # A directly reset coin pile or a mobile carrying coins is a funding
    # opportunity that avoids making a previously profitable gear drop the
    # default retry. Prefer either kind of fresh coin carrier over replaying
    # an old below-band item carrier.
    eligible = fresh_coin_carriers or never_attempted
    if realized_coin_stashes and not fresh_coin_carriers:
        # A direct stash may have yielded usable currency even when the
        # attempt ended before the stash completion gate (for example, after
        # a safe route boundary). Re-probe that observed source before
        # spending another segment on a lower-yield fresh gear carrier.
        eligible = realized_coin_stashes
    if not eligible:
        # A successful funding kill may have already been sold or spent. Once
        # every other source-safe candidate has had one bounded attempt, reuse
        # that target before cycling failed candidates forever.
        reusable_completed = [
            candidate
            for candidate in all_candidates
            if (
                (
                    _provision_funding_candidate_key(candidate) in completed_attempts
                    and latest_attempt_completed.get(
                        _provision_funding_candidate_key(candidate)
                    )
                    is True
                    and not _funding_candidate_is_below_band(
                        state,
                        candidate,
                        character_level=character_level,
                        boot_id=boot_id,
                    )
                    and candidate.estimated_level_range[1] > character_level - 5
                )
                or (
                    prefer_completed_funding_candidate
                    and flight_shortfall > 0
                    and _funding_candidate_has_persisted_below_band_sighting(
                        state,
                        candidate,
                        character_level=character_level,
                        boot_id=boot_id,
                    )
                    and realized_proceeds.get(
                        _provision_funding_candidate_key(candidate),
                        0,
                    ) > 0
                )
            )
        ]
        if reusable_completed:
            eligible = reusable_completed
        else:
            # A missing or failed reset is temporary. Once every source-safe
            # candidate has had one bounded attempt, rotate to another failed
            # candidate instead of declaring the generic money loop exhausted.
            retryable = [
                candidate
                for candidate in all_eligible
                if _provision_funding_candidate_key(candidate) in failed_attempts
            ]
            retryable_by_key = {
                _provision_funding_candidate_key(candidate): candidate
                for candidate in retryable
            }
            if last_attempted in attempt_order:
                start = attempt_order.index(last_attempted) + 1
                rotated_keys = attempt_order[start:] + attempt_order[:start]
                eligible = [
                    retryable_by_key[key]
                    for key in rotated_keys
                    if key in retryable_by_key
                ]
            else:
                eligible = retryable
    reusable_completed = [
        candidate
        for candidate in all_candidates
        if (
            (
                _provision_funding_candidate_key(candidate) in completed_attempts
                and latest_attempt_completed.get(
                    _provision_funding_candidate_key(candidate)
                )
                is True
                and not _funding_candidate_is_below_band(
                    state,
                    candidate,
                    character_level=character_level,
                    boot_id=boot_id,
                )
                and (
                    candidate.estimated_level_range[1] > character_level - 5
                    or (
                        prefer_completed_funding_candidate
                        and flight_shortfall > 0
                        and candidate.is_coin_stash
                    )
                )
            )
            or (
                prefer_completed_funding_candidate
                and flight_shortfall > 0
                and _funding_candidate_has_persisted_below_band_sighting(
                    state,
                    candidate,
                    character_level=character_level,
                    boot_id=boot_id,
                )
                and realized_proceeds.get(
                    _provision_funding_candidate_key(candidate),
                    0,
                ) > 0
            )
        )
    ]
    if (
        prefer_completed_funding_candidate
        and reusable_completed
        and not fresh_coin_carriers
        and not realized_coin_stashes
    ):
        eligible = reusable_completed
    preferred = [
        candidate
        for candidate in eligible
        if not _funding_candidate_is_below_band(
            state,
            candidate,
            character_level=character_level,
            boot_id=boot_id,
        )
        and (
            candidate.is_coin_stash
            or candidate.estimated_level_range[1] > character_level - 5
        )
    ]
    # A money-only segment may use a source-safe, statically or live-confirmed
    # below-band carrier only when every useful-band saleable target is
    # exhausted. The dispatch layer marks its first saleable drop as required
    # loot so this is never treated as an XP hunt.
    below_band_fallback = not preferred
    eligible = preferred or eligible
    if len(eligible) > 1 and last_attempted:
        # Metadata repair can reorder a bounded history while a live segment
        # is closing. Preserve the funding loop's rotation invariant even if
        # that leaves the just-failed candidate in the fallback pool.
        rotated = [
            candidate
            for candidate in eligible
            if _provision_funding_candidate_key(candidate) != last_attempted
        ]
        if rotated:
            eligible = rotated
    if not eligible:
        return None
    if below_band_fallback:
        if prefer_completed_funding_candidate and reusable_completed:
            return max(
                eligible,
                key=lambda candidate: (
                    realized_proceeds.get(
                        _provision_funding_candidate_key(candidate),
                        0,
                    ),
                    _funding_candidate_source_value(candidate),
                    candidate.contained_coins > 0,
                    -len(candidate.route),
                    candidate.score,
                ),
            )
        return max(
            eligible,
            key=lambda candidate: (
                -len(candidate.route),
                candidate.contained_coins > 0,
                candidate.source_value,
                candidate.score,
                min(candidate.estimated_level_range[1], character_level),
            ),
        )

    def funding_priority(candidate: HuntCandidate) -> tuple[float, int, int, float, int]:
        """Prefer useful proceeds per safe route effort over target level."""
        observed_proceeds = realized_proceeds.get(
            _provision_funding_candidate_key(candidate),
            0,
        )
        proceeds = (
            observed_proceeds
            if (
                prefer_completed_funding_candidate
                and candidate.is_coin_stash
                and observed_proceeds > 0
            )
            else max(0, candidate.source_value) + max(
                0, candidate.contained_coins
            )
        )
        route_effort = max(
            candidate.estimated_move_cost,
            len(candidate.route),
            1,
        )
        return (
            proceeds / route_effort,
            proceeds,
            min(candidate.estimated_level_range[1], character_level),
            candidate.score,
            -len(candidate.route),
        )

    return max(
        eligible,
        key=funding_priority,
    )


def _record_provision_funding_attempt(
    state: dict[str, Any],
    *,
    candidate: HuntCandidate,
    boot_id: str | int | None,
    completed_kill: bool,
) -> dict[str, Any]:
    """Persist a funding attempt without losing the need for provisions."""
    recorded = dict(state)
    attempts = [
        dict(record)
        for record in state.get(_PROVISION_FUNDING_ATTEMPTS_KEY, ())
        if isinstance(record, dict)
    ]
    attempts.append(
        {
            "boot_id": boot_id,
            "candidate_key": _provision_funding_candidate_key(candidate),
            "target": candidate.target,
            "room_vnum": candidate.room_vnum,
            "completed_kill": completed_kill,
        }
    )
    recorded[_PROVISION_FUNDING_ATTEMPTS_KEY] = attempts[-_PROVISION_FUNDING_HISTORY_LIMIT:]
    recorded[_PROVISION_FUNDING_LAST_ATTEMPT_KEY] = {
        "boot_id": boot_id,
        "candidate_key": _provision_funding_candidate_key(candidate),
        "completed_kill": completed_kill,
    }
    if completed_kill:
        recorded.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
    else:
        recorded[_PROVISION_FUNDING_REQUIRED_KEY] = True
    return recorded


def _provision_funding_completed(
    candidate: HuntCandidate | None,
    *,
    start_state: Mapping[str, Any],
    end_state: Mapping[str, Any],
    objective_kills: Collection[Any] | None,
) -> bool:
    """Require the selected funding source to produce usable evidence."""
    if candidate is None:
        return False
    currency_increased = _state_copper_value(dict(end_state)) > _state_copper_value(
        dict(start_state)
    )
    if candidate.is_coin_stash:
        return currency_increased

    matching_kill = False
    candidate_name = normalize_item_name(candidate.target)
    candidate_keyword = normalize_item_name(candidate.target_keyword)
    for kill in objective_kills or ():
        if not isinstance(kill, Mapping):
            continue
        if candidate.mobile_vnum is not None:
            try:
                if int(kill.get("source_mobile_vnum")) == int(
                    candidate.mobile_vnum
                ):
                    matching_kill = True
                    break
            except (TypeError, ValueError):
                pass
        kill_name = normalize_item_name(
            str(kill.get("mob_name") or kill.get("target") or "")
        )
        if kill_name in {candidate_name, candidate_keyword}:
            matching_kill = True
            break
    if not matching_kill:
        return False
    if candidate.contained_coins > 0:
        # A carrier kill without a currency delta usually means the purse or
        # coin container could not be collected because the inventory was
        # full. Let the next bounded attempt retry after capacity relief.
        return currency_increased
    if not candidate.loot:
        return True
    return not _missing_required_inventory_items(
        end_state.get("inventory"),
        tuple(candidate.loot),
    )


def _record_provision_funding_proceeds(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    sales: Collection[Mapping[str, Any]],
    boot_id: str | int | None,
) -> dict[str, Any]:
    """Attach realized shop proceeds to the latest funding candidate.

    Source object costs are only prototype metadata. DD4 derives live loot
    cost from reset level and then applies the shop's duplicate penalty, so a
    funding retry must use observed sale rows rather than prototype cost.
    """
    last_attempt = previous.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
    if not isinstance(last_attempt, Mapping):
        return current
    candidate_key = last_attempt.get("candidate_key")
    if candidate_key is None or boot_id is None:
        return current
    proceeds = 0
    for sale in sales:
        try:
            if isinstance(sale, Mapping):
                sold_coins = sale.get("sold_coins")
                offered_coins = sale.get("offered_coins")
            else:
                sold_coins = sale["sold_coins"]
                offered_coins = sale["offered_coins"]
            proceeds += max(
                0,
                int(sold_coins or offered_coins or 0),
            )
        except (KeyError, TypeError, ValueError):
            continue
    if proceeds <= 0:
        return current

    records: list[dict[str, Any]] = []
    raw_records = previous.get(_PROVISION_FUNDING_PROCEEDS_KEY)
    if isinstance(raw_records, (list, tuple)):
        for raw in raw_records:
            if isinstance(raw, Mapping):
                records.append(dict(raw))
    matching = None
    for record in records:
        if (
            record.get("boot_id") == boot_id
            and str(record.get("candidate_key")) == str(candidate_key)
        ):
            matching = record
            break
    if matching is None:
        matching = {
            "boot_id": boot_id,
            "candidate_key": str(candidate_key),
            "proceeds": 0,
        }
        records.append(matching)
    try:
        matching["proceeds"] = max(0, int(matching.get("proceeds") or 0)) + proceeds
    except (TypeError, ValueError):
        matching["proceeds"] = proceeds
    recorded = dict(current)
    recorded[_PROVISION_FUNDING_PROCEEDS_KEY] = records[-_PROVISION_FUNDING_HISTORY_LIMIT:]
    return recorded


def _has_campaign_food(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
) -> bool:
    if "inventory" not in state:
        return True
    for description in _inventory_descriptions(state.get("inventory")):
        normalized = normalize_item_name(description)
        if "pie" in normalized or "steak" in normalized:
            return True
        item = gear_catalog.match(description) if gear_catalog is not None else None
        if (
            item is not None
            and item.item_type == 19
            and len(item.values) >= 4
            and item.values[3] <= 0
        ):
            return True
    return False


def _needs_piercing_weapon_upgrade(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    character_class: str,
    subclass: str | None,
    target_vnum: int = _PIERCING_WEAPON_UPGRADE_VNUM,
) -> bool:
    """Compare known carried piercing weapons with the registered source upgrade."""
    if gear_catalog is None:
        return False
    target = gear_catalog.objects.get(target_vnum)
    if (
        target is None
        or not is_piercing_weapon(target)
        or not character_can_use_item(
            target,
            character_class=character_class,
            subclass=subclass,
        )
    ):
        return False
    descriptions = [
        *(
            str(description)
            for description in state.get("campaign_worn_equipment") or ()
        ),
        *_inventory_descriptions(state.get("inventory")),
    ]
    current_score = max(
        (
            weapon_damage_score(item)
            for description in descriptions
            if (item := gear_catalog.match(description)) is not None
            if is_piercing_weapon(item)
            and character_can_use_item(
                item,
                character_class=character_class,
                subclass=subclass,
            )
        ),
        default=0,
    )
    return current_score < weapon_damage_score(target)


def _state_has_source_weapon_role(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    character_class: str,
    subclass: str | None,
    predicate: Callable[[Any], bool],
    worn_only: bool = False,
) -> bool:
    """Return whether persisted inventory or worn gear proves a weapon role."""
    if gear_catalog is None:
        return False
    if worn_only and (
        state.get("campaign_has_weapon") is False
        or "wield" in set(state.get("campaign_empty_equipment_categories") or ())
    ):
        # A direct ``You wield`` acknowledgement can be left over from an
        # earlier response chunk or segment.  An explicit empty current slot,
        # or a reconciled false weapon flag, is stronger evidence.
        return False
    primary_weapon = state.get("campaign_primary_weapon")
    if worn_only and "campaign_primary_weapon" in state:
        descriptions = [str(primary_weapon)] if primary_weapon else []
    else:
        descriptions = [
            *(
                str(description)
                for description in state.get("campaign_worn_equipment") or ()
            )
        ]
    if not worn_only:
        descriptions.extend(_inventory_descriptions(state.get("inventory")))
    # The persisted worn description is the primary proof of a wielded role;
    # inventory evidence is also useful when a disarm or reconnect has left
    # the item carried.  Source matching already restricts this to usable
    # catalog objects, and the role predicate restricts it to real weapons.
    return any(
        predicate(item)
        for item in gear_catalog.match_many_usable(
            descriptions,
            character_class=character_class,
            subclass=subclass,
        )
    )


def _state_has_digging_capability(
    state: Mapping[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    character_class: str,
    subclass: str | None,
) -> bool:
    """Mirror DD4's ordered ``do_dig`` capability checks from persisted state."""
    if gear_catalog is None:
        return False
    form = str(state.get("form") or "").casefold()
    if (subclass or "").casefold() == "werewolf" or any(
        name in form for name in ("bear", "wolf", "dire wolf", "direwolf")
    ):
        return True

    carried_descriptions = _inventory_descriptions(state.get("inventory"))
    worn_descriptions = [
        str(description)
        for description in state.get("campaign_worn_equipment") or ()
    ]
    primary_weapon = state.get("campaign_primary_weapon")
    if isinstance(primary_weapon, str) and primary_weapon.strip():
        worn_descriptions.append(primary_weapon)
    descriptions = gear_catalog.match_many_usable(
        [*carried_descriptions, *worn_descriptions],
        character_class=character_class,
        subclass=subclass,
    )
    if any(is_digging_tool(item) for item in descriptions):
        return True

    # DD4 only checks the wielded and dual-wielded weapon slots for this
    # fallback; persisted worn equipment is the closest durable representation
    # of those slots in a campaign checkpoint.
    worn_items = gear_catalog.match_many_usable(
        worn_descriptions,
        character_class=character_class,
        subclass=subclass,
    )
    return any(is_digging_weapon(item) for item in worn_items)


def _state_needs_better_piercing_weapon(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    character_class: str,
    subclass: str | None,
) -> bool:
    """Return whether a carried piercing weapon outranks the worn primary."""
    if gear_catalog is None:
        return False
    current_weapon = None
    primary_description = state.get("campaign_primary_weapon")
    if isinstance(primary_description, str) and primary_description.strip():
        candidate = gear_catalog.match(primary_description)
        if candidate is not None and item_category(candidate) == "wield":
            current_weapon = candidate
    if current_weapon is None:
        for description in state.get("campaign_worn_equipment") or ():
            candidate = gear_catalog.match(str(description))
            if candidate is not None and item_category(candidate) == "wield":
                current_weapon = candidate
                break
    if current_weapon is None or not is_piercing_weapon(current_weapon):
        return True
    current_score = weapon_damage_score(current_weapon)
    return any(
        is_piercing_weapon(item)
        and weapon_damage_score(item) > current_score
        for item in gear_catalog.match_many_usable(
            _inventory_descriptions(state.get("inventory")),
            character_class=character_class,
            subclass=subclass,
        )
        if item_category(item) == "wield"
    )


def _has_own_corpse_recovery(
    state: dict[str, Any],
    character_name: str,
) -> bool:
    needle = f"corpse of {character_name}".casefold()
    acquisitions = state.get("acquired_items")
    if not isinstance(acquisitions, list):
        return False
    return any(
        needle in str(acquisition.get("item", "")).casefold()
        for acquisition in acquisitions
        if isinstance(acquisition, dict)
    )


def _campaign_policy_xp_deltas(
    segments: list[Any],
    *,
    storage: RunStorage | None = None,
) -> dict[str, int]:
    """Return each policy's latest bounded result, discounting unconfirmed hunts."""
    results: dict[str, int] = {}
    for segment in segments:
        if segment["status"] not in {"success", "ready"}:
            continue
        start = json.loads(segment["start_state_json"] or "{}")
        end = json.loads(segment["end_state_json"] or "{}")
        if not end:
            continue
        phase = str(segment["phase"])
        objective_kills = _segment_objective_kills(storage, segment)
        if (
            results.get(phase, 0) > 0
            and isinstance(objective_kills, list)
            and not objective_kills
            and (
                end.get("campaign_fastwalk_crowded")
                or any(
                    str(
                        end.get("campaign_fastwalk_abort_reason") or ""
                    ).startswith(prefix)
                    for prefix in _FIELD_CROWD_ABORT_PREFIXES
                )
            )
        ):
            # A crowded field is transient route-state evidence. Preserve a
            # confirmed productive result for this policy so a later rotation
            # can retry it after the crowd cooldown instead of erasing its
            # only useful progression path.
            continue
        if (
            phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and objective_kills is None
        ):
            # Source-ranked progress requires an objective ledger. A positive
            # XP delta without one can only be incidental transit combat.
            objective_kills = []
        results[phase] = _effective_policy_xp_delta(
            start,
            end,
            completed_kills=objective_kills,
            require_objective_kill=phase.startswith(_SOURCE_RANKED_POLICY_PREFIX),
        )
    return results


def _source_ranked_no_progress_streak(
    segments: Collection[Any],
    *,
    storage: RunStorage | None = None,
    boot_id: Any,
    character_level: int,
) -> int:
    """Count trailing same-level source hunts with no objective XP this reboot."""
    if boot_id is None:
        return 0
    streak = 0
    for segment in reversed(tuple(segments)):
        if str(segment["phase"]).startswith(_SOURCE_RANKED_POLICY_PREFIX):
            if segment["status"] not in {"success", "ready"}:
                continue
            try:
                start = json.loads(segment["start_state_json"] or "{}")
                end = json.loads(segment["end_state_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                continue
            if not end:
                continue
            segment_boot_id = end.get("world_boot_id")
            if segment_boot_id != boot_id:
                break
            if _level(end) != character_level:
                break
            if (
                _effective_policy_xp_delta(
                    start,
                    end,
                    completed_kills=_segment_objective_kills(storage, segment),
                    require_objective_kill=True,
                )
                > 0
            ):
                break
            streak += 1
    return streak


def _source_ranked_no_progress_policy_ids(
    segments: Collection[Any],
    *,
    storage: RunStorage | None = None,
    boot_id: Any,
    character_level: int,
) -> frozenset[str]:
    """Return the bounded trailing source routes that produced no XP."""
    if boot_id is None:
        return frozenset()
    policy_ids: set[str] = set()
    for segment in reversed(tuple(segments)):
        phase = str(segment["phase"])
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if segment["status"] not in {"success", "ready"}:
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not end:
            continue
        if end.get("world_boot_id") != boot_id:
            break
        if _level(end) != character_level:
            break
        if (
            _effective_policy_xp_delta(
                start,
                end,
                completed_kills=_segment_objective_kills(storage, segment),
                require_objective_kill=True,
            )
            > 0
        ):
            break
        policy_ids.add(phase)
        if len(policy_ids) >= _SOURCE_RANKED_NO_PROGRESS_POLICY_LIMIT:
            break
    return frozenset(policy_ids)


def _campaign_productive_policy_ids(
    segments: list[Any],
    *,
    storage: RunStorage | None = None,
    boot_id: str | int | None = None,
) -> frozenset[str]:
    """Collect same-reboot hunt policies with a meaningful objective kill."""
    productive: set[str] = set()
    for segment in segments:
        if segment["status"] not in {"success", "ready"}:
            continue
        phase = str(segment["phase"])
        if "-hunt" not in phase:
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not end or (boot_id is not None and end.get("world_boot_id") != boot_id):
            continue
        objective_kills = _segment_objective_kills(storage, segment)
        _total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
            objective_kills
        )
        meaningful_kill = (
            max_kill_xp >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
            if explicit_xp
            else _xp_delta(start, end)
            >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        )
        if (
            isinstance(objective_kills, list)
            and objective_kills
            and meaningful_kill
            and _xp_delta(start, end) > 0
        ):
            # A wandering source mobile can be killed at a different reset
            # room than the selected anchor. Preserve the actual source
            # policy identity when it is present; falling back to the segment
            # phase keeps older untagged records compatible.
            source_policy_ids = _source_ranked_kill_policy_ids(objective_kills)
            productive.update(source_policy_ids or (phase,))
    return frozenset(productive)


def _state_productive_policy_ids(state: Mapping[str, Any]) -> frozenset[str]:
    """Read productive-policy history only when it matches the current boot."""
    history = state.get(_PRODUCTIVE_POLICY_HISTORY_KEY)
    if not isinstance(history, Mapping):
        return frozenset()
    if history.get("boot_id") != state.get("world_boot_id"):
        return frozenset()
    policy_ids = history.get("policy_ids")
    if not isinstance(policy_ids, (list, tuple, set, frozenset)):
        return frozenset()
    return frozenset(str(policy_id) for policy_id in policy_ids if policy_id)


def _has_independent_productive_source_history(
    state: Mapping[str, Any],
) -> bool:
    """Return whether current-reboot history can seed an independent fallback."""
    marker = state.get(_PROTECTION_RECOVERY_KEY)
    failed_policy_id = (
        str(marker.get("policy_id") or "")
        if isinstance(marker, Mapping)
        else ""
    )
    return any(
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and "-hunt-" in policy_id
        and policy_id != failed_policy_id
        for policy_id in _state_productive_policy_ids(state)
    )


def _mark_retryable_research_failures(state: dict[str, Any]) -> dict[str, Any]:
    """Keep productive hunts retryable after a safe, incomplete combat pass."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return state
    productive_policy_ids = _state_productive_policy_ids(state)
    if not productive_policy_ids:
        return state
    results = dict(state.get("campaign_research_results") or {})
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    changed = False
    for policy_id in productive_policy_ids:
        raw_result = results.get(policy_id)
        if (
            isinstance(raw_result, dict)
            and raw_result.get("boot_id") == boot_id
            and policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and raw_result.get("consider_viable") is False
        ):
            # A source-ranked negative consider is terminal for this level and
            # reboot even when an earlier incarnation of the policy was
            # productive. Never turn level-band evidence into a combat retry.
            result = dict(raw_result)
            result.pop("retryable_failure", None)
            result.pop("previously_productive", None)
            if result != raw_result:
                results[policy_id] = result
                changed = True
            if policy_id in absence_cooldowns:
                absence_cooldowns.pop(policy_id, None)
                changed = True
            continue
        if not (
            isinstance(raw_result, dict)
            and raw_result.get("boot_id") == boot_id
            and raw_result.get("observed") is True
            and raw_result.get("viable") is False
            and raw_result.get("completed_kill") is False
            and not raw_result.get("absent")
            and not raw_result.get("route_hazard")
            and not raw_result.get("crowded")
            and not raw_result.get("unattackable")
        ):
            continue
        result = dict(raw_result)
        retry_cooldown = _research_absence_retry_cooldown(
            policy_id,
            default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
        )
        if not result.get("retryable_failure"):
            result["retryable_failure"] = True
            changed = True
        if not result.get("previously_productive"):
            result["previously_productive"] = True
            changed = True
        if results.get(policy_id) != result:
            results[policy_id] = result
            changed = True
        if absence_cooldowns.get(policy_id) != retry_cooldown:
            absence_cooldowns[policy_id] = retry_cooldown
            changed = True
        if policy_id in cleared_research_policies:
            cleared_research_policies.discard(policy_id)
            changed = True
    if not changed:
        return state
    updated = dict(state)
    updated["campaign_research_results"] = results
    if absence_cooldowns:
        updated[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        updated.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if cleared_research_policies:
        updated[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        updated.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return updated


def _with_productive_policy_history(
    state: Mapping[str, Any],
    *,
    policy_ids: Collection[str],
    boot_id: str | int | None,
    replace_source_ranked_hunt_ids: bool = False,
) -> dict[str, Any]:
    """Merge durable same-reboot productive hunt identities into state."""
    updated = dict(state)
    if boot_id is None:
        return updated
    current_ids = _state_productive_policy_ids(state)
    if replace_source_ranked_hunt_ids:
        current_ids = frozenset(
            policy_id
            for policy_id in current_ids
            if not (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and "-hunt-" in policy_id
            )
        )
    merged_ids = current_ids | {str(policy_id) for policy_id in policy_ids}
    if merged_ids:
        updated[_PRODUCTIVE_POLICY_HISTORY_KEY] = {
            "boot_id": boot_id,
            "policy_ids": sorted(merged_ids),
        }
    else:
        updated.pop(_PRODUCTIVE_POLICY_HISTORY_KEY, None)
    return updated


def _effective_policy_xp_delta(
    start: dict[str, Any],
    end: dict[str, Any],
    *,
    completed_kills: Any,
    require_objective_kill: bool = False,
) -> int:
    """Ignore incidental XP from a field segment with no confirmed kill."""
    xp_delta = _xp_delta(start, end)
    if xp_delta > 0 and (
        require_objective_kill and not completed_kills
        or isinstance(completed_kills, list) and not completed_kills
    ):
        return 0
    return xp_delta


def _run_objective_kills(
    storage: RunStorage,
    run_id: int,
    *,
    execution: str | None = None,
) -> list[Any] | None:
    """Read objective kills even when final runner state was never written."""
    for event in reversed(storage.list_events(run_id)):
        if event["kind"] != "state":
            continue
        payload = json.loads(event["payload_json"])
        objective_kills = payload.get("objective_kills")
        if isinstance(objective_kills, list):
            return objective_kills
        completed_kills = payload.get("completed_kills")
        if isinstance(completed_kills, list):
            return completed_kills

    rows = storage.list_mob_kills_for_run(run_id)
    rows = [row for row in rows if bool(row["objective_eligible"])]
    if execution and execution.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        rows = [
            row
            for row in rows
            if row["source_policy_id"] == execution
        ]
    if not rows:
        return None
    kills: list[dict[str, Any]] = []
    for row in rows:
        kill: dict[str, Any] = {
            "mob_name": str(row["mob_name"]),
            "xp_gained": row["xp_gained"],
        }
        if row["source_mobile_vnum"] is not None:
            kill["source_mobile_vnum"] = int(row["source_mobile_vnum"])
        if row["source_policy_id"] is not None:
            kill["source_policy_id"] = str(row["source_policy_id"])
        kills.append(kill)
    return kills


def _objective_kills_for_execution(
    storage: RunStorage,
    run_id: int,
    *,
    execution: str | None,
) -> list[Any] | None:
    """Exclude incidental combat from maintenance and loot-only segments."""
    objective_kills = _run_objective_kills(
        storage,
        run_id,
        execution=execution,
    )
    if not _execution_records_objective_kills(execution):
        return []
    return objective_kills


def _execution_records_objective_kills(execution: str | None) -> bool:
    """Identify segments whose combat is part of the campaign objective."""
    if execution in _NON_OBJECTIVE_MAINTENANCE_PHASES:
        return False
    return not (
        execution in _MAINTENANCE_EXECUTIONS
        and execution != "provision-funding"
    )


def _segment_objective_kills(
    storage: RunStorage | None,
    segment: Mapping[str, Any],
) -> list[Any] | None:
    """Read objective kills while applying the segment's execution boundary."""
    execution = str(segment["phase"] or "")
    if not _execution_records_objective_kills(execution):
        return []
    try:
        end_state = json.loads(segment["end_state_json"] or "{}")
    except (TypeError, json.JSONDecodeError):
        end_state = {}
    if isinstance(end_state, Mapping):
        objective_kills = end_state.get("campaign_objective_kills")
        if objective_kills is None:
            objective_kills = end_state.get("campaign_completed_kills")
        if objective_kills is not None:
            return objective_kills
    if storage is None:
        return None
    run_id = segment["run_id"]
    if run_id is None:
        return None
    return _objective_kills_for_execution(
        storage,
        int(run_id),
        execution=execution,
    )


def _clear_non_objective_maintenance_kills(
    checkpoint: Mapping[str, Any] | None,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Remove legacy kill metadata left by a maintenance checkpoint."""
    if checkpoint is None:
        return state
    phase = str(checkpoint["phase"] or "")
    if _execution_records_objective_kills(phase):
        return state
    updated = dict(state)
    updated.pop("campaign_completed_kills", None)
    updated.pop("campaign_objective_kills", None)
    return updated


def _source_ranked_endpoint_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
) -> dict[str, Any]:
    """Quarantine a source route whose fastwalk never reached its endpoint."""
    updated = dict(state)
    updated.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    updated.update(
        {
            "campaign_fastwalk_abort_reason": (
                f"field route endpoint not observed: {error}"
            ),
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            _SOURCE_CONSIDER_OUTCOMES_KEY: {},
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY: [],
            _SOURCE_ABSENT_SIGHTINGS_KEY: [],
            _SOURCE_PRESENT_SIGHTINGS_KEY: [],
            "campaign_objective_kills": [],
            "campaign_completed_kills": [],
            "campaign_last_policy": policy_id,
            "campaign_policy_revision": _CAMPAIGN_POLICY_REVISION,
        }
    )
    return updated


def _source_ranked_watchdog_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
) -> dict[str, Any]:
    """Quarantine a source route that repeated a movement cycle without progress."""
    updated = dict(state)
    updated.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    route_hazard = f"field route watchdog stopped: {error}"
    updated.update(
        {
            "campaign_fastwalk_abort_reason": route_hazard,
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            _SOURCE_CONSIDER_OUTCOMES_KEY: {},
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY: [],
            _SOURCE_ABSENT_SIGHTINGS_KEY: [],
            _SOURCE_PRESENT_SIGHTINGS_KEY: [],
            "campaign_objective_kills": [],
            "campaign_completed_kills": [],
            "campaign_last_policy": policy_id,
            "campaign_policy_revision": _CAMPAIGN_POLICY_REVISION,
        }
    )
    results = _campaign_research_results(state)
    results[policy_id] = {
        "observed": False,
        "viable": False,
        "route_hazard": route_hazard,
        "retryable_failure": True,
        "boot_id": updated.get("world_boot_id"),
    }
    updated["campaign_research_results"] = results
    retry_cooldown = _research_absence_retry_cooldown(
        policy_id,
        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
    )
    if retry_cooldown is not None:
        absence_cooldowns = dict(
            state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        )
        absence_cooldowns[policy_id] = retry_cooldown
        updated[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    return updated


def _maintenance_route_watchdog_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    execution: str,
    boot_id: str | int | None,
    error: str,
) -> dict[str, Any]:
    """Quarantine an optional maintenance route without failing the campaign."""
    updated = _maintenance_failure_state(
        dict(state),
        execution=execution,
        boot_id=boot_id,
        error=error,
    )
    route_hazard = f"field route watchdog stopped: {error}"
    updated.update(
        {
            "campaign_fastwalk_abort_reason": route_hazard,
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            _SOURCE_CONSIDER_OUTCOMES_KEY: {},
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY: [],
            _SOURCE_ABSENT_SIGHTINGS_KEY: [],
            _SOURCE_PRESENT_SIGHTINGS_KEY: [],
            "campaign_objective_kills": [],
            "campaign_completed_kills": [],
        }
    )
    hazards = dict(updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY) or {})
    hazards[policy_id] = {
        "boot_id": updated.get("world_boot_id") or boot_id,
        "route_hazard": route_hazard,
        "retryable_failure": True,
    }
    updated[_MAINTENANCE_ROUTE_HAZARDS_KEY] = hazards
    if execution == "upgrade-piercing-weapon":
        updated[_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = max(
            int(updated.get(_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY) or 0),
            _PIERCING_WEAPON_UPGRADE_COOLDOWN_SEGMENTS,
        )
        if boot_id is not None:
            updated[_PIERCING_WEAPON_UPGRADE_BOOT_KEY] = boot_id
        if policy_id == "thalos-long-dagger-upgrade-10-29":
            updated[_INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = max(
                int(
                    updated.get(
                        _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY
                    )
                    or 0
                ),
                _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_SEGMENTS,
            )
    return updated


def _reconcile_maintenance_fastwalk_state(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
    *,
    execution: str,
    policy_id: str,
    boot_id: str | int | None,
) -> dict[str, Any]:
    """Keep maintenance route observations out of the field-policy ledger."""
    if execution not in _MAINTENANCE_EXECUTIONS:
        return dict(current)

    updated = dict(current)
    abort_reason = str(updated.get("campaign_fastwalk_abort_reason") or "")
    previous_abort_reason = str(
        previous.get("campaign_fastwalk_abort_reason") or ""
    )
    if abort_reason and abort_reason != previous_abort_reason:
        hazards = dict(updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY) or {})
        hazards[policy_id] = {
            "boot_id": updated.get("world_boot_id") or boot_id,
            "route_hazard": abort_reason,
            "retryable_failure": True,
        }
        updated[_MAINTENANCE_ROUTE_HAZARDS_KEY] = hazards

    # A maintenance trip can use the same fastwalk machinery as a hunt. Its
    # transient observations must not replace the last field policy's evidence
    # or make a safe healer checkpoint look like an unfinished hunt.
    fastwalk_keys = (
        "campaign_fastwalk_abort_reason",
        "campaign_fastwalk_target_absent",
        "campaign_fastwalk_target_present_observed",
        "campaign_fastwalk_crowded",
        "campaign_fastwalk_consider_outcomes",
        _SOURCE_CONSIDER_OUTCOMES_KEY,
        _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        _SOURCE_ABSENT_SIGHTINGS_KEY,
        _SOURCE_PRESENT_SIGHTINGS_KEY,
        "campaign_fastwalk_below_band_targets",
        "campaign_fastwalk_route_hazards",
        "campaign_fastwalk_route_preflight_hazard_observed",
        "campaign_fastwalk_target_vnum_mismatch",
        "campaign_fastwalk_unattackable_target",
    )
    for key in fastwalk_keys:
        if key in previous:
            if key == "campaign_fastwalk_abort_reason":
                previous_reason = str(previous[key] or "")
                field_policy = str(previous.get("campaign_last_policy") or "")
                field_result = _campaign_research_results(previous).get(
                    field_policy
                )
                owns_abort = any(
                    previous_reason.startswith(prefix)
                    for prefix in (
                        *_FIELD_CROWD_ABORT_PREFIXES,
                        *_FIELD_ROUTE_HAZARD_ABORT_PREFIXES,
                    )
                ) or (
                    isinstance(field_result, Mapping)
                    and field_result.get("route_hazard") == previous_reason
                )
                if not owns_abort:
                    updated.pop(key, None)
                    continue
            elif key == "campaign_fastwalk_target_absent" and previous[key]:
                field_policy = str(previous.get("campaign_last_policy") or "")
                field_result = _campaign_research_results(previous).get(
                    field_policy
                )
                if not (
                    isinstance(field_result, Mapping)
                    and (
                        field_result.get("absent") is True
                        or field_result.get("verified_empty") is True
                    )
                ):
                    updated.pop(key, None)
                    continue
            updated[key] = previous[key]
        else:
            updated.pop(key, None)
    return updated


def _is_source_ranked_endpoint_failure(error: Any) -> bool:
    """Recognize the fastwalk boundary that must rotate instead of failing."""
    return "returned without observing its endpoint" in str(error or "")


def _is_source_ranked_watchdog_failure(error: Any) -> bool:
    """Recognize a source-route progress watchdog that must rotate safely."""
    text = str(error or "")
    legacy_command_budget = (
        "Starter bot exceeded" in text and "command budget" in text
    )
    return (
        (
            "progress watchdog stopped after repeating" in text
            or "source route command budget" in text
            or legacy_command_budget
        )
        and (
            "route cycle" in text
            or "no policy decision" in text
            or "repeating 'look'" in text
            or "source route command budget" in text
            or legacy_command_budget
        )
    )


def _is_source_ranked_timeout_failure(error: Any) -> bool:
    """Recognize the bounded outer runner cap as a route rotation signal."""
    text = str(error or "")
    return bool(
        "campaign runner exceeded" in text
        and "outer cleanup grace" in text
        or (
            "startup boundary stopped" in text
            and "source route" in text
        )
        or "duplicate timed-out source route" in text
    )


def _run_terminal_state(
    storage: RunStorage,
    run_id: int,
) -> dict[str, Any] | None:
    """Return the latest structured runner completion boundary."""
    for event in reversed(storage.list_events(run_id)):
        if event["kind"] != "state":
            continue
        payload = json.loads(event["payload_json"])
        if payload.get("state") not in {"completed", "runtime_cap"}:
            continue
        return payload
    return None


def _advance_retry_cooldown(
    state: dict[str, Any],
    *,
    key: str,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Advance an optional-loot retry only after productive field work."""
    if execution in _MAINTENANCE_EXECUTIONS or xp_delta <= 0:
        return state
    remaining = int(state.get(key) or 0)
    if remaining <= 0:
        return state
    updated = dict(state)
    updated[key] = remaining - 1
    return updated


def _advance_daycare_ring_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry missing Daycare rings after other productive work."""
    return _advance_retry_cooldown(
        state,
        key=_DAYCARE_RING_COOLDOWN_KEY,
        execution=execution,
        xp_delta=xp_delta,
    )


def _daycare_ring_below_band_observed(state: Mapping[str, Any]) -> bool:
    """Return whether the ring route has direct live below-band evidence."""
    return any(
        state.get(key)
        for key in (
            "campaign_fastwalk_below_band_targets",
            "campaign_fastwalk_below_band_sightings",
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        )
    )


def _clear_daycare_ring_field_metadata(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Keep optional ring retries from contaminating the active XP policy."""
    updated = dict(state)
    for key in (
        "campaign_fastwalk_target_absent",
        "campaign_fastwalk_target_present_observed",
        "campaign_fastwalk_crowded",
        "campaign_fastwalk_abort_reason",
        "campaign_fastwalk_consider_outcomes",
        _SOURCE_CONSIDER_OUTCOMES_KEY,
        _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        _SOURCE_ABSENT_SIGHTINGS_KEY,
        _SOURCE_PRESENT_SIGHTINGS_KEY,
        "campaign_fastwalk_unattackable_target",
        "campaign_fastwalk_target_vnum_mismatch",
    ):
        updated.pop(key, None)

    results = _campaign_research_results(updated)
    results.pop("recover-daycare-ring", None)
    if results:
        updated["campaign_research_results"] = results
    else:
        updated.pop("campaign_research_results", None)

    exclusions = dict(updated.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY) or {})
    exclusions.pop("recover-daycare-ring", None)
    if exclusions:
        updated[_BELOW_BAND_POLICY_EXCLUSIONS_KEY] = exclusions
    else:
        updated.pop(_BELOW_BAND_POLICY_EXCLUSIONS_KEY, None)

    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
    ):
        records = dict(updated.get(key) or {})
        records.pop("recover-daycare-ring", None)
        if records:
            updated[key] = records
        else:
            updated.pop(key, None)

    cleared = {
        str(policy_id)
        for policy_id in updated.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.discard("recover-daycare-ring")
    if cleared:
        updated[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        updated.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return updated


def _advance_war_dog_collar_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry missing war dog collars after other productive work."""
    return _advance_retry_cooldown(
        state,
        key=_WAR_DOG_COLLAR_COOLDOWN_KEY,
        execution=execution,
        xp_delta=xp_delta,
    )


def _advance_piercing_weapon_upgrade_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry the Forest weapon after six productive field segments."""
    return _advance_retry_cooldown(
        state,
        key=_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY,
        execution=execution,
        xp_delta=xp_delta,
    )


def _advance_intermediate_piercing_weapon_upgrade_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry the Thalos weapon after three productive field segments."""
    return _advance_retry_cooldown(
        state,
        key=_INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY,
        execution=execution,
        xp_delta=xp_delta,
    )


def _advance_flight_purchase_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry an optional flight purchase after productive field work."""
    # Provisioning remains maintenance for policy selection, but a funding
    # kill is still productive field work and must be able to age a blocked
    # shop retry.  Without this exception, a blocked shop plus a positive
    # cooldown creates a liveness deadlock because funding cannot advance the
    # counter and the shop cannot be retried.
    cooldown_execution = (
        "provision-funding-progress"
        if execution == "provision-funding" and xp_delta > 0
        else execution
    )
    advanced = _advance_retry_cooldown(
        state,
        key=_FLIGHT_PURCHASE_COOLDOWN_KEY,
        execution=cooldown_execution,
        xp_delta=xp_delta,
    )
    has_flight = any(
        _state_has_active_affect(advanced.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    if not has_flight and not (
        advanced.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and int(advanced.get(_FLIGHT_PURCHASE_COOLDOWN_KEY) or 0) <= 0
    ):
        return advanced
    updated = dict(advanced)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_KEY, None)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY, None)
    if has_flight:
        updated.pop(_FLIGHT_PURCHASE_COOLDOWN_KEY, None)
    return updated


def _xp_delta(before: dict[str, Any], after: dict[str, Any]) -> int:
    """Treat a level gain as progress even when DD4 resets cumulative XP."""
    level_delta = _level(after) - _level(before)
    if level_delta > 0:
        return max(1, level_delta)
    return _numeric_progress(after, "xp") - _numeric_progress(before, "xp")


def _preserve_verified_progress_on_unexplained_regression(
    previous: dict[str, Any],
    current: dict[str, Any],
    merged: dict[str, Any],
) -> None:
    """Reject same-level regressions unless DD4 supplied loss evidence."""
    if (
        current.get("dead")
        or current.get("campaign_died_during_segment")
        or current.get("xp_loss_observed")
        or current.get("campaign_xp_loss_observed")
        or current.get("progress_source") in {"text", "gmcp"}
    ):
        return
    previous_level = _level(previous)
    current_level = _level(current)
    previous_xp = _numeric_progress(previous, "xp")
    current_xp = _numeric_progress(current, "xp")
    if (
        previous_level <= 0
        or current_level != previous_level
        or current_xp >= previous_xp
    ):
        return
    for key in ("level", "xp", "max_xp", "xp_to_next_level"):
        if key in previous:
            merged[key] = previous[key]
    previous_progress = previous.get("progress")
    current_progress = current.get("progress")
    if isinstance(previous_progress, Mapping) and isinstance(
        current_progress, Mapping
    ):
        merged["progress"] = {
            **current_progress,
            **{
                key: previous_progress[key]
                for key in ("level", "xp", "maxxp", "xptnl", "xplvl")
                if key in previous_progress
            },
        }


def _campaign_segment_end_state(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    execution: str,
) -> dict[str, Any]:
    """Keep maintenance facts sticky until their owning policy re-evaluates them."""
    merged = dict(current)
    _preserve_verified_progress_on_unexplained_regression(
        previous,
        current,
        merged,
    )
    if not _execution_records_objective_kills(execution):
        # A maintenance runner can still be attacked by a wandering mobile.
        # Its transient kill ledger belongs to the run transcript, not to the
        # campaign objective ledger. Clear it before the checkpoint is saved.
        merged.pop("campaign_completed_kills", None)
        merged.pop("campaign_objective_kills", None)
    if execution == "source-ranked-hunt":
        # A repair marker authorizes one live attempt, not an indefinite
        # replay loop. Maintenance segments retain it through sticky metadata;
        # the first source-ranked attempt consumes it regardless of outcome.
        merged.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
    for key in _CAMPAIGN_STICKY_METADATA_KEYS:
        if (
            key == _SOURCE_RANKED_REVALIDATION_POLICY_KEY
            and execution == "source-ranked-hunt"
        ):
            # Do not let the sticky pass restore a marker consumed above.
            continue
        if key not in merged and key in previous:
            merged[key] = previous[key]
    protection_marker = merged.get(_PROTECTION_RECOVERY_KEY)
    if (
        isinstance(protection_marker, Mapping)
        and merged.get("world_boot_id") is not None
        and protection_marker.get("boot_id") is not None
        and protection_marker.get("boot_id") != merged.get("world_boot_id")
    ):
        # The sticky metadata pass preserves useful campaign facts between
        # segments, but a protection failure is valid only in its reboot.
        merged.pop(_PROTECTION_RECOVERY_KEY, None)
    if (
        previous.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and execution
        not in {"buy-flight", "buy-flight-potion", "buy-optional-flight"}
    ):
        # StarterPolicy emits a false route-block default on unrelated runs.
        # Keep the live block until productive field work advances its owner.
        merged[_MAGIC_SHOP_ROUTE_BLOCKED_KEY] = True
        if previous.get(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY):
            merged[_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY] = previous[
                _MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY
            ]
    fame = _state_fame(current)
    if fame is not None:
        if fame < 0:
            merged[_SHOP_REARM_REPUTATION_BLOCKED_KEY] = True
        else:
            merged.pop(_SHOP_REARM_REPUTATION_BLOCKED_KEY, None)
    if not current.get("world_boot_id") and previous.get("world_boot_id"):
        merged["world_boot_id"] = previous["world_boot_id"]
    frontier_retry = merged.get(_SOURCE_RANKED_FRONTIER_RETRY_KEY)
    if (
        isinstance(frontier_retry, Mapping)
        and frontier_retry.get("boot_id") != merged.get("world_boot_id")
    ):
        merged.pop(_SOURCE_RANKED_FRONTIER_RETRY_KEY, None)
    elif execution == "source-ranked-hunt" and (
        _level(current) > _level(previous)
        or current.get("campaign_objective_kills")
        or current.get("campaign_completed_kills")
    ):
        # A confirmed kill or level gain starts a fresh frontier cycle. A
        # partial, non-productive retry keeps its one-attempt guard so the
        # campaign cannot spin on the same reboot-local target.
        merged.pop(_SOURCE_RANKED_FRONTIER_RETRY_KEY, None)
    current_flight_price = current.get(_MAGIC_SHOP_FLIGHT_PRICE_KEY)
    if current_flight_price is None:
        for key in (
            _MAGIC_SHOP_FLIGHT_PRICE_KEY,
            _MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY,
        ):
            if merged.get(key) is None and previous.get(key) is not None:
                merged[key] = previous[key]
    else:
        # A standalone shop run can observe the list price before it issues
        # `time`, leaving the policy's price boot unset. Bind that fresh quote
        # to the campaign's known current reboot instead of retaining a stale
        # prior-reboot stamp.
        current_price_boot = current.get(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY)
        if current_price_boot:
            merged[_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY] = current_price_boot
        elif merged.get("world_boot_id"):
            merged[_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY] = merged["world_boot_id"]
        else:
            merged.pop(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY, None)
    if (
        "combat_pouch_potions" not in current
        and "combat_pouch_potions" in previous
    ):
        merged["combat_pouch_potions"] = previous["combat_pouch_potions"]
    if (
        "verified_combat_pouch_potions" not in current
        and "verified_combat_pouch_potions" in previous
    ):
        merged["verified_combat_pouch_potions"] = previous[
            "verified_combat_pouch_potions"
        ]
    if (
        execution
        not in {"buy-flight", "buy-flight-potion", "buy-optional-flight"}
        and previous.get("magic_shop_purchase_failed")
    ):
        merged["magic_shop_purchase_failed"] = True
    if previous.get("vault_storage_rejected"):
        merged["vault_storage_rejected"] = True
    if _SACK_VAULT_ITEMS_KEY in previous:
        merged[_SACK_VAULT_ITEMS_KEY] = previous[_SACK_VAULT_ITEMS_KEY]
    if _SACK_VAULT_RECLAIM_LEVEL_KEY in previous:
        merged[_SACK_VAULT_RECLAIM_LEVEL_KEY] = previous[
            _SACK_VAULT_RECLAIM_LEVEL_KEY
        ]
    for owner, key in (
        ("outfit-basic-gear", "campaign_outfit_attempted_level"),
        ("recover-basic-body", "campaign_body_gear_attempted_level"),
        (
            "recover-school-wrist-float",
            "campaign_school_wrist_float_attempted_level",
        ),
        ("recover-gremlin-waist", "campaign_gremlin_waist_attempted_level"),
        ("recover-daycare-ring", "campaign_daycare_ring_attempted_level"),
        ("recover-daycare-ring", _DAYCARE_RING_ATTEMPT_BOOT_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_COOLDOWN_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_BLOCKED_LEVEL_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_BLOCKED_BOOT_KEY),
        ("recover-war-dog-collar", "campaign_war_dog_collar_attempted_level"),
        ("recover-war-dog-collar", _WAR_DOG_COLLAR_ATTEMPT_BOOT_KEY),
        ("recover-war-dog-collar", _WAR_DOG_COLLAR_COOLDOWN_KEY),
        (
            "recover-foundry-set-circlet",
            _FOUNDRY_SET_CIRCLET_ATTEMPTED_LEVEL_KEY,
        ),
        ("upgrade-piercing-weapon", _PIERCING_WEAPON_UPGRADE_BOOT_KEY),
        ("upgrade-piercing-weapon", _PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY),
    ):
        if execution != owner and key in previous:
            if (
                key in set(_MAINTENANCE_ATTEMPT_LEVEL_KEYS.values())
                and key in current
            ):
                # Reconciliation can rebuild a checkpoint from an older
                # failed segment. Never age a newer same-level maintenance
                # attempt back to the level stored in that old segment.
                try:
                    merged[key] = max(int(previous[key]), int(current[key]))
                except (TypeError, ValueError):
                    merged[key] = current[key]
            else:
                merged[key] = previous[key]
    if _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY in previous:
        merged[_INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = previous[
            _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY
        ]
    return _apply_flight_funding_state_transition(
        previous,
        merged,
        execution=execution,
        funding_completed=False,
    )


def _apply_flight_funding_state_transition(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    execution: str,
    funding_completed: bool,
) -> dict[str, Any]:
    """Advance the bounded flight-funding loop without mixing it with XP."""
    transitioned = dict(current)
    if execution == "provision-funding":
        if previous.get(_FLIGHT_FUNDING_REQUIRED_KEY) and funding_completed:
            transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
            transitioned[_FLIGHT_FUNDING_RETRY_KEY] = True
        return transitioned
    if execution not in {
        "buy-flight",
        "buy-flight-potion",
        "buy-optional-flight",
    }:
        return transitioned

    active_flight = any(
        _state_has_active_affect(transitioned.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    if transitioned.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY) and not active_flight:
        # The shop was not reached, so this is neither a successful purchase
        # nor evidence that more money is needed. Preserve the existing funding
        # objective and rotate through productive work before another live
        # preflight of mobile 3064's current location.
        for key in (_FLIGHT_FUNDING_REQUIRED_KEY, _FLIGHT_FUNDING_RETRY_KEY):
            if previous.get(key) and key not in transitioned:
                transitioned[key] = previous[key]
        transitioned["magic_shop_purchase_failed"] = False
        transitioned[_FLIGHT_PURCHASE_COOLDOWN_KEY] = (
            _FLIGHT_PURCHASE_COOLDOWN_SEGMENTS
        )
        route_boot = transitioned.get("world_boot_id") or previous.get(
            "world_boot_id"
        )
        if route_boot:
            transitioned[_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY] = route_boot
        return transitioned

    transitioned.pop(_MAGIC_SHOP_ROUTE_BLOCKED_KEY, None)
    transitioned.pop(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY, None)

    if active_flight or transitioned.get("magic_shop_purchase_failed") is False:
        transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        transitioned.pop(_FLIGHT_FUNDING_RETRY_KEY, None)
        transitioned.pop(_FLIGHT_PURCHASE_COOLDOWN_KEY, None)
        transitioned.pop("campaign_fastwalk_abort_reason", None)
        if active_flight:
            transitioned = _clear_flight_blocked_research_evidence(transitioned)
    elif transitioned.get("magic_shop_purchase_failed") is True:
        transitioned.pop(_FLIGHT_FUNDING_RETRY_KEY, None)
        transitioned[_FLIGHT_PURCHASE_COOLDOWN_KEY] = (
            _FLIGHT_PURCHASE_COOLDOWN_SEGMENTS
        )
        if execution == "buy-optional-flight":
            transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        else:
            transitioned[_FLIGHT_FUNDING_REQUIRED_KEY] = True
    return transitioned


def _clear_flight_blocked_research_evidence(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Reopen same-reboot routes that failed only for missing flight."""
    if not any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    ):
        return state
    research_results = state.get("campaign_research_results")
    if not isinstance(research_results, dict):
        return state
    current_boot = state.get("world_boot_id")
    flight_blocked_policy_ids = {
        str(policy_id)
        for policy_id, result in research_results.items()
        if isinstance(result, Mapping)
        and result.get("boot_id") == current_boot
        and isinstance(result.get("route_hazard"), str)
        and result["route_hazard"].startswith(_FLIGHT_ROUTE_ABORT_PREFIXES)
    }
    if not flight_blocked_policy_ids:
        return state
    repaired = dict(state)
    remaining_results = {
        policy_id: result
        for policy_id, result in research_results.items()
        if str(policy_id) not in flight_blocked_policy_ids
    }
    if remaining_results:
        repaired["campaign_research_results"] = remaining_results
    else:
        repaired.pop("campaign_research_results", None)
    cooldowns = dict(repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for policy_id in flight_blocked_policy_ids:
        cooldowns.pop(policy_id, None)
    if cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared = {
        str(policy_id)
        for policy_id in repaired.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        if str(policy_id) not in flight_blocked_policy_ids
    }
    if cleared:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return repaired


def _campaign_has_item(state: dict[str, Any], item_name: str) -> bool:
    """Check carried, worn, and newly acquired state for a named item."""
    target = normalize_item_name(item_name)
    descriptions = [
        *_inventory_descriptions(state.get("inventory")),
        *(
            str(description)
            for description in state.get("campaign_worn_equipment") or ()
        ),
        *(
            str(item.get("item", ""))
            for item in state.get("acquired_items") or ()
            if isinstance(item, dict)
        ),
    ]
    return any(
        target in normalize_item_name(description)
        for description in descriptions
    )


def _prioritize_sack_vault_claims(items: Any) -> tuple[str, ...]:
    """Reclaim combat-value gear before heavier fallback armour."""
    if not isinstance(items, (list, tuple)):
        return ()
    priority = {
        keyword: index
        for index, keyword in enumerate(
            ("collar", "bracer", "belt", "sleeves", "vest", "guards", "cape")
        )
    }
    unique = tuple(dict.fromkeys(str(item).casefold() for item in items))
    return tuple(
        sorted(unique, key=lambda item: (priority.get(item, len(priority)), item))
    )


def _campaign_research_results(state: dict[str, Any]) -> dict[str, dict[str, Any]]:
    raw_results = state.get("campaign_research_results")
    if not isinstance(raw_results, dict):
        return {}
    return {
        str(policy_id): dict(result)
        for policy_id, result in raw_results.items()
        if isinstance(result, dict)
    }


def _repair_research_absence_cooldowns(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Drop absence cooldowns whose reboot-scoped evidence no longer exists."""
    raw_cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
    if not isinstance(raw_cooldowns, Mapping):
        return dict(state)
    results = _campaign_research_results(dict(state))
    boot_id = state.get("world_boot_id")
    retained: dict[str, int] = {}
    for raw_policy_id, raw_remaining in raw_cooldowns.items():
        policy_id = str(raw_policy_id)
        try:
            remaining = int(raw_remaining)
        except (TypeError, ValueError):
            continue
        result = results.get(policy_id)
        if (
            remaining <= 0
            or not isinstance(result, dict)
            or result.get("boot_id") != boot_id
            or not (
                result.get("absent") is True
                or result.get("route_hazard")
                == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
                or _is_retryable_source_ranked_route_hazard(
                    policy_id,
                    result.get("route_hazard"),
                )
                or result.get("retryable_failure") is True
            )
        ):
            continue
        retained[policy_id] = remaining
    original = dict(raw_cooldowns)
    if retained == original:
        return dict(state)
    repaired = dict(state)
    if retained:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = retained
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    return repaired


def _repair_protection_recovery_metadata(
    state: Mapping[str, Any],
    segments: list[Any],
    *,
    storage: RunStorage | None = None,
) -> dict[str, Any]:
    """Recover a current-reboot protection need from recorded hunt evidence."""
    updated = dict(state)
    existing_marker = updated.get(_PROTECTION_RECOVERY_KEY)
    boot_id = updated.get("world_boot_id")
    if (
        boot_id is not None
        and isinstance(existing_marker, Mapping)
        and existing_marker.get("boot_id") is not None
        and existing_marker.get("boot_id") != boot_id
    ):
        # Protection evidence is reboot-scoped; never carry an old-world
        # marker into a new live world.
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
        existing_marker = None
    existing_hard_health_marker = bool(
        isinstance(existing_marker, Mapping)
        and existing_marker.get("trigger")
        == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
    )
    has_sanctuary_reserve = _state_has_sanctuary_reserve(updated)
    if has_sanctuary_reserve and not existing_hard_health_marker:
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
    if boot_id is None:
        return updated

    def hunt_evidence(segment: Mapping[str, Any]) -> tuple[
        str, Mapping[str, Any], list[Any] | None, int, bool
    ] | None:
        if segment.get("status") not in {"success", "ready"}:
            return None
        phase = str(segment.get("phase") or "")
        if "-hunt-" not in phase:
            return None
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            return None
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            return None
        if not end or end.get("world_boot_id") != boot_id:
            return None
        outcomes = end.get("campaign_fastwalk_consider_outcomes")
        objective_kills = _segment_objective_kills(storage, segment)
        xp_delta = _xp_delta(start, end)
        has_viable_consider = (
            isinstance(outcomes, Mapping)
            and any(value is True for value in outcomes.values())
        )
        source_ranked_xp_loss = (
            phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and not objective_kills
            and xp_delta < 0
        )
        if not (
            has_viable_consider
            or source_ranked_xp_loss
            or bool(objective_kills)
        ):
            return None
        return (
            phase,
            end,
            objective_kills,
            xp_delta,
            _hard_health_floor_withdrawal(end),
        )

    def is_positive_kill(
        evidence: tuple[
            str, Mapping[str, Any], list[Any] | None, int, bool
        ] | None,
    ) -> bool:
        if evidence is None:
            return False
        _phase, _end, objective_kills, xp_delta, _hard_health = evidence
        return (
            isinstance(objective_kills, (list, tuple))
            and bool(objective_kills)
            and xp_delta > 0
        )

    normalized_segments: list[Mapping[str, Any]] = []
    for segment in segments:
        if isinstance(segment, Mapping):
            normalized_segments.append(segment)
            continue
        try:
            normalized_segments.append(
                {key: segment[key] for key in segment.keys()}
            )
        except (AttributeError, KeyError, TypeError):
            continue
    evidence = [hunt_evidence(segment) for segment in normalized_segments]
    replayed_loss_counts: Counter[str] = Counter()
    for segment, item in zip(normalized_segments, evidence):
        if item is None:
            continue
        phase, end, objective_kills, xp_delta, _hard_health = item
        if (
            phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and not objective_kills
            and xp_delta < 0
        ):
            replayed_loss_counts[phase] += 1
            updated = _remember_source_ranked_xp_loss(
                updated,
                policy_id=phase,
                level=_level(end),
                boot_id=end.get("world_boot_id"),
                xp_delta=xp_delta,
                observed_loss_count=replayed_loss_counts[phase],
                loss_event_id=segment.get("id"),
            )
    positive_source_policies: set[str] = set()
    for item in evidence:
        if item is None or not is_positive_kill(item):
            continue
        phase, _end, objective_kills, _objective_delta, _hard_health = item
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        tagged_policies = _source_ranked_kill_policy_ids(objective_kills)
        positive_source_policies.update(tagged_policies or (phase,))
    if positive_source_policies:
        # A later positive objective result is authoritative over an older
        # same-reboot loss when startup reconstructs the loss ledger.
        updated = _clear_source_ranked_xp_loss(
            updated,
            policy_ids=positive_source_policies,
        )
    existing = updated.get(_PROTECTION_RECOVERY_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
    ):
        # A checkpoint can predate the positive kill that cleared this gate.
        # Repair that persisted state before the marker can steer a new run.
        policy_id = str(existing.get("policy_id") or "")
        hard_health_marker = (
            existing.get("trigger")
            == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        )
        failure_indexes = [
            index
            for index, item in enumerate(evidence)
            if (
                item is not None
                and item[0] == policy_id
                and not is_positive_kill(item)
                and (item[3] < 0 or item[4])
            )
        ]
        if failure_indexes:
            failure_index = failure_indexes[-1]
            if any(
                is_positive_kill(item)
                and (not hard_health_marker or item[0] == policy_id)
                for item in evidence[failure_index + 1 :]
            ):
                updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    for index in range(len(evidence) - 1, -1, -1):
        item = evidence[index]
        if item is None:
            continue
        phase, end, objective_kills, xp_delta, hard_health = item
        if isinstance(objective_kills, (list, tuple)) and objective_kills:
            continue
        if not hard_health and xp_delta >= 0:
            continue
        if not hard_health and has_sanctuary_reserve:
            continue
        if any(
            is_positive_kill(later)
            and (not hard_health or later[0] == phase)
            for later in evidence[index + 1 :]
        ):
            return updated
        marker = {
            "boot_id": boot_id,
            "level": _level(end),
            "policy_id": phase,
            "xp_delta": xp_delta,
            "reason": (
                "recorded viable hunt reached the hard health floor before a kill"
                if hard_health
                else "recorded viable hunt withdrew with an XP loss before a kill"
            ),
        }
        if hard_health:
            marker["trigger"] = _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        updated[_PROTECTION_RECOVERY_KEY] = marker
        return updated
    return updated


def _remember_last_productive_policy(
    state: dict[str, Any],
    *,
    policy_xp_deltas: Mapping[str, int],
) -> dict[str, Any]:
    """Keep a current-reboot hunt available after an absent research probe."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    productive_history = _state_productive_policy_ids(state)
    history_is_present = isinstance(
        state.get(_PRODUCTIVE_POLICY_HISTORY_KEY),
        Mapping,
    )

    def is_productive(policy_id: str) -> bool:
        result = results.get(policy_id)
        if (
            history_is_present
            and policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and "-hunt-" in policy_id
            and policy_id not in productive_history
        ):
            return False
        if isinstance(result, dict) and "max_objective_kill_xp" in result:
            try:
                if int(result.get("max_objective_kill_xp") or 0) < (
                    _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
                ):
                    return False
            except (TypeError, ValueError):
                return False
        return bool(
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
            and result.get("observed") is True
            and result.get("viable") is True
            and result.get("completed_kill") is True
            and "-hunt" in str(policy_id)
        )

    existing = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    if isinstance(existing, str) and is_productive(existing):
        return state
    candidates = [
        str(policy_id)
        for policy_id, delta in policy_xp_deltas.items()
        if int(delta or 0) >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        and is_productive(str(policy_id))
    ]
    if not candidates:
        return state
    selected = max(
        candidates,
        key=lambda policy_id: (
            int(policy_xp_deltas.get(policy_id, 0) or 0),
            policy_id,
        ),
    )
    if existing == selected:
        return state
    remembered = dict(state)
    remembered[_LAST_PRODUCTIVE_POLICY_KEY] = selected
    return remembered


def _historical_productive_handoff_policy_id(
    state: Mapping[str, Any],
    *,
    current_group: frozenset[str],
) -> str | None:
    """Find a previously productive hunt whose current miss is retryable."""
    history = state.get(_PRODUCTIVE_POLICY_HISTORY_KEY)
    boot_id = state.get("world_boot_id")
    if not isinstance(history, Mapping) or history.get("boot_id") != boot_id:
        return None
    policy_ids = history.get("policy_ids")
    if not isinstance(policy_ids, (list, tuple, set, frozenset)):
        return None
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    results = _campaign_research_results(dict(state))
    candidates: list[str] = []
    for raw_policy_id in policy_ids:
        policy_id = str(raw_policy_id)
        if "-hunt-" not in policy_id or policy_id in current_group:
            continue
        probe_id = policy_id.replace("-hunt-", "-probe-", 1)
        if any(
            int(cooldowns.get(candidate_id) or 0) > 0
            for candidate_id in (policy_id, probe_id)
        ):
            continue
        hunt_result = results.get(policy_id)
        probe_result = results.get(probe_id)
        blocked = False
        for result, is_hunt in (
            (hunt_result, True),
            (probe_result, False),
        ):
            if not isinstance(result, dict) or result.get("boot_id") != boot_id:
                continue
            if result.get("absent") is True or result.get("unobserved") is True:
                continue
            if is_hunt and result.get("completed_kill") is False:
                blocked = True
                break
            if result.get("observed") is True and result.get("viable") is True:
                continue
            blocked = True
            break
        if not blocked:
            candidates.append(policy_id)
    return sorted(candidates)[0] if candidates else None


def _repair_sanctuary_resource_acquisition_history(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Restore successful sanctuary acquisitions misread as XP probes."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)

    latest_by_policy: dict[str, Mapping[str, Any]] = {}
    for segment in segments:
        phase = str(segment.get("phase") or "")
        if phase in _SANCTUARY_RESOURCE_POLICY_IDS:
            latest_by_policy[phase] = segment

    repaired = dict(state)
    results = _campaign_research_results(repaired)
    absence_cooldowns = dict(
        repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(repaired.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    changed = False
    for policy_id, segment in latest_by_policy.items():
        if str(segment.get("status") or "") != "success":
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        if end.get("campaign_died_during_segment"):
            continue
        if _verified_combat_potion_count(
            end, "purple"
        ) <= _verified_combat_potion_count(start, "purple"):
            continue

        restored_result = {
            "observed": True,
            "viable": True,
            "completed_kill": False,
            "required_object_acquired": True,
            "required_object_vnums": [4050],
            "boot_id": boot_id,
        }
        if results.get(policy_id) != restored_result:
            results[policy_id] = restored_result
            changed = True
        if policy_id in absence_cooldowns:
            absence_cooldowns.pop(policy_id, None)
            changed = True
        if policy_id in crowd_cooldowns:
            crowd_cooldowns.pop(policy_id, None)
            changed = True

    if not changed:
        return repaired
    repaired["campaign_research_results"] = results
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        repaired.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    return repaired


def _verified_combat_potion_count(
    state: Mapping[str, Any],
    keyword: str,
) -> int:
    """Return one source-verified pouch count without trusting inventory text."""
    counts = state.get("verified_combat_pouch_potions") or {}
    if not isinstance(counts, Mapping):
        return 0
    try:
        return max(0, int(counts.get(keyword) or 0))
    except (TypeError, ValueError):
        return 0


def _state_has_sanctuary_reserve(state: Mapping[str, Any]) -> bool:
    """Return whether sanctuary is active or a usable potion is carried."""
    if _has_named_affect(state.get("affects"), "sanctuary"):
        return True
    if _state_has_item(state.get("inventory"), "purple potion"):
        return True
    try:
        return int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        ) > 0
    except (TypeError, ValueError):
        return False


def _state_needs_combat_pouch_repack(state: Mapping[str, Any]) -> bool:
    """Detect a source-safe loose purple potion after a field abort."""
    if not _state_has_item(state.get("inventory"), "purple potion"):
        return False
    if _verified_combat_potion_count(state, "purple") > 0:
        return False
    try:
        if int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        ) > 0:
            return False
    except (TypeError, ValueError):
        return False
    marker = state.get(_PROTECTION_RECOVERY_KEY)
    current_boot_marker = (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
    )
    return bool(
        current_boot_marker
        or state.get("campaign_acquired_sanctuary_potion")
    )


def _state_has_blindness_recovery_reserve(
    state: Mapping[str, Any],
    *,
    required_purple_count: int = 2,
) -> bool:
    """Return whether the required source-verified blindness cure is carried."""
    if required_purple_count < 1:
        raise ValueError("required_purple_count must be positive")
    if state.get("campaign_cure_blindness_available") is True:
        return True
    known_skills = state.get("campaign_known_skills") or ()
    if isinstance(known_skills, str):
        known_skills = (known_skills,)
    if any(str(skill).casefold() == "cure blindness" for skill in known_skills):
        return True

    # DD4's verified purple potion is the currently source-identified
    # blindness cure. Count inventory entries as well as pouch entries because
    # the runner may not have stowed a newly acquired potion yet. Caster
    # specials request two copies because one is spent on sanctuary first;
    # non-sanctuary status routes need only the cure itself.
    potion_counts = dict(state.get("verified_combat_pouch_potions") or {})
    if not potion_counts:
        potion_counts = dict(state.get("combat_pouch_potions") or {})
    purple_count = 0
    try:
        purple_count = int(potion_counts.get("purple") or 0)
    except (TypeError, ValueError):
        purple_count = 0
    purple_count += sum(
        1
        for description in _inventory_descriptions(state.get("inventory"))
        if "purple potion" in description.casefold()
    )
    return purple_count >= required_purple_count


def _hard_health_floor_withdrawal(state: Mapping[str, Any]) -> bool:
    """Return whether a field fight ended at its explicit hard HP floor."""
    return str(state.get("campaign_fastwalk_abort_reason") or "").startswith(
        _HARD_HEALTH_ABORT_PREFIX
    )


def _protection_recovery_required(state: Mapping[str, Any]) -> bool:
    """Return whether a current-reboot hunt needs a protection upgrade."""
    record = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("boot_id") != state.get("world_boot_id"):
        return False
    return not _state_has_sanctuary_reserve(state)


def _negative_fame_cure_critical_reserve_waiting(
    state: Mapping[str, Any],
) -> bool:
    """Return whether fame recovery is waiting for its blocked reserve route."""
    fame = _state_fame(state)
    if fame is None or fame >= 0:
        return False
    verified_pouch = dict(state.get("verified_combat_pouch_potions") or {})
    if (
        _verified_combat_potion_keyword_for_spell(
            verified_pouch,
            None,
            "cure critical",
        )
        is not None
    ):
        return False
    return _research_retry_cooldown_active(
        state,
        _SOURCE_RANKED_CURE_CRITICAL_RESERVE_POLICY.policy_id,
    )


def _campaign_sanctuary_recovery_required(state: dict[str, Any]) -> bool:
    """Return whether a current-reboot protected hunt still needs a reserve."""
    if _protection_recovery_required(state):
        return True
    boot_id = state.get("world_boot_id")
    results = _campaign_research_results(state)
    for policy_id in (
        _SHIRE_ELVEN_WIZARD_HUNT_POLICY_ID,
        _HIGHTOWER_JAILOR_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_SANCTUARY_HUNT_POLICY_ID,
    ):
        result = results.get(policy_id)
        if (
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
            and result.get("completed_kill") is False
        ):
            return True
    return False


def _campaign_productive_sanctuary_handoff(
    state: dict[str, Any],
    *,
    character_class: str,
) -> str | None:
    """Keep a productive hunt running while a required Moria pass is crowded."""
    if character_class.casefold() != "thief" or _level(state) < 17:
        return None
    if (
        int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        )
        > 0
        or _state_has_item(state.get("inventory"), "purple potion")
    ):
        return None
    if not _campaign_sanctuary_recovery_required(state):
        return None
    policy_id = _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
    result = _campaign_research_results(state).get(policy_id)
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    if not (
        isinstance(result, dict)
        and result.get("crowded") is True
        and result.get("boot_id") == state.get("world_boot_id")
        and isinstance(cooldowns, dict)
    ):
        return None
    try:
        if int(cooldowns.get(policy_id) or 0) <= 0:
            return None
    except (TypeError, ValueError):
        return None
    productive_policy_id = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    productive_result = (
        _campaign_research_results(state).get(productive_policy_id)
        if isinstance(productive_policy_id, str)
        else None
    )
    if not (
        isinstance(productive_policy_id, str)
        and "-hunt" in productive_policy_id
        and isinstance(productive_result, dict)
        and productive_result.get("boot_id") == state.get("world_boot_id")
        and productive_result.get("observed") is True
        and (
            (
                productive_result.get("viable") is True
                and productive_result.get("completed_kill") is not False
            )
            or (
                state.get(_LAST_PRODUCTIVE_POLICY_KEY) == productive_policy_id
                and productive_result.get("completed_kill") is False
            )
        )
    ):
        return None
    if productive_policy_id in {
        _SHIRE_ELVEN_WIZARD_HUNT_POLICY_ID,
        _HIGHTOWER_JAILOR_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_SANCTUARY_HUNT_POLICY_ID,
    }:
        # A crowd checkpoint must never bypass the progression safety gate
        # for a caster hunt that requires a currently carried potion.
        return None
    return productive_policy_id


def _campaign_below_band_policy_ids(
    state: dict[str, Any],
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[str]:
    """Return policies rejected by live consider at this level and reboot."""
    raw = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw, dict):
        return frozenset()
    return frozenset(
        str(policy_id)
        for policy_id, record in raw.items()
        if isinstance(record, dict)
        and record.get("level") == level
        and record.get("boot_id") == boot_id
    )


def _source_mobile_key(value: Any) -> str | None:
    """Return the stable mobile-namespace identity for a candidate record."""
    if isinstance(value, HuntCandidate):
        mobile_vnum = value.mobile_vnum
    elif isinstance(value, Mapping):
        mobile_vnum = value.get("mobile_vnum")
    else:
        return None
    try:
        mobile_vnum = int(mobile_vnum or 0)
    except (TypeError, ValueError):
        return None
    if mobile_vnum <= 0:
        return None
    return f"mobile:{mobile_vnum}"


def _campaign_below_band_source_mobile_keys(
    state: Mapping[str, Any],
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[str]:
    """Return source mobile identities rejected by live consider."""
    raw = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw, Mapping):
        return frozenset()
    keys: set[str] = set()
    for policy_id, record in raw.items():
        if (
            not isinstance(record, Mapping)
            or record.get("level") != level
            or record.get("boot_id") != boot_id
        ):
            continue
        source_keys = record.get("source_mobile_keys")
        if isinstance(source_keys, (list, tuple, set, frozenset)):
            keys.update(str(key) for key in source_keys if str(key))
        if not source_keys and str(policy_id).startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            # Older checkpoints keyed source exclusions by reset policy only.
            # The source-ranked policy format ends with mobile, room, level;
            # recover the mobile VNUM so those checkpoints cannot replay a
            # sibling reset before the next level or reboot.
            match = re.search(r"-(\d+)-\d+-\d+$", str(policy_id))
            if match:
                keys.add(f"mobile:{match.group(1)}")
    return frozenset(keys)


def _source_ranked_candidate_excluded_by_below_band_evidence(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    key = _source_mobile_key(candidate)
    return bool(
        key
        and key
        in _campaign_below_band_source_mobile_keys(
            state,
            level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _below_band_sighting_pairs(value: Any) -> set[tuple[str, str]]:
    if not isinstance(value, (list, tuple, set)):
        return set()
    pairs: set[tuple[str, str]] = set()
    for sighting in value:
        if not isinstance(sighting, dict):
            continue
        room_vnum = sighting.get("room_vnum")
        target = sighting.get("target")
        if room_vnum is None or target is None:
            continue
        room = str(room_vnum).strip()
        target_name = str(target).strip().casefold()
        if room and target_name:
            pairs.add((room, target_name))
    return pairs


def _campaign_below_band_sightings(
    state: dict[str, Any],
    policy_id: str,
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[tuple[str, str]]:
    raw = state.get(_BELOW_BAND_SIGHTINGS_KEY)
    if not isinstance(raw, dict):
        return frozenset()
    record = raw.get(policy_id)
    if (
        not isinstance(record, dict)
        or record.get("level") != level
        or record.get("boot_id") != boot_id
    ):
        return frozenset()
    return frozenset(_below_band_sighting_pairs(record.get("sightings")))


def _source_ranked_circuit_policy_records(
    candidate_record: object,
    *,
    primary_policy_id: str,
) -> tuple[Mapping[str, Any], ...]:
    """Return the serialized source candidates dispatched in one circuit."""
    if not isinstance(candidate_record, Mapping):
        return ()
    raw_circuit = candidate_record.get("circuit")
    circuit_records = (
        tuple(raw_circuit)
        if isinstance(raw_circuit, (list, tuple))
        else ()
    )
    records: list[Mapping[str, Any]] = []
    for raw_record in (
        candidate_record,
        *circuit_records,
    ):
        if not isinstance(raw_record, Mapping):
            continue
        policy_id = str(raw_record.get("policy_id") or "")
        if not policy_id and raw_record is candidate_record:
            policy_id = primary_policy_id
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if any(
            str(record.get("policy_id") or primary_policy_id) == policy_id
            for record in records
        ):
            continue
        if raw_record.get("policy_id") == policy_id:
            records.append(raw_record)
        else:
            records.append({**raw_record, "policy_id": policy_id})
    return tuple(records)


def _source_ranked_normalized_target(value: object) -> str:
    """Normalize only grammatical articles around a source mobile identity."""
    normalized = normalize_item_name(str(value or "")).strip(" .")
    return re.sub(r"^(?:a|an|the)\s+", "", normalized)


def _source_ranked_policy_id_for_target(
    candidate_record: object,
    target: object,
    *,
    primary_policy_id: str,
) -> str | None:
    """Resolve a live identity to one unambiguous serialized source policy."""
    observed = _source_ranked_normalized_target(target)
    if not observed:
        return None
    matches: list[str] = []
    for record in _source_ranked_circuit_policy_records(
        candidate_record,
        primary_policy_id=primary_policy_id,
    ):
        identities = {
            _source_ranked_normalized_target(record.get("target_identity")),
            _source_ranked_normalized_target(record.get("target")),
        } - {""}
        if observed not in identities:
            continue
        policy_id = str(record.get("policy_id") or "")
        if policy_id not in matches:
            matches.append(policy_id)
    return matches[0] if len(matches) == 1 else None


def _source_ranked_consider_outcomes_by_policy(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> dict[str, bool]:
    """Prefer runner-recorded stop IDs, with identity fallback for old runs."""
    records = _source_ranked_circuit_policy_records(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    valid_policy_ids = {
        str(record.get("policy_id") or "") for record in records
    }
    direct = state.get(_SOURCE_CONSIDER_OUTCOMES_KEY)
    if isinstance(direct, Mapping):
        resolved = {
            str(policy_id): outcome
            for policy_id, outcome in direct.items()
            if str(policy_id) in valid_policy_ids
            and isinstance(outcome, bool)
        }
        if resolved:
            return resolved

    resolved: dict[str, bool] = {}
    outcomes = state.get("campaign_fastwalk_consider_outcomes")
    if not isinstance(outcomes, Mapping):
        return resolved
    for target, outcome in outcomes.items():
        if not isinstance(outcome, bool):
            continue
        policy_id = _source_ranked_policy_id_for_target(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            target,
            primary_policy_id=primary_policy_id,
        )
        if policy_id is not None:
            resolved[policy_id] = bool(outcome or resolved.get(policy_id))
    return resolved


def _source_ranked_below_band_sightings_by_policy(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> dict[str, set[tuple[str, str]]]:
    """Attribute below-band sightings to the exact source circuit stop."""
    records = _source_ranked_circuit_policy_records(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    valid_policy_ids = {
        str(record.get("policy_id") or "") for record in records
    }
    resolved: dict[str, set[tuple[str, str]]] = {}
    direct = state.get(_SOURCE_BELOW_BAND_SIGHTINGS_KEY)
    if isinstance(direct, (list, tuple)):
        for sighting in direct:
            if not isinstance(sighting, Mapping):
                continue
            policy_id = str(sighting.get("policy_id") or "")
            room_vnum = str(sighting.get("room_vnum") or "")
            target = str(sighting.get("target") or "").casefold()
            if policy_id in valid_policy_ids and room_vnum and target:
                resolved.setdefault(policy_id, set()).add(
                    (room_vnum, target)
                )
        if resolved:
            return resolved

    for room_vnum, target in _below_band_sighting_pairs(
        state.get("campaign_fastwalk_below_band_sightings")
    ):
        policy_id = _source_ranked_policy_id_for_target(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            target,
            primary_policy_id=primary_policy_id,
        )
        if policy_id is not None:
            resolved.setdefault(policy_id, set()).add(
                (room_vnum, target)
            )
    return resolved


def _source_ranked_absent_policy_ids(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Resolve runner-recorded reset misses to exact circuit policies."""
    valid_policy_ids = set(
        _source_ranked_circuit_policy_ids(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=primary_policy_id,
        )
    )
    direct = state.get(_SOURCE_ABSENT_SIGHTINGS_KEY)
    if not isinstance(direct, (list, tuple)):
        return ()
    return tuple(
        dict.fromkeys(
            str(sighting.get("policy_id") or "")
            for sighting in direct
            if isinstance(sighting, Mapping)
            and str(sighting.get("policy_id") or "") in valid_policy_ids
        )
    )


def _source_ranked_present_policy_ids(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Resolve runner-recorded live sightings to exact circuit policies."""
    valid_policy_ids = set(
        _source_ranked_circuit_policy_ids(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=primary_policy_id,
        )
    )
    direct = state.get(_SOURCE_PRESENT_SIGHTINGS_KEY)
    if not isinstance(direct, (list, tuple)):
        return ()
    return tuple(
        dict.fromkeys(
            str(sighting.get("policy_id") or "")
            for sighting in direct
            if isinstance(sighting, Mapping)
            and str(sighting.get("policy_id") or "") in valid_policy_ids
        )
    )


def _merge_campaign_below_band_policy_exclusions(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
    level: int,
    boot_id: str | int | None,
) -> dict[str, Any]:
    """Persist live below-band rejections until level or reboot changes."""
    merged = dict(current)
    raw = previous.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    exclusions = {
        str(policy_id): dict(record)
        for policy_id, record in (raw.items() if isinstance(raw, dict) else ())
        if isinstance(record, dict)
        and record.get("level") == level
        and record.get("boot_id") == boot_id
    }
    previous_sightings = previous.get(_BELOW_BAND_SIGHTINGS_KEY)
    sightings_by_policy: dict[str, set[tuple[str, str]]] = {}
    if isinstance(previous_sightings, dict):
        for policy_id, record in previous_sightings.items():
            if (
                isinstance(record, dict)
                and record.get("level") == level
                and record.get("boot_id") == boot_id
            ):
                pairs = _below_band_sighting_pairs(record.get("sightings"))
                if pairs:
                    sightings_by_policy[str(policy_id)] = pairs
    current_sightings = _below_band_sighting_pairs(
        current.get("campaign_fastwalk_below_band_sightings")
    )
    candidate_record = current.get(_SOURCE_RANKED_CANDIDATE_KEY)
    source_ranked_dispatch = bool(
        policy.execution == "source-ranked-hunt"
        and isinstance(candidate_record, Mapping)
        and candidate_record.get("policy_id") == policy.policy_id
    )
    source_sightings = (
        _source_ranked_below_band_sightings_by_policy(
            current,
            primary_policy_id=policy.policy_id,
        )
        if source_ranked_dispatch
        else {}
    )
    for source_policy_id, pairs in source_sightings.items():
        sightings_by_policy.setdefault(source_policy_id, set()).update(pairs)
    if current_sightings and not source_sightings:
        sightings_by_policy.setdefault(policy.policy_id, set()).update(
            current_sightings
        )

    targets = current.get("campaign_fastwalk_below_band_targets")
    raw_targets = (
        [str(target).casefold() for target in targets]
        if isinstance(targets, (list, tuple, set))
        else []
    )
    targets_by_policy: dict[str, set[str]] = {
        source_policy_id: {target for _, target in pairs}
        for source_policy_id, pairs in source_sightings.items()
    }
    for target in raw_targets:
        source_policy_id = (
            _source_ranked_policy_id_for_target(
                candidate_record,
                target,
                primary_policy_id=policy.policy_id,
            )
            if source_ranked_dispatch
            else None
        )
        targets_by_policy.setdefault(
            source_policy_id or policy.policy_id,
            set(),
        ).add(target)

    candidate_records = {
        str(record.get("policy_id") or ""): record
        for record in _source_ranked_circuit_policy_records(
            candidate_record,
            primary_policy_id=policy.policy_id,
        )
    }

    if policy.allow_partial_below_band:
        outcomes = current.get("campaign_fastwalk_consider_outcomes")
        has_viable_stop = isinstance(outcomes, dict) and any(
            value is True for value in outcomes.values()
        )
        below_band_evidence = (
            raw_targets
            if raw_targets
            else [target for _, target in current_sightings]
        )
        if below_band_evidence and not has_viable_stop:
            # A multi-stop hunt may tolerate one below-band mobile only when
            # another stop remains inside the useful XP band.
            record = dict(exclusions.get(policy.policy_id) or {})
            record.update({
                "level": level,
                "boot_id": boot_id,
                "targets": sorted(
                    {str(target).casefold() for target in below_band_evidence}
                ),
            })
            current_record = candidate_records.get(policy.policy_id)
            if current_record is not None:
                source_keys = {
                    str(key)
                    for key in record.get("source_mobile_keys") or ()
                }
                source_keys.add(_source_mobile_key(current_record))
                record["source_mobile_keys"] = sorted(source_keys)
            exclusions[policy.policy_id] = record
        else:
            exclusions.pop(policy.policy_id, None)
    else:
        for source_policy_id, source_targets in targets_by_policy.items():
            if not source_targets:
                continue
            record = dict(exclusions.get(source_policy_id) or {})
            retained_targets = {
                str(target).casefold()
                for target in record.get("targets") or ()
            }
            retained_targets.update(source_targets)
            record.update({
                "level": level,
                "boot_id": boot_id,
                "targets": sorted(retained_targets),
            })
            current_record = candidate_records.get(source_policy_id)
            if current_record is not None:
                source_keys = {
                    str(key)
                    for key in record.get("source_mobile_keys") or ()
                }
                source_keys.add(_source_mobile_key(current_record))
                record["source_mobile_keys"] = sorted(source_keys)
            exclusions[source_policy_id] = record
    if exclusions:
        merged[_BELOW_BAND_POLICY_EXCLUSIONS_KEY] = exclusions
    else:
        merged.pop(_BELOW_BAND_POLICY_EXCLUSIONS_KEY, None)
    if sightings_by_policy:
        merged[_BELOW_BAND_SIGHTINGS_KEY] = {
            policy_id: {
                "level": level,
                "boot_id": boot_id,
                "sightings": [
                    {"room_vnum": room_vnum, "target": target}
                    for room_vnum, target in sorted(pairs)
                ],
            }
            for policy_id, pairs in sorted(sightings_by_policy.items())
        }
    else:
        merged.pop(_BELOW_BAND_SIGHTINGS_KEY, None)
    return merged


def _merge_protection_recovery_metadata(
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
    xp_delta: int,
    loss_event_id: Any = None,
) -> dict[str, Any]:
    """Remember a costly failed hunt until progress restores its gate."""
    updated = dict(current)
    existing = updated.get(_PROTECTION_RECOVERY_KEY)
    existing_hard_health_marker = bool(
        isinstance(existing, Mapping)
        and existing.get("trigger")
        == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
    )
    objective_kills = updated.get("campaign_objective_kills")
    positive_objective_kill = bool(
        xp_delta > 0
        and isinstance(objective_kills, (list, tuple))
        and objective_kills
    )
    source_kill_policy_ids = (
        set(_source_ranked_kill_policy_ids(objective_kills))
        if positive_objective_kill
        else set()
    )
    if source_kill_policy_ids:
        updated = _clear_source_ranked_xp_loss(
            updated,
            policy_ids=source_kill_policy_ids,
        )
    same_policy_recovery = bool(
        positive_objective_kill
        and isinstance(existing, Mapping)
        and existing.get("policy_id") == policy.policy_id
    )
    if same_policy_recovery or (
        positive_objective_kill and not existing_hard_health_marker
    ):
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    execution = str(policy.execution or "")
    if (
        execution == "source-ranked-hunt"
        and not updated.get("campaign_objective_kills")
        and xp_delta < 0
    ):
        updated = _remember_source_ranked_xp_loss(
            updated,
            policy_id=policy.policy_id,
            level=_level(updated),
            boot_id=updated.get("world_boot_id"),
            xp_delta=xp_delta,
            loss_event_id=loss_event_id,
        )
    outcomes = updated.get("campaign_fastwalk_consider_outcomes")
    viable = isinstance(outcomes, Mapping) and any(
        value is True for value in outcomes.values()
    )
    hard_health_withdrawal = _hard_health_floor_withdrawal(updated)
    if (
        policy.status == "research"
        and execution.endswith("-hunt")
        and not updated.get("campaign_objective_kills")
        and viable
        and (xp_delta < 0 or hard_health_withdrawal)
        and updated.get("world_boot_id") is not None
    ):
        marker = {
            "boot_id": updated.get("world_boot_id"),
            "level": _level(updated),
            "policy_id": policy.policy_id,
            "xp_delta": xp_delta,
            "reason": (
                "viable hunt reached the hard health floor before a kill"
                if hard_health_withdrawal
                else "viable hunt withdrew with an XP loss before a kill"
            ),
        }
        if hard_health_withdrawal:
            marker["trigger"] = _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        updated[_PROTECTION_RECOVERY_KEY] = marker
        return updated
    if _state_has_sanctuary_reserve(updated):
        if not existing_hard_health_marker:
            updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    return updated


def _merge_campaign_research_result(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
) -> dict[str, Any]:
    """Persist one reboot-scoped live consideration for research promotion."""
    merged = dict(current)
    results = _campaign_research_results(previous)
    absence_cooldowns = dict(
        previous.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        previous.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    source_ranked_crowd_attempts = dict(
        previous.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in previous.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    recorded_current_result = False
    if policy.status == "research":
        outcomes = current.get("campaign_fastwalk_consider_outcomes")
        viable = None
        if isinstance(outcomes, dict):
            boolean_outcomes = [
                value for value in outcomes.values() if isinstance(value, bool)
            ]
            if boolean_outcomes:
                viable = any(boolean_outcomes)
        target_present_observed = bool(
            current.get("campaign_fastwalk_target_present_observed")
        )
        acquired_required_object_vnums: tuple[int, ...] = ()
        raw_acquired_required_object_vnums = current.get(
            "campaign_fastwalk_required_object_vnums"
        )
        if isinstance(
            raw_acquired_required_object_vnums,
            (list, tuple, set, frozenset),
        ):
            parsed_acquired_required_object_vnums: set[int] = set()
            for raw_vnum in raw_acquired_required_object_vnums:
                try:
                    parsed_acquired_required_object_vnums.add(int(raw_vnum))
                except (TypeError, ValueError):
                    continue
            acquired_required_object_vnums = tuple(
                sorted(parsed_acquired_required_object_vnums)
            )
        sanctuary_resource_acquisition = bool(
            policy.execution
            in {
                "moria-sanctuary-hunt",
                "moria-deep-sanctuary-hunt",
            }
            and _verified_combat_potion_count(current, "purple")
            > _verified_combat_potion_count(previous, "purple")
        )
        resource_acquisition = bool(
            (
                (
                    acquired_required_object_vnums
                    and policy.execution
                    in {
                        "source-ranked-food-reserve",
                        "source-ranked-cure-critical-reserve",
                    }
                )
                or sanctuary_resource_acquisition
            )
            and not current.get("campaign_died_during_segment")
        )
        fastwalk_abort_reason = str(
            current.get("campaign_fastwalk_abort_reason") or ""
        )
        hunt_without_confirmed_kill = bool(
            (
                str(policy.execution or "").endswith("-hunt")
                or policy.execution
                in {
                    "fame-recovery-circus",
                    "fame-recovery",
                    "fame-recovery-lotus",
                }
            )
            and not current.get("campaign_objective_kills")
        )
        unobserved_hunt = bool(
            hunt_without_confirmed_kill
            and viable is None
            and not current.get("campaign_fastwalk_consider_outcomes")
            and not target_present_observed
            and not current.get("campaign_fastwalk_target_absent")
            and not current.get("campaign_fastwalk_abort_reason")
            and not current.get("campaign_fastwalk_unattackable_target")
            and not current.get("campaign_fastwalk_target_vnum_mismatch")
        )
        unobserved_moria_deep_probe = bool(
            policy.policy_id == _MORIA_DEEP_SANCTUARY_THIEF_PROBE_POLICY_ID
            and viable is None
            and not current.get("campaign_fastwalk_consider_outcomes")
            and not target_present_observed
            and not current.get("campaign_fastwalk_target_absent")
            and not current.get("campaign_fastwalk_abort_reason")
            and not current.get("campaign_fastwalk_unattackable_target")
            and not current.get("campaign_fastwalk_target_vnum_mismatch")
        )
        unattackable_target = current.get(
            "campaign_fastwalk_unattackable_target"
        )
        target_vnum_mismatch = current.get(
            "campaign_fastwalk_target_vnum_mismatch"
        )
        crowded_field = bool(
            current.get("campaign_fastwalk_crowded")
            or any(
                fastwalk_abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        )
        route_hazard = any(
            fastwalk_abort_reason.startswith(prefix)
            for prefix in _FIELD_ROUTE_HAZARD_ABORT_PREFIXES
        )
        protection_required = (
            _FIELD_REQUIRED_SANCTUARY_ABORT_FRAGMENT in fastwalk_abort_reason
        )
        if resource_acquisition:
            # Required-object acquisition is positive evidence for resource
            # routes even when the generic fastwalk target flag was stale.
            merged["campaign_fastwalk_target_absent"] = False
            merged["campaign_fastwalk_target_present_observed"] = True
            results[policy.policy_id] = {
                "observed": True,
                "viable": True,
                "completed_kill": False,
                "required_object_acquired": True,
                "required_object_vnums": list(
                    acquired_required_object_vnums
                    or ((4050,) if sanctuary_resource_acquisition else ())
                ),
                "boot_id": current.get("world_boot_id"),
            }
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
            recorded_current_result = True
        elif route_hazard:
            result = {
                "observed": False,
                "viable": False,
                "route_hazard": fastwalk_abort_reason,
                "boot_id": current.get("world_boot_id"),
            }
            if (
                policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and _is_retryable_dynamic_route_hazard(
                    policy.policy_id,
                    fastwalk_abort_reason,
                )
            ):
                result["retryable_failure"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            if _is_retryable_dynamic_route_hazard(
                policy.policy_id,
                fastwalk_abort_reason,
            ):
                retry_cooldown = _research_absence_retry_cooldown(
                    policy.policy_id
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy.policy_id] = retry_cooldown
            else:
                absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
        elif crowded_field:
            previous_result = results.get(policy.policy_id)
            preserve_positive_result = (
                isinstance(previous_result, dict)
                and current.get("world_boot_id") is not None
                and previous_result.get("boot_id") == current.get("world_boot_id")
                and previous_result.get("viable") is True
                and previous_result.get("completed_kill") is not False
            )

            def record_source_ranked_crowd_attempt(
                result: dict[str, Any],
            ) -> None:
                if not policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                    return
                previous_attempt = source_ranked_crowd_attempts.get(
                    policy.policy_id
                )
                try:
                    attempt_count = (
                        int(previous_attempt.get("count") or 0)
                        if isinstance(previous_attempt, dict)
                        and previous_attempt.get("boot_id")
                        == current.get("world_boot_id")
                        else 0
                    )
                except (TypeError, ValueError):
                    attempt_count = 0
                if (
                    attempt_count == 0
                    and previous.get("campaign_fastwalk_crowded")
                    and previous.get("campaign_last_policy")
                    == policy.policy_id
                ):
                    # Checkpoints created before this counter existed
                    # already contain one crowd observation. Preserve it
                    # during the first post-upgrade merge.
                    attempt_count = _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD - 1
                attempt_count += 1
                source_ranked_crowd_attempts[policy.policy_id] = {
                    "boot_id": current.get("world_boot_id"),
                    "count": attempt_count,
                }
                if attempt_count >= _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD:
                    result["crowd_exhausted"] = True

            if not preserve_positive_result:
                results[policy.policy_id] = {
                    "observed": False,
                    "viable": False,
                    "crowded": True,
                    "boot_id": current.get("world_boot_id"),
                }
                record_source_ranked_crowd_attempt(
                    results[policy.policy_id]
                )
                crowd_cooldowns[policy.policy_id] = (
                    _DEFAULT_RESEARCH_CROWD_COOLDOWN
                )
                absence_cooldowns.pop(policy.policy_id, None)
            elif policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                preserved_result = dict(previous_result)
                # Keep the positive kill evidence for later same-reboot use,
                # but make the current crowd a temporary selection gate.
                preserved_result["crowded"] = True
                record_source_ranked_crowd_attempt(preserved_result)
                results[policy.policy_id] = preserved_result
                crowd_cooldowns[policy.policy_id] = (
                    _DEFAULT_RESEARCH_CROWD_COOLDOWN
                )
                absence_cooldowns.pop(policy.policy_id, None)
            else:
                absence_cooldowns.pop(policy.policy_id, None)
                crowd_cooldowns.pop(policy.policy_id, None)
                source_ranked_crowd_attempts.pop(policy.policy_id, None)
            recorded_current_result = True
        elif unattackable_target:
            results[policy.policy_id] = {
                "observed": viable is not None,
                "viable": False,
                "unattackable": str(unattackable_target),
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif target_vnum_mismatch:
            results[policy.policy_id] = {
                "observed": target_present_observed,
                "viable": False,
                "target_vnum_mismatch": target_vnum_mismatch,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        aborted_without_consider = bool(
            current.get("campaign_fastwalk_abort_reason")
            and viable is None
            and not current.get("campaign_fastwalk_target_absent")
        )
        source_ranked_route_abort = bool(
            policy.execution == "source-ranked-hunt"
            and aborted_without_consider
        )
        if resource_acquisition:
            pass
        elif (
            route_hazard
            or crowded_field
            or unattackable_target
            or target_vnum_mismatch
        ):
            pass
        elif source_ranked_route_abort:
            result = {
                "observed": False,
                "viable": False,
                "route_hazard": fastwalk_abort_reason,
                "boot_id": current.get("world_boot_id"),
            }
            if _is_retryable_dynamic_route_hazard(
                policy.policy_id,
                fastwalk_abort_reason,
            ):
                result["retryable_failure"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id,
                default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif aborted_without_consider:
            pass
        elif (
            current.get("campaign_fastwalk_target_absent")
            and viable is None
            and not target_present_observed
        ):
            results[policy.policy_id] = {
                "observed": False,
                "viable": False,
                "absent": True,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif unobserved_moria_deep_probe:
            # The deep sanctuary probe uses a research execution rather than
            # a ``-hunt`` execution, so it does not enter ``unobserved_hunt``.
            # Preserve an explicit absence record or policy revision cleanup
            # will erase the failed probe and immediately reopen it.
            results[policy.policy_id] = {
                "observed": False,
                "viable": False,
                "absent": True,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id,
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif protection_required:
            results[policy.policy_id] = {
                "observed": viable is not None or target_present_observed,
                "viable": viable is True,
                "completed_kill": False,
                "protection_required": "sanctuary",
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif hunt_without_confirmed_kill:
            # A positive consider proves only that the target was worth
            # probing. A research hunt is not viable until the runner records
            # the deliberate kill, even if the character dealt partial damage
            # before a safe withdrawal.
            result = {
                "observed": viable is not None or target_present_observed,
                "viable": False,
                "completed_kill": False,
                "boot_id": current.get("world_boot_id"),
            }
            if policy.execution == "source-ranked-hunt" and viable is not None:
                result["consider_viable"] = viable is True
            if unobserved_hunt:
                # A bounded hunt that never produced a live consideration did
                # not find a target to fight. Treat it as temporary absence so
                # the scheduler rotates to another policy instead of replaying
                # an empty, movement-expensive circuit immediately.
                result["absent"] = True
                result["unobserved"] = True
                retry_cooldown = _research_absence_retry_cooldown(
                    policy.policy_id
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy.policy_id] = retry_cooldown
            elif policy.execution == "source-ranked-hunt" and viable is False:
                # A negative live consider is terminal at this character
                # level and reboot. Do not attach a short route retry that
                # can later revive a below-band or over-ceiling target.
                absence_cooldowns.pop(policy.policy_id, None)
            else:
                previous_result = results.get(policy.policy_id)
                same_boot = bool(
                    current.get("world_boot_id") is not None
                    and (
                        previous_result is None
                        or (
                            isinstance(previous_result, dict)
                            and previous_result.get("boot_id")
                            == current.get("world_boot_id")
                        )
                    )
                )
                previously_productive = bool(
                    same_boot
                    and (
                        policy.policy_id
                        in _state_productive_policy_ids(previous)
                        or (
                            isinstance(previous_result, dict)
                            and previous_result.get("viable") is True
                            and previous_result.get("completed_kill") is not False
                        )
                    )
                )
                if previously_productive and viable is True:
                    # Preserve positive same-reboot history, but do not replay
                    # a route that just failed to finish its target.
                    result["retryable_failure"] = True
                    result["previously_productive"] = True
                    retry_cooldown = _research_absence_retry_cooldown(
                        policy.policy_id,
                        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                    )
                    absence_cooldowns[policy.policy_id] = retry_cooldown
                else:
                    # A present target that survived a bounded attempt needs
                    # the same short rotation as a previously productive one;
                    # otherwise the generic selector can immediately replay it.
                    if (
                        policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                        or policy.policy_id
                        == _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
                        or policy.policy_id
                        == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
                        or policy.policy_id
                        == _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
                        or policy.policy_id
                        in {
                            _FAME_RECOVERY_CIRCUS_POLICY.policy_id,
                            _FAME_RECOVERY_POLICY.policy_id,
                            _FAME_RECOVERY_LOTUS_POLICY.policy_id,
                        }
                    ):
                        result["retryable_failure"] = True
                        retry_cooldown = _research_absence_retry_cooldown(
                            policy.policy_id,
                            default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                        )
                        absence_cooldowns[policy.policy_id] = retry_cooldown
                    else:
                        absence_cooldowns.pop(policy.policy_id, None)
            results[policy.policy_id] = result
            recorded_current_result = True
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        else:
            result = {
                "observed": viable is not None,
                "viable": viable is True,
                "boot_id": current.get("world_boot_id"),
            }
            if policy.execution == "source-ranked-hunt":
                # Generated source-ranked routes need an explicit durable
                # distinction between a productive hunt and a viable probe.
                # Other objective-bearing policies may intentionally record
                # an acquisition without promoting it to XP progress.
                objective_kills = current.get("campaign_objective_kills")
                result["completed_kill"] = bool(objective_kills)
                total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
                    objective_kills
                )
                if objective_kills and explicit_xp:
                    result["objective_xp"] = total_xp
                    result["max_objective_kill_xp"] = max_kill_xp
                    if max_kill_xp < _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP:
                        result["low_reward"] = True
            if (
                policy.policy_id == _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
                and current.get("campaign_objective_kills")
            ):
                result["objective_kill"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        if current.get("campaign_died_during_segment"):
            # A target kill before death is still useful forensic evidence, but
            # it does not make the route viable: the net attempt lost XP and
            # must remain blocked until the level or reboot changes.
            objective_kills = current.get("campaign_objective_kills")
            total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
                objective_kills
            )
            fatal_result: dict[str, Any] = {
                "observed": True,
                "viable": False,
                "completed_kill": False,
                "fatal_failure": True,
                "boot_id": current.get("world_boot_id"),
                "level": _level(current),
            }
            if objective_kills:
                fatal_result["objective_kill_observed"] = True
            if objective_kills and explicit_xp:
                fatal_result["objective_xp"] = total_xp
                fatal_result["max_objective_kill_xp"] = max_kill_xp
            results[policy.policy_id] = fatal_result
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        if recorded_current_result:
            cleared_research_policies.discard(policy.policy_id)
    if results:
        merged["campaign_research_results"] = results
    if absence_cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if source_ranked_crowd_attempts:
        merged[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = (
            source_ranked_crowd_attempts
        )
    else:
        merged.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    if cleared_research_policies:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _source_ranked_circuit_policy_ids(
    candidate_record: object,
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Return the exact generated policies searched by one saved circuit."""
    records = _source_ranked_circuit_policy_records(
        candidate_record,
        primary_policy_id=primary_policy_id,
    )
    policy_ids = tuple(
        dict.fromkeys(
            str(record.get("policy_id") or "") for record in records
        )
    )
    return policy_ids or (primary_policy_id,)


def _restore_source_ranked_policy_metadata(
    previous: Mapping[str, Any],
    current: dict[str, Any],
    policy_id: str,
) -> dict[str, Any]:
    """Undo a circuit-wide merge for a primary stop that was not observed."""
    restored = dict(current)
    for key in (
        "campaign_research_results",
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
        _BELOW_BAND_POLICY_EXCLUSIONS_KEY,
        _BELOW_BAND_SIGHTINGS_KEY,
    ):
        current_records = dict(restored.get(key) or {})
        previous_records = previous.get(key)
        previous_record = (
            previous_records.get(policy_id)
            if isinstance(previous_records, Mapping)
            else None
        )
        current_record = current_records.get(policy_id)
        if previous_record is None:
            current_records.pop(policy_id, None)
        elif key != "campaign_research_results" or not isinstance(
            previous_record, Mapping
        ):
            current_records[policy_id] = previous_record
        else:
            restored_record = dict(previous_record)
            if (
                isinstance(current_record, Mapping)
                and current_record.get("consider_viable") is True
                and "consider_viable" not in restored_record
            ):
                # Confirmed-kill repair can recover a positive consideration
                # after this older circuit snapshot was written. Preserve
                # that newer evidence while still restoring the old primary
                # record's other circuit-owned fields.
                restored_record["consider_viable"] = True
            current_records[policy_id] = restored_record
        if current_records:
            restored[key] = current_records
        else:
            restored.pop(key, None)

    current_cleared = {
        str(value)
        for value in restored.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    previous_cleared = {
        str(value)
        for value in previous.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    explicit_retry_marker = restored.get(_EXPLICIT_RESEARCH_RETRY_KEY)
    explicitly_cleared = (
        isinstance(explicit_retry_marker, Mapping)
        and explicit_retry_marker.get("boot_id") == restored.get("world_boot_id")
        and policy_id
        in {
            str(value)
            for value in explicit_retry_marker.get("policy_ids", ())
        }
    )
    if policy_id in previous_cleared or explicitly_cleared:
        current_cleared.add(policy_id)
    else:
        current_cleared.discard(policy_id)
    if current_cleared:
        restored[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(current_cleared)
    else:
        restored.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return restored


def _merge_source_ranked_circuit_consider_results(
    previous: Mapping[str, Any],
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Persist each circuit consideration against its own source policy."""
    policy_ids = _source_ranked_circuit_policy_ids(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    if len(policy_ids) <= 1:
        return state
    outcomes = _source_ranked_consider_outcomes_by_policy(
        state,
        primary_policy_id=primary_policy_id,
    )
    if not outcomes:
        return state
    killed_policy_ids = set(_source_ranked_kill_policy_ids(objective_kills))
    merged = dict(state)
    if (
        primary_policy_id not in outcomes
        and primary_policy_id not in killed_policy_ids
    ):
        merged = _restore_source_ranked_policy_metadata(
            previous,
            merged,
            primary_policy_id,
        )

    results = _campaign_research_results(merged)
    previous_results = _campaign_research_results(dict(previous))
    absence_cooldowns = dict(
        merged.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        merged.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    crowd_attempts = dict(
        merged.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    )
    cleared = {
        str(value)
        for value in merged.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    boot_id = merged.get("world_boot_id")
    for policy_id, outcome in outcomes.items():
        if policy_id in killed_policy_ids:
            continue
        result: dict[str, Any] = {
            "observed": True,
            "viable": False,
            "completed_kill": False,
            "consider_viable": outcome,
            "boot_id": boot_id,
        }
        if outcome:
            result["retryable_failure"] = True
            previous_result = previous_results.get(policy_id)
            if (
                isinstance(previous_result, Mapping)
                and previous_result.get("boot_id") == boot_id
                and previous_result.get("viable") is True
                and previous_result.get("completed_kill") is not False
            ):
                result["previously_productive"] = True
            absence_cooldowns[policy_id] = (
                _research_absence_retry_cooldown(
                    policy_id,
                    default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                )
            )
        else:
            # The level-difference rejection is terminal for this level and
            # reboot. A short retry must never reopen it.
            absence_cooldowns.pop(policy_id, None)
        results[policy_id] = result
        crowd_cooldowns.pop(policy_id, None)
        crowd_attempts.pop(policy_id, None)
        cleared.discard(policy_id)

    merged["campaign_research_results"] = results
    for key, records in (
        (_RESEARCH_ABSENCE_COOLDOWN_KEY, absence_cooldowns),
        (_RESEARCH_CROWD_COOLDOWN_KEY, crowd_cooldowns),
        (_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, crowd_attempts),
    ):
        if records:
            merged[key] = records
        else:
            merged.pop(key, None)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _with_source_ranked_absence_results(
    state: dict[str, Any],
    policy_ids: Collection[str],
) -> dict[str, Any]:
    """Apply one reboot-scoped absence to exact generated policy identities."""
    unique_policy_ids = tuple(dict.fromkeys(str(value) for value in policy_ids))
    if not unique_policy_ids:
        return state
    merged = dict(state)
    boot_id = state.get("world_boot_id")
    results = _campaign_research_results(state)
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    crowd_attempts = dict(state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {})
    cleared = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    for policy_id in unique_policy_ids:
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        results[policy_id] = {
            "observed": False,
            "viable": False,
            "absent": True,
            "boot_id": boot_id,
        }
        retry_cooldown = _research_absence_retry_cooldown(policy_id)
        if retry_cooldown is not None:
            absence_cooldowns[policy_id] = retry_cooldown
        crowd_cooldowns.pop(policy_id, None)
        crowd_attempts.pop(policy_id, None)
        cleared.discard(policy_id)
    merged["campaign_research_results"] = results
    if absence_cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if crowd_attempts:
        merged[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = crowd_attempts
    else:
        merged.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _merge_source_ranked_circuit_absence_results(
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Cool down exact reset misses without hiding behind circuit presence."""
    crowd_abort_reason = str(
        state.get("campaign_fastwalk_abort_reason") or ""
    )
    crowded_field = bool(
        state.get("campaign_fastwalk_crowded")
        or any(
            crowd_abort_reason.startswith(prefix)
            for prefix in _FIELD_CROWD_ABORT_PREFIXES
        )
    )
    killed_policy_ids = set(_source_ranked_kill_policy_ids(objective_kills))
    present_policy_ids = set(
        _source_ranked_present_policy_ids(
            state,
            primary_policy_id=primary_policy_id,
        )
    )
    present_policy_ids.update(
        _source_ranked_consider_outcomes_by_policy(
            state,
            primary_policy_id=primary_policy_id,
        )
    )
    direct_absences = tuple(
        policy_id
        for policy_id in _source_ranked_absent_policy_ids(
            state,
            primary_policy_id=primary_policy_id,
        )
        if policy_id not in killed_policy_ids
        and policy_id not in present_policy_ids
        # The primary policy's exact room miss is secondary to a live crowd
        # decision for the dispatched circuit.  The research merger already
        # recorded the primary as crowded; replacing it with absence here
        # causes startup repair to flip the same evidence back to crowd.
        and not (crowded_field and policy_id == primary_policy_id)
    )
    if direct_absences:
        state = _with_source_ranked_absence_results(
            state,
            direct_absences,
        )
    if not state.get("campaign_fastwalk_target_absent"):
        return state
    if (
        state.get("campaign_fastwalk_target_present_observed")
        or state.get("campaign_fastwalk_consider_outcomes")
    ):
        # Presence anywhere in the dispatched circuit means the route was not
        # a complete empty search. Preserve the primary attempt and leave
        # unvisited supplementary resets open.
        return state
    if isinstance(objective_kills, (list, tuple)) and objective_kills:
        return state
    policy_ids = _source_ranked_circuit_policy_ids(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    if len(policy_ids) <= 1:
        return state
    return _with_source_ranked_absence_results(state, policy_ids)


def _repair_source_ranked_circuit_consider_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Repair old circuit outcomes that were assigned to the primary stop."""
    repaired = dict(state)
    confirmed_current_boot_results = {
        str(policy_id): dict(result)
        for policy_id, result in _campaign_research_results(state).items()
        if (
            isinstance(result, Mapping)
            and result.get("boot_id") == state.get("world_boot_id")
            and result.get("viable") is True
            and result.get("completed_kill") is True
        )
    }
    previously_productive_policy_ids = {
        str(policy_id)
        for policy_id, result in _campaign_research_results(state).items()
        if (
            isinstance(result, Mapping)
            and result.get("previously_productive") is True
        )
    }
    later_evidence: set[str] = set()
    boot_id = state.get("world_boot_id")
    for segment in reversed(tuple(segments)):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        segment_boot_id = end.get("world_boot_id")
        if boot_id and segment_boot_id and segment_boot_id != boot_id:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        evidence_state = dict(end)
        if isinstance(candidate_record, Mapping):
            evidence_state[_SOURCE_RANKED_CANDIDATE_KEY] = candidate_record
        outcomes = _source_ranked_consider_outcomes_by_policy(
            evidence_state,
            primary_policy_id=phase,
        )
        killed_policy_ids = set(
            _source_ranked_kill_policy_ids(
                end.get("campaign_objective_kills")
            )
        )
        actual_evidence = set(outcomes) | killed_policy_ids
        if not outcomes:
            later_evidence.update(actual_evidence or {phase})
            continue

        policy = replace(
            _SOURCE_RANKED_HUNT_POLICY,
            policy_id=phase,
            minimum_level=_level(end),
            maximum_level=_level(end),
        )
        corrected = _merge_campaign_below_band_policy_exclusions(
            dict(start),
            evidence_state,
            policy=policy,
            level=_level(end),
            boot_id=segment_boot_id or boot_id,
        )
        corrected = _merge_campaign_research_result(
            dict(start),
            corrected,
            policy=policy,
        )
        corrected = _merge_source_ranked_circuit_consider_results(
            start,
            corrected,
            end.get("campaign_objective_kills"),
            primary_policy_id=phase,
        )
        repair_policy_ids = {
            policy_id
            for policy_id in actual_evidence
            if policy_id not in later_evidence
        }
        if phase not in actual_evidence and phase not in later_evidence:
            repair_policy_ids.add(phase)
        for policy_id in repair_policy_ids:
            repaired = _restore_source_ranked_policy_metadata(
                corrected,
                repaired,
                policy_id,
            )
        later_evidence.update(actual_evidence)
        later_evidence.add(phase)
    if previously_productive_policy_ids:
        results = dict(_campaign_research_results(repaired))
        changed = False
        for policy_id in previously_productive_policy_ids:
            result = results.get(policy_id)
            if not isinstance(result, Mapping) or result.get(
                "consider_viable"
            ) is False:
                continue
            if result.get("previously_productive") is True:
                continue
            restored = dict(result)
            restored["previously_productive"] = True
            results[policy_id] = restored
            changed = True
        if changed:
            repaired["campaign_research_results"] = results
    if confirmed_current_boot_results:
        results = dict(_campaign_research_results(repaired))
        changed = False
        for policy_id, confirmed_result in confirmed_current_boot_results.items():
            current_result = results.get(policy_id)
            if not (
                isinstance(current_result, Mapping)
                and current_result.get("boot_id")
                == state.get("world_boot_id")
                and (
                    current_result.get("viable") is not True
                    or current_result.get("completed_kill") is not True
                )
            ):
                continue
            # A current-reboot confirmed objective kill is authoritative over
            # an older circuit migration that only reclassified a secondary
            # consider or no-kill outcome. Keeping it intact also makes the
            # startup repair converge instead of alternating on reconnect.
            results[policy_id] = confirmed_result
            changed = True
        if changed:
            repaired["campaign_research_results"] = results
    return repaired


def _repair_source_ranked_present_circuit_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Reverse pre-revision-149 absence propagation after a live sighting."""
    ordered_segments = tuple(segments)
    results = _campaign_research_results(state)
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    changed = False
    for index, segment in enumerate(ordered_segments):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not (
            end.get("campaign_fastwalk_target_absent") is True
            and end.get("campaign_fastwalk_target_present_observed") is True
            and not end.get("campaign_objective_kills")
        ):
            continue
        boot_id = end.get("world_boot_id") or state.get("world_boot_id")
        if (
            boot_id
            and state.get("world_boot_id")
            and boot_id != state.get("world_boot_id")
        ):
            continue
        policy_ids = _source_ranked_circuit_policy_ids(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=phase,
        )
        later_evidence: set[str] = set()
        for later_segment in ordered_segments[index + 1 :]:
            later_phase = str(later_segment["phase"] or "")
            try:
                later_end = json.loads(
                    later_segment["end_state_json"] or "{}"
                )
            except (TypeError, json.JSONDecodeError):
                continue
            later_boot = later_end.get("world_boot_id")
            if boot_id and later_boot and later_boot != boot_id:
                continue
            if later_phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                later_evidence.add(later_phase)
            later_evidence.update(
                _source_ranked_kill_policy_ids(
                    later_end.get("campaign_objective_kills")
                )
            )
        primary_result = results.get(phase)
        if (
            phase not in later_evidence
            and isinstance(primary_result, Mapping)
            and primary_result.get("absent") is True
            and primary_result.get("boot_id") == boot_id
        ):
            outcomes = end.get("campaign_fastwalk_consider_outcomes")
            consider_viable = bool(
                isinstance(outcomes, Mapping)
                and any(value is True for value in outcomes.values())
            )
            repaired_primary: dict[str, Any] = {
                "observed": True,
                "viable": False,
                "completed_kill": False,
                "retryable_failure": True,
                "boot_id": boot_id,
            }
            if isinstance(outcomes, Mapping) and outcomes:
                repaired_primary["consider_viable"] = consider_viable
            results[phase] = repaired_primary
            absence_cooldowns[phase] = _research_absence_retry_cooldown(
                phase,
                default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
            )
            changed = True
        for secondary_id in policy_ids[1:]:
            if secondary_id in later_evidence:
                continue
            secondary_result = results.get(secondary_id)
            if not (
                isinstance(secondary_result, Mapping)
                and secondary_result.get("absent") is True
                and secondary_result.get("boot_id") == boot_id
            ):
                continue
            results.pop(secondary_id, None)
            absence_cooldowns.pop(secondary_id, None)
            changed = True
    if not changed:
        return state
    repaired = dict(state)
    if results:
        repaired["campaign_research_results"] = results
    else:
        repaired.pop("campaign_research_results", None)
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    return repaired


def _repair_source_ranked_circuit_absence_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill secondary absences from pre-revision-147 circuit segments."""
    repaired = state
    ordered_segments = tuple(segments)
    for index, segment in enumerate(ordered_segments):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not (
            end.get("campaign_fastwalk_target_absent") is True
            and not end.get("campaign_fastwalk_target_present_observed")
            and not end.get("campaign_fastwalk_consider_outcomes")
            and not end.get("campaign_objective_kills")
        ):
            continue
        primary_result = _campaign_research_results(repaired).get(phase)
        if not (
            isinstance(primary_result, Mapping)
            and primary_result.get("absent") is True
            and primary_result.get("boot_id") == repaired.get("world_boot_id")
        ):
            continue
        try:
            remaining = int(
                (repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}).get(
                    phase
                )
                or 0
            )
        except (AttributeError, TypeError, ValueError):
            remaining = 0
        if remaining <= 0:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        if len(policy_ids) <= 1:
            continue
        later_evidence: set[str] = set()
        for later_segment in ordered_segments[index + 1 :]:
            later_phase = str(later_segment["phase"] or "")
            if later_phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                later_evidence.add(later_phase)
            try:
                later_end = json.loads(
                    later_segment["end_state_json"] or "{}"
                )
            except (TypeError, json.JSONDecodeError):
                continue
            later_evidence.update(
                _source_ranked_kill_policy_ids(
                    later_end.get("campaign_objective_kills")
                )
            )
        missing_absences = tuple(
            policy_id
            for policy_id in policy_ids[1:]
            if policy_id not in later_evidence
        )
        repaired = _with_source_ranked_absence_results(
            repaired,
            missing_absences,
        )
    return repaired


def _repair_source_ranked_partial_absence_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill exact misses from completed mixed-presence circuits."""
    repaired = state
    later_evidence: set[str] = set()
    current_boot_id = state.get("world_boot_id")
    for segment in reversed(tuple(segments)):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if str(segment["status"] or "") != "success":
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        boot_id = end.get("world_boot_id")
        if current_boot_id and boot_id and boot_id != current_boot_id:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        if len(policy_ids) <= 1:
            later_evidence.update(policy_ids)
            continue
        evidence_state = dict(end)
        evidence_state[_SOURCE_RANKED_CANDIDATE_KEY] = candidate_record
        outcomes = _source_ranked_consider_outcomes_by_policy(
            evidence_state,
            primary_policy_id=phase,
        )
        killed_policy_ids = set(
            _source_ranked_kill_policy_ids(
                end.get("campaign_objective_kills")
            )
        )
        direct_absences = set(
            _source_ranked_absent_policy_ids(
                evidence_state,
                primary_policy_id=phase,
            )
        )
        present_policy_ids = set(
            _source_ranked_present_policy_ids(
                evidence_state,
                primary_policy_id=phase,
            )
        )
        present_policy_ids.update(outcomes)
        direct_absences.difference_update(
            killed_policy_ids | present_policy_ids
        )
        actual_evidence = (
            set(outcomes)
            | killed_policy_ids
            | direct_absences
            | present_policy_ids
        )
        inferred_absences: set[str] = set(direct_absences)
        if (
            outcomes
            and not killed_policy_ids
            and not end.get("campaign_fastwalk_crowded")
            and not end.get("campaign_fastwalk_abort_reason")
        ):
            inferred_absences.update(set(policy_ids) - actual_evidence)
        inferred_absences.difference_update(later_evidence)
        if inferred_absences:
            repaired = _with_source_ranked_absence_results(
                repaired,
                sorted(inferred_absences),
            )
        later_evidence.update(actual_evidence)
    return repaired


def _merge_source_ranked_circuit_kill_results(
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Promote every source target that produced a tagged circuit kill."""
    killed_policy_ids = _source_ranked_kill_policy_ids(objective_kills)
    if not killed_policy_ids:
        return state

    merged = dict(state)
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    for policy_id in killed_policy_ids:
        result: dict[str, Any] = {
            "observed": True,
            "viable": True,
            "completed_kill": True,
            "consider_viable": True,
            "boot_id": boot_id,
        }
        policy_kills = [
            kill
            for kill in objective_kills
            if isinstance(kill, Mapping)
            and str(kill.get("source_policy_id") or "") == policy_id
        ]
        total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
            policy_kills
        )
        if explicit_xp:
            result["objective_xp"] = total_xp
            result["max_objective_kill_xp"] = max_kill_xp
        results[policy_id] = result

    # The generic research merger sees the circuit-wide kill list. Do not let
    # a secondary kill falsely promote an absent or rejected primary target.
    if primary_policy_id not in killed_policy_ids:
        primary_result = results.get(primary_policy_id)
        if isinstance(primary_result, Mapping):
            corrected = dict(primary_result)
            corrected["viable"] = False
            corrected["completed_kill"] = False
            corrected.pop("consider_viable", None)
            results[primary_policy_id] = corrected

    merged["campaign_research_results"] = results
    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
    ):
        records = dict(state.get(key) or {})
        for policy_id in killed_policy_ids:
            records.pop(policy_id, None)
        if records:
            merged[key] = records
        else:
            merged.pop(key, None)
    cleared = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.difference_update(killed_policy_ids)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _clear_completed_source_ranked_dispatch(
    state: dict[str, Any],
    objective_kills: object,
) -> dict[str, Any]:
    """Rebuild source circuits after a completed target changes the frontier."""
    if not isinstance(objective_kills, (list, tuple)) or not objective_kills:
        return state
    refreshed = dict(state)
    refreshed.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    return refreshed


def _run_has_crowded_field_decision(
    storage: RunStorage,
    run_id: int,
) -> bool:
    """Detect the old runner's durable decision evidence for a crowd."""
    for event in storage.list_events(run_id):
        if event["kind"] != "decision":
            continue
        try:
            payload = json.loads(event["payload_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        reason = str(payload.get("reason") or "").casefold()
        if (
            "crowded circuit target" in reason
            or "crowded field room" in reason
        ):
            return True
    return False


def _repair_crowded_field_metadata(
    storage: RunStorage,
    checkpoint: Any,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Migrate old multi-stop crowd runs that were mislabeled as absent."""
    if (
        checkpoint is None
        or not state.get("campaign_fastwalk_target_absent")
        or state.get("campaign_fastwalk_crowded")
        or state.get("campaign_objective_kills")
    ):
        return state
    run_id = checkpoint["run_id"]
    if run_id is None:
        return state
    try:
        run_id = int(run_id)
    except (TypeError, ValueError):
        return state
    if not _run_has_crowded_field_decision(storage, run_id):
        return state
    policy_id = str(state.get("campaign_last_policy") or "")
    if not policy_id:
        return state
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, dict) or result.get("absent") is not True:
        return state
    repaired = dict(state)
    results = dict(_campaign_research_results(state))
    results[policy_id] = {
        "observed": False,
        "viable": False,
        "crowded": True,
        "boot_id": result.get("boot_id") or state.get("world_boot_id"),
    }
    repaired["campaign_research_results"] = results
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    absence_cooldowns.pop(policy_id, None)
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    crowd_cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    crowd_cooldowns[policy_id] = _DEFAULT_RESEARCH_CROWD_COOLDOWN
    repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    repaired["campaign_fastwalk_target_absent"] = False
    repaired["campaign_fastwalk_crowded"] = True
    cleared = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.discard(policy_id)
    if cleared:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return repaired


def _repair_source_ranked_crowd_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Rehydrate a current-reboot crowd lost by an older restart repair."""
    boot_id = state.get("world_boot_id")
    if not boot_id:
        return state
    latest_by_policy: dict[str, tuple[str, Mapping[str, Any]]] = {}
    for segment in sorted(
        segments,
        key=lambda row: int(row["sequence"] or 0),
    ):
        policy_id = str(segment["phase"] or "")
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        if end_state.get("world_boot_id") != boot_id:
            continue
        latest_by_policy[policy_id] = (
            str(segment["status"] or ""),
            end_state,
        )

    results = dict(_campaign_research_results(state))
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    explicit_retry_policy_ids: set[str] = set()
    retry_marker = state.get(_EXPLICIT_RESEARCH_RETRY_KEY)
    if (
        isinstance(retry_marker, Mapping)
        and retry_marker.get("boot_id") == boot_id
    ):
        explicit_retry_policy_ids = {
            str(policy_id)
            for policy_id in retry_marker.get("policy_ids", ())
        }
    crowd_policy_ids: set[str] = set()
    absent_policy_ids: set[str] = set()
    changed = False
    for policy_id, (status, end_state) in latest_by_policy.items():
        if status not in {"ready", "success"}:
            continue
        abort_reason = str(
            end_state.get("campaign_fastwalk_abort_reason") or ""
        )
        crowd_signal = bool(
            end_state.get("campaign_fastwalk_crowded")
            or any(
                abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        )
        if not crowd_signal:
            if (
                end_state.get("campaign_fastwalk_target_absent") is True
                and not end_state.get(
                    "campaign_fastwalk_target_present_observed"
                )
                and not end_state.get("campaign_fastwalk_consider_outcomes")
            ):
                absent_policy_ids.add(policy_id)
            continue
        if policy_id in explicit_retry_policy_ids:
            # This route was deliberately retired by a same-reboot reset
            # retry. Preserve that decision; generic crowd migration must not
            # immediately reopen it on the next reconnect.
            continue
        crowd_policy_ids.add(policy_id)
        historical_result = _campaign_research_results(end_state).get(
            policy_id
        )
        current_result = results.get(policy_id)
        base_result = (
            current_result
            if isinstance(current_result, Mapping)
            and current_result.get("boot_id") == boot_id
            else historical_result
        )
        if (
            isinstance(base_result, Mapping)
            and base_result.get("viable") is True
            and base_result.get("completed_kill") is not False
        ):
            repaired_result = dict(base_result)
            repaired_result["crowded"] = True
        else:
            repaired_result = {
                "observed": False,
                "viable": False,
                "crowded": True,
                "boot_id": boot_id,
            }
            if isinstance(base_result, Mapping) and base_result.get(
                "crowd_exhausted"
            ) is True:
                repaired_result["crowd_exhausted"] = True
        if results.get(policy_id) != repaired_result:
            results[policy_id] = repaired_result
            changed = True
        absence_cooldowns.pop(policy_id, None)
        crowd_cooldowns[policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            int(crowd_cooldowns.get(policy_id) or 0),
        )
        if policy_id in cleared_research_policies:
            cleared_research_policies.discard(policy_id)
            changed = True

    current_policy_id = str(state.get("campaign_last_policy") or "")
    restore_current_absent_marker = bool(
        current_policy_id in absent_policy_ids
        and state.get("campaign_fastwalk_crowded")
    )
    if restore_current_absent_marker:
        results[current_policy_id] = {
            "observed": False,
            "viable": False,
            "absent": True,
            "boot_id": boot_id,
        }
        absence_cooldowns[current_policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            int(absence_cooldowns.get(current_policy_id) or 0),
        )
        crowd_cooldowns.pop(current_policy_id, None)
        cleared_research_policies.discard(current_policy_id)
        changed = True

    if not changed:
        return state
    repaired = dict(state)
    repaired["campaign_research_results"] = results
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    if cleared_research_policies:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    if restore_current_absent_marker:
        repaired["campaign_fastwalk_target_absent"] = True
        repaired["campaign_fastwalk_crowded"] = False
        repaired.pop("campaign_fastwalk_abort_reason", None)
    if repaired.get("campaign_last_policy") in crowd_policy_ids:
        repaired["campaign_fastwalk_target_absent"] = False
        repaired["campaign_fastwalk_crowded"] = True
    return repaired


def _clear_crowd_absence_marker(state: dict[str, Any]) -> dict[str, Any]:
    """Undo the old crowd-as-absence encoding without touching real absence."""
    reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    if not (
        state.get("campaign_fastwalk_crowded")
        or reason.startswith("field room contained ")
    ):
        return state
    policy_id = state.get("campaign_last_policy")
    if not isinstance(policy_id, str) or not policy_id:
        return state
    results = _campaign_research_results(state)
    result = results.get(policy_id)
    if not isinstance(result, dict) or not result.get("absent"):
        return state
    crowd_signal = bool(
        state.get("campaign_fastwalk_crowded")
        or reason.startswith("field room contained ")
    )
    if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) and crowd_signal:
        # Source-ranked field runs briefly used the old absent encoding for a
        # crowded room. Preserve that live crowd evidence instead of letting
        # startup migration erase its cooldown and reopen the same route.
        repaired = dict(state)
        source_result = dict(result)
        source_result.pop("absent", None)
        source_result.pop("unobserved", None)
        source_result.update(
            {
                "observed": False,
                "viable": False,
                "crowded": True,
                "boot_id": source_result.get("boot_id")
                or state.get("world_boot_id"),
            }
        )
        results[policy_id] = source_result
        repaired["campaign_research_results"] = results
        absence_cooldowns = dict(
            state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        )
        absence_remaining = int(absence_cooldowns.pop(policy_id, 0) or 0)
        if absence_cooldowns:
            repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
        else:
            repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        crowd_cooldowns = dict(
            state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
        )
        crowd_cooldowns[policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            absence_remaining,
            int(crowd_cooldowns.get(policy_id) or 0),
        )
        repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.discard(policy_id)
        if cleared_research_policies:
            repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
                cleared_research_policies
            )
        else:
            repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
        repaired["campaign_fastwalk_target_absent"] = False
        repaired["campaign_fastwalk_crowded"] = True
        return repaired
    results.pop(policy_id, None)
    repaired = dict(state)
    if results:
        repaired["campaign_research_results"] = results
    else:
        repaired.pop("campaign_research_results", None)
    cooldowns = dict(repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    cooldowns.pop(policy_id, None)
    if cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.add(policy_id)
    repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    repaired["campaign_fastwalk_target_absent"] = False
    repaired["campaign_fastwalk_crowded"] = False
    return repaired


def _clear_absent_research_results(
    state: dict[str, Any],
    *,
    except_policy_id: str,
) -> dict[str, Any]:
    """Retry missing or crowded reset targets after productive work elsewhere."""
    merged = dict(state)
    results = _campaign_research_results(state)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    crowd_cooldowns = dict(
        state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    retained: dict[str, dict[str, Any]] = {}
    expired_retryable_groups: set[frozenset[str]] = set()
    for policy_id, result in results.items():
        if policy_id == except_policy_id:
            retained[policy_id] = result
            continue
        if (
            result.get("consider_viable") is False
            and result.get("boot_id") == state.get("world_boot_id")
        ):
            # A live level-band rejection remains authoritative for this
            # reboot. Generic retry metadata must not age it back into use.
            retained[policy_id] = result
            cooldowns.pop(policy_id, None)
            continue
        if result.get("retryable_failure"):
            remaining = int(
                cooldowns.get(
                    policy_id,
                    _research_absence_retry_cooldown(
                        policy_id,
                        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                    ),
                )
                or 0
            )
            if remaining > 1:
                retained[policy_id] = result
                cooldowns[policy_id] = remaining - 1
            else:
                cooldowns.pop(policy_id, None)
                expired_retryable_groups.add(
                    _research_retryable_failure_group(policy_id)
                )
                cleared_research_policies.add(policy_id)
            continue
        if not result.get("absent"):
            retained[policy_id] = result
            continue
        remaining = int(cooldowns.get(policy_id) or 0)
        if remaining > 1:
            retained[policy_id] = result
            cooldowns[policy_id] = remaining - 1
        else:
            cooldowns.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    for policy_id, result in list(retained.items()):
        if (
            policy_id == except_policy_id
            or not result.get("crowded")
            or result.get("boot_id") != state.get("world_boot_id")
        ):
            continue
        remaining = int(
            crowd_cooldowns.get(policy_id)
            or _DEFAULT_RESEARCH_CROWD_COOLDOWN
        )
        if remaining > 1:
            crowd_cooldowns[policy_id] = remaining - 1
        else:
            crowd_cooldowns.pop(policy_id, None)
            retained.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    for retryable_group in expired_retryable_groups:
        for policy_id in retryable_group:
            retained.pop(policy_id, None)
            cooldowns.pop(policy_id, None)
            crowd_cooldowns.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    if retained:
        merged["campaign_research_results"] = retained
    else:
        merged.pop("campaign_research_results", None)
    if cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if cleared_research_policies:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _campaign_should_await_research_reset(state: dict[str, Any]) -> bool:
    """Allow a bounded reset wait for an absent target or dynamic hazard."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if not policy_id:
        return False
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    if not isinstance(cooldowns, dict):
        return False
    group = _research_absence_retry_group(policy_id)
    group_cooldown_active = any(
        int(cooldowns.get(candidate_id) or 0) > 0
        for candidate_id in group
    )
    if not group_cooldown_active:
        return False
    for candidate_id in group:
        result = results.get(candidate_id)
        if not isinstance(result, dict) or result.get("boot_id") != state.get(
            "world_boot_id"
        ):
            continue
        if not (
            result.get("absent") is True
            or result.get("route_hazard")
            == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
        ):
            continue
        return True
    return False


def _campaign_has_pending_dynamic_route_hazard(state: dict[str, Any]) -> bool:
    """Identify a current dynamic route hazard that is waiting for reset."""
    policy_id = str(state.get("campaign_last_policy") or "")
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, dict)
        and (
            result.get("route_hazard")
            == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
        )
        and result.get("boot_id") == state.get("world_boot_id")
    ):
        return False
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    return isinstance(cooldowns, dict) and int(cooldowns.get(policy_id) or 0) > 0


def _maintenance_failure_state(
    state: dict[str, Any],
    *,
    execution: str,
    boot_id: str | int | None = None,
    error: str | None = None,
) -> dict[str, Any]:
    """Prevent a failed optional equipment errand from looping at one level."""
    attempted_level_key = _MAINTENANCE_ATTEMPT_LEVEL_KEYS.get(execution)
    if attempted_level_key is None:
        if execution == "restock" and (
            error is None
            or any(
                marker in (error or "").casefold()
                for marker in (
                    "no pie after purchase",
                    "can't even afford",
                    "not enough money",
                    "unaffordable",
                )
            )
        ):
            failed_state = dict(state)
            failed_state[_PROVISION_FUNDING_REQUIRED_KEY] = True
            return failed_state
        return state
    failed_state = dict(state)
    failed_state[attempted_level_key] = _level(state)
    if execution == "recover-daycare-ring":
        failed_state[_DAYCARE_RING_COOLDOWN_KEY] = _DAYCARE_RING_COOLDOWN_SEGMENTS
        if boot_id is not None:
            failed_state[_DAYCARE_RING_ATTEMPT_BOOT_KEY] = boot_id
    if execution == "recover-war-dog-collar" and boot_id is not None:
        failed_state[_WAR_DOG_COLLAR_ATTEMPT_BOOT_KEY] = boot_id
    if execution == "recover-war-dog-collar":
        failed_state[_WAR_DOG_COLLAR_COOLDOWN_KEY] = (
            _WAR_DOG_COLLAR_COOLDOWN_SEGMENTS
        )
    if execution == "restock" and (
        error is None
        or any(
            marker in error.casefold()
            for marker in (
                "no pie after purchase",
                "can't even afford",
                "not enough money",
                "unaffordable",
            )
        )
    ):
        failed_state[_PROVISION_FUNDING_REQUIRED_KEY] = True
    return failed_state


def _repair_failed_flight_funding_state(
    state: dict[str, Any],
    checkpoint: Any,
) -> dict[str, Any]:
    """Re-arm one pre-withdrawal funding failure after its bank fix."""
    if (
        checkpoint is None
        or checkpoint["reason"] != "segment_failed"
        or checkpoint["phase"] != "borrow-flight-potion"
        or not state.get("campaign_flight_loan_attempted")
        or state.get("campaign_flight_funding_repair_applied")
    ):
        return state
    repaired = dict(state)
    repaired["campaign_flight_loan_attempted"] = False
    repaired["campaign_flight_funding_repair_applied"] = True
    return repaired


def _repair_exhausted_flight_funding_state(
    state: dict[str, Any],
    *,
    has_sellable_loot: bool | None = None,
) -> dict[str, Any]:
    """Re-arm funding after a used flight reserve expires without cash."""
    affects = state.get("affects")
    if (
        affects is None
        or not state.get("campaign_flight_loan_attempted")
        or any(
            _state_has_active_affect(affects, effect)
            for effect in ("fly", "levitation")
        )
    ):
        return state
    if state.get(_FLIGHT_FUNDING_RETRY_KEY):
        if (
            has_sellable_loot is False
            and _state_copper_value(state) < _flight_purchase_minimum(state)
        ):
            if state.get(_FLIGHT_FUNDING_REQUIRED_KEY):
                return state
            repaired = dict(state)
            repaired[_FLIGHT_FUNDING_REQUIRED_KEY] = True
            return repaired
        if not state.get(_FLIGHT_FUNDING_REQUIRED_KEY):
            return state
        repaired = dict(state)
        repaired.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        return repaired
    if (
        state.get(_FLIGHT_FUNDING_REQUIRED_KEY)
        or _state_copper_value(state) >= _flight_purchase_minimum(state)
    ):
        return state
    repaired = dict(state)
    repaired[_FLIGHT_FUNDING_REQUIRED_KEY] = True
    return repaired


def _newer_progress_state(
    checkpoint: dict[str, Any],
    live: dict[str, Any] | None,
) -> dict[str, Any]:
    if not live:
        return checkpoint
    if not _progress_state_is_valid(live):
        return checkpoint
    if (
        isinstance(live.get("level"), (int, float))
        and isinstance(live.get("xp"), (int, float))
    ):
        merged = {**checkpoint, **live}
        if checkpoint:
            # The live character snapshot can predate a metadata-only
            # checkpoint. Campaign policy, cooldown, and equipment facts are
            # owned by that durable checkpoint; only live game progress and
            # protocol state should override it here.
            for key in _CAMPAIGN_STICKY_METADATA_KEYS:
                if key in checkpoint:
                    merged[key] = checkpoint[key]
                else:
                    merged.pop(key, None)
        _preserve_verified_progress_on_unexplained_regression(
            checkpoint,
            live,
            merged,
        )
        if (
            merged.get("dead")
            and str(merged.get("area", "")).casefold() != "purgatory"
            and _numeric_progress(merged, "hp") > 0
        ):
            merged["dead"] = False
        return merged
    checkpoint_progress = (_level(checkpoint), _numeric_progress(checkpoint, "xp"))
    live_progress = (_level(live), _numeric_progress(live, "xp"))
    return {**checkpoint, **live} if live_progress >= checkpoint_progress else checkpoint


def _numeric_progress(state: dict[str, Any], key: str) -> int:
    value = state.get(key)
    return int(value) if isinstance(value, (int, float)) else 0


def _state_fame(state: Mapping[str, Any]) -> int | None:
    """Return the current GMCP fame value when it is present."""
    stats = state.get("stats")
    if isinstance(stats, Mapping):
        fame = stats.get("fame")
        try:
            return int(fame)
        except (TypeError, ValueError):
            pass
    fame = state.get("fame")
    try:
        return int(fame) if fame is not None else None
    except (TypeError, ValueError):
        return None


def _shop_rearm_blocked_by_reputation(state: Mapping[str, Any]) -> bool:
    """Prefer current GMCP fame over a prior textual shop refusal."""
    fame = _state_fame(state)
    if fame is not None:
        return fame < 0
    return bool(state.get(_SHOP_REARM_REPUTATION_BLOCKED_KEY))


def _run_has_unrecovered_weapon_loss(
    storage: RunStorage,
    run_id: int,
) -> bool:
    """Reconstruct the final weapon state for legacy or interrupted runs."""
    primary_weapon = _replay_run_equipment(storage, run_id).primary_weapon
    return primary_weapon is not None and not bool(
        primary_weapon[0] and primary_weapon[1]
    )


def _latest_character_run(
    storage: RunStorage,
    character_name: str,
) -> Any | None:
    """Return the latest conventionally named runner for one character."""
    suffixes = (
        f":{character_name}".casefold(),
        f"-{character_name}".casefold(),
    )
    return next(
        (
            run
            for run in storage.list_runs(limit=1000)
            if str(run["scenario_name"]).casefold().endswith(suffixes)
        ),
        None,
    )


def _latest_new_character_run(
    storage: RunStorage,
    character_name: str,
    prior_run_ids: Collection[int],
) -> Any | None:
    """Return the newest named run created during the current segment."""
    prior = {int(run_id) for run_id in prior_run_ids}
    suffixes = (
        f":{character_name}".casefold(),
        f"-{character_name}".casefold(),
    )
    return next(
        (
            run
            for run in storage.list_runs(limit=1000)
            if int(run["id"]) not in prior
            and str(run["scenario_name"]).casefold().endswith(suffixes)
        ),
        None,
    )


def _run_latest_state(storage: RunStorage, run_id: int) -> dict[str, Any] | None:
    """Return the last character snapshot recorded by one run."""
    snapshot = storage.get_latest_state_snapshot(run_id)
    if snapshot is None:
        return None
    try:
        state = json.loads(snapshot["state_json"])
    except (TypeError, json.JSONDecodeError):
        return None
    return dict(state) if isinstance(state, dict) else None


def _run_successful_vault_lodges(
    storage: RunStorage,
    run_id: int,
) -> tuple[str, ...]:
    """Return command keywords for vault lodges acknowledged by DD4."""
    lodged: list[str] = []
    pending_keyword: str | None = None
    for event in storage.list_events(run_id):
        payload = json.loads(event["payload_json"])
        if event["kind"] == "command":
            command = str(payload.get("command", "")).strip().casefold()
            pending_keyword = (
                command.removeprefix("lodge ")
                if command.startswith("lodge ")
                else None
            )
            continue
        if event["kind"] != "response" or pending_keyword is None:
            continue
        response = _ANSI_ESCAPE.sub(
            "",
            str(payload.get("text", "")),
        ).casefold()
        if "you lodge " in response and " in your vault." in response:
            lodged.append(pending_keyword)
        pending_keyword = None
    return tuple(dict.fromkeys(lodged))


@dataclass
class _RunEquipmentReplay:
    empty_categories: set[str] | None = None
    worn_descriptions: list[str] | None = None
    primary_weapon: tuple[bool, str | None] | None = None


def _complete_worn_snapshot(payload: Mapping[str, Any]) -> Any | None:
    """Return the value from a complete GMCP Char.Worn event."""
    if payload.get("type") != "equipment_changed":
        return None
    data = payload.get("data")
    if not isinstance(data, Mapping):
        return None
    if str(data.get("package", "")).casefold() != "char.worn":
        return None
    value = data.get("value", [])
    if isinstance(value, str):
        try:
            return json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return None
    return value


def _structured_worn_descriptions(value: Any) -> list[str]:
    """Extract occupied-slot descriptions from a structured worn snapshot."""
    if isinstance(value, list):
        descriptions: list[str] = []
        for item in value:
            descriptions.extend(_structured_worn_descriptions(item))
        return descriptions
    if not isinstance(value, Mapping):
        return []
    if "slot" in value or "wear_loc" in value:
        description = value.get("name", value.get("short_desc"))
        if description is None:
            return []
        cleaned = _ANSI_ESCAPE.sub("", str(description)).strip()
        return [_strip_live_selector(cleaned)] if cleaned else []
    descriptions = []
    for item in value.values():
        if isinstance(item, (list, Mapping)):
            descriptions.extend(_structured_worn_descriptions(item))
    return descriptions


def _replay_run_equipment(
    storage: RunStorage,
    run_id: int,
) -> _RunEquipmentReplay:
    """Replay authoritative worn snapshots plus later confirmed slot changes."""
    result = _RunEquipmentReplay()
    weapon_description: str | None = None
    structured_current = False
    awaiting_audit = False

    def set_weapon(present: bool, description: str | None) -> None:
        nonlocal weapon_description
        cleaned = (
            _strip_live_selector(description)
            if description is not None
            else None
        )
        if result.worn_descriptions is not None and weapon_description is not None:
            result.worn_descriptions = [
                item
                for item in result.worn_descriptions
                if item != weapon_description
            ]
        weapon_description = cleaned if present else None
        result.primary_weapon = (bool(present and cleaned), weapon_description)
        if result.worn_descriptions is not None and weapon_description is not None:
            result.worn_descriptions.append(weapon_description)
        if result.empty_categories is not None:
            if weapon_description is not None:
                result.empty_categories.discard("wield")
            else:
                result.empty_categories.add("wield")

    for event in storage.list_events(run_id):
        payload = json.loads(event["payload_json"])
        kind = event["kind"]
        if kind == "command":
            command = str(payload.get("command", "")).strip().casefold()
            if command in {"equipment", "eq all"}:
                awaiting_audit = True
            if command == "wear all" or command.startswith(
                ("wear ", "remove ", "wield ", "hold ")
            ):
                structured_current = False
            continue
        if kind == "game_event":
            snapshot = _complete_worn_snapshot(payload)
            if snapshot is None:
                continue
            result.worn_descriptions = _structured_worn_descriptions(snapshot)
            weapon_seen, structured_description = _equipment_weapon_from_payload(
                snapshot
            )
            weapon_description = (
                _strip_live_selector(structured_description)
                if weapon_seen and structured_description is not None
                else None
            )
            result.primary_weapon = (
                weapon_description is not None,
                weapon_description,
            )
            if result.empty_categories is not None:
                if weapon_description is None:
                    result.empty_categories.add("wield")
                else:
                    result.empty_categories.discard("wield")
            structured_current = True
            continue
        if kind != "response":
            continue

        response = str(payload.get("text", ""))
        if awaiting_audit and _equipment_audit_present(response):
            empty_categories = _equipment_empty_categories(response)
            if structured_current:
                if result.primary_weapon and result.primary_weapon[1] is not None:
                    empty_categories.discard("wield")
                else:
                    empty_categories.add("wield")
            else:
                result.worn_descriptions = [
                    _strip_live_selector(description)
                    for description in _equipment_audit_descriptions(response)
                ]
                weapon_seen, audited_description = _equipment_weapon_slot(response)
                weapon_description = (
                    _strip_live_selector(audited_description)
                    if weapon_seen and audited_description is not None
                    else None
                )
                result.primary_weapon = (
                    weapon_description is not None,
                    weapon_description,
                )
            result.empty_categories = empty_categories
            awaiting_audit = False

        acknowledgement = _direct_weapon_slot_acknowledgement(response)
        if acknowledgement is not None:
            structured_current = False
            set_weapon(acknowledgement[0], acknowledgement[1])
        folded = _ANSI_ESCAPE.sub("", response).casefold()
        if (
            "disarms you" in folded
            or "your weapon slips from your hand" in folded
        ):
            structured_current = False
            set_weapon(False, None)
    return result


def _run_equipment_empty_categories(
    storage: RunStorage,
    run_id: int,
) -> set[str] | None:
    """Return the newest empty categories from structured and text evidence."""
    return _replay_run_equipment(storage, run_id).empty_categories


def _run_worn_equipment_descriptions(
    storage: RunStorage,
    run_id: int,
) -> list[str] | None:
    """Return occupied equipment from structured and text evidence."""
    return _replay_run_equipment(storage, run_id).worn_descriptions


def _direct_weapon_slot_acknowledgement(
    response: str,
) -> tuple[bool, str | None] | None:
    """Extract a direct wield or stop-using acknowledgement from game text."""
    wielded = re.search(
        r"(?im)^\s*you wield\s+(?P<item>.+?)(?:[.!]\s*$|\s*$)",
        response,
    )
    if wielded is not None:
        return True, wielded.group("item").strip()
    if re.search(r"(?im)^\s*you stop using\s+", response):
        return False, None
    return None


_LIVE_SELECTOR_PREFIX = re.compile(r"^\s*\[#\d+\]\s*")


def _strip_live_selector(description: str) -> str:
    """Remove a connection-scoped TARGETMODE selector before persistence."""
    return _LIVE_SELECTOR_PREFIX.sub("", description).strip()


def _run_primary_weapon_slot(
    storage: RunStorage,
    run_id: int,
) -> tuple[bool, str | None] | None:
    """Return the newest observed primary weapon state, if one was recorded."""
    return _replay_run_equipment(storage, run_id).primary_weapon


def _research_absence_retry_group(policy_id: str) -> frozenset[str]:
    """Return the probe/hunt identities that share one reset target."""
    if policy_id in _MORIA_SANCTUARY_RESEARCH_POLICY_IDS:
        return _MORIA_SANCTUARY_RESEARCH_POLICY_IDS
    if policy_id in {
        _NOBLEMAN_LEVEL_SEVENTEEN_HUNT_POLICY_ID,
        _NOBLEMAN_LEVEL_SEVENTEEN_PROBE_POLICY_ID,
    }:
        return frozenset(
            {
                policy_id,
                _NOBLEMAN_LEVEL_SEVENTEEN_HUNT_POLICY_ID,
                _NOBLEMAN_LEVEL_SEVENTEEN_PROBE_POLICY_ID,
            }
        )
    if policy_id in {_SOLACE_MAGNUS_POLICY_ID, _SOLACE_MAGNUS_HUNT_POLICY_ID}:
        return frozenset({_SOLACE_MAGNUS_POLICY_ID, _SOLACE_MAGNUS_HUNT_POLICY_ID})
    return frozenset({policy_id})


